#!/usr/bin/env python3
"""
SQL Injection Scanner
Automates detection of SQL injection vulnerabilities
"""

import requests
import time
from urllib.parse import urljoin

class SQLInjectionScanner:
    def __init__(self, target_url):
        self.target_url = target_url
        self.vulnerable_endpoints = []

        # Common SQL injection payloads
        self.payloads = [
            "' OR '1'='1",
            "' OR '1'='1' --",
            "' UNION SELECT null, version() --",
            "'; WAITFOR DELAY '00:00:05' --",
            "1' AND SLEEP(5) --",
            "1' OR 1=1 --",
            "1' AND (SELECT * FROM users) --"
        ]

    def test_parameter(self, endpoint, param_name, param_value):
        """Test a single parameter for SQL injection"""
        url = urljoin(self.target_url, endpoint)

        for payload in self.payloads:
            # Test with payload
            test_value = param_value + payload
            params = {param_name: test_value}

            try:
                start_time = time.time()
                response = requests.get(url, params=params, timeout=10)
                elapsed_time = time.time() - start_time

                # Check for indicators of SQL injection
                indicators = [
                    "sql syntax",
                    "mysql",
                    "postgresql",
                    "oracle",
                    "database",
                    "unclosed quotation",
                    "syntax error"
                ]

                # Time-based detection
                if elapsed_time > 5:  # Potential time-based SQLi
                    return {"vulnerable": True, "type": "time-based", "payload": payload}

                # Error-based detection
                if any(indicator in response.text.lower() for indicator in indicators):
                    return {"vulnerable": True, "type": "error-based", "payload": payload}

            except requests.exceptions.Timeout:
                return {"vulnerable": True, "type": "timeout", "payload": payload}
            except Exception as e:
                print(f"Error testing {url}: {e}")

        return {"vulnerable": False}

    def scan_endpoint(self, endpoint, parameters):
        """Scan an endpoint with multiple parameters"""
        results = {}
        for param_name, param_value in parameters.items():
            result = self.test_parameter(endpoint, param_name, param_value)
            if result["vulnerable"]:
                results[param_name] = result

        if results:
            self.vulnerable_endpoints.append({
                "endpoint": endpoint,
                "parameters": results
            })

        return results

# Example usage
if __name__ == "__main__":
    scanner = SQLInjectionScanner("http://testphp.vulnweb.com")

    # Test login endpoint
    results = scanner.scan_endpoint("/login.php", {
        "uname": "test",
        "pass": "password123"
    })

    if scanner.vulnerable_endpoints:
        print("Vulnerabilities found:")
        for vuln in scanner.vulnerable_endpoints:
            print(f"  {vuln['endpoint']}: {vuln['parameters']}")
    else:
        print("No SQL injection vulnerabilities detected.")

#!/usr/bin/env python3
"""
Security Headers Validator
Checks for proper security headers configuration
"""

import requests
from urllib.parse import urljoin

class SecurityHeadersValidator:
    def __init__(self):
        # Required security headers and their expected values
        self.required_headers = {
            "X-Content-Type-Options": ["nosniff"],
            "X-Frame-Options": ["DENY", "SAMEORIGIN"],
            "X-XSS-Protection": ["1; mode=block"],
            "Strict-Transport-Security": [],  # Any value is better than none
            "Content-Security-Policy": [],     # Any value is better than none
            "Referrer-Policy": ["no-referrer", "strict-origin-when-cross-origin"],
            "Permissions-Policy": []          # Modern replacement for Feature-Policy
        }

        self.findings = []

    def check_headers(self, url):
        """Check security headers for a given URL"""
        try:
            response = requests.get(url, timeout=10, allow_redirects=True)
            headers = response.headers

            for header, expected_values in self.required_headers.items():
                header_value = headers.get(header)

                if not header_value:
                    self.findings.append({
                        "url": url,
                        "header": header,
                        "status": "MISSING",
                        "severity": "HIGH" if header in ["X-Content-Type-Options", "X-Frame-Options"] else "MEDIUM",
                        "recommendation": f"Add {header} header"
                    })
                elif expected_values and header_value not in expected_values:
                    self.findings.append({
                        "url": url,
                        "header": header,
                        "status": "MISCONFIGURED",
                        "value": header_value,
                        "expected": expected_values,
                        "severity": "MEDIUM",
                        "recommendation": f"Update {header} to one of: {', '.join(expected_values)}"
                    })
                else:
                    self.findings.append({
                        "url": url,
                        "header": header,
                        "status": "OK",
                        "value": header_value,
                        "severity": "LOW"
                    })

            # Check for deprecated headers
            deprecated_headers = ["X-Powered-By", "Server"]
            for dep_header in deprecated_headers:
                if dep_header in headers:
                    self.findings.append({
                        "url": url,
                        "header": dep_header,
                        "status": "DEPRECATED",
                        "value": headers[dep_header],
                        "severity": "LOW",
                        "recommendation": f"Remove {dep_header} header"
                    })

            # Check HSTS configuration
            hsts = headers.get("Strict-Transport-Security")
            if hsts:
                if "max-age=0" in hsts:
                    self.findings.append({
                        "url": url,
                        "header": "Strict-Transport-Security",
                        "status": "INSECURE",
                        "value": hsts,
                        "severity": "HIGH",
                        "recommendation": "HSTS max-age should be at least 31536000 seconds (1 year)"
                    })
                elif "max-age=" in hsts and "includeSubDomains" not in hsts:
                    self.findings.append({
                        "url": url,
                        "header": "Strict-Transport-Security",
                        "status": "WARNING",
                        "value": hsts,
                        "severity": "MEDIUM",
                        "recommendation": "Consider adding includeSubDomains directive"
                    })

        except Exception as e:
            self.findings.append({
                "url": url,
                "status": "ERROR",
                "error": str(e),
                "severity": "HIGH"
            })

    def generate_report(self):
        """Generate security headers report"""
        report = {
            "summary": {
                "total_checks": len(self.findings),
                "missing_headers": sum(1 for f in self.findings if f["status"] == "MISSING"),
                "misconfigured_headers": sum(1 for f in self.findings if f["status"] == "MISCONFIGURED"),
                "secure_headers": sum(1 for f in self.findings if f["status"] == "OK")
            },
            "findings": self.findings
        }
        return report

# Example usage
if __name__ == "__main__":
    validator = SecurityHeadersValidator()

    # Test URLs
    test_urls = [
        "https://example.com",
        "https://httpbin.org/headers"
    ]

    for url in test_urls:
        print(f"\nChecking security headers for: {url}")
        validator.check_headers(url)

    report = validator.generate_report()

    print("\n=== Security Headers Report ===")
    print(f"Total checks: {report['summary']['total_checks']}")
    print(f"Missing headers: {report['summary']['missing_headers']}")
    print(f"Misconfigured headers: {report['summary']['misconfigured_headers']}")
    print(f"Secure headers: {report['summary']['secure_headers']}")

    print("\n=== Detailed Findings ===")
    for finding in report["findings"]:
        if finding["status"] != "OK":
            print(f"\nURL: {finding['url']}")
            print(f"Header: {finding.get('header', 'N/A')}")
            print(f"Status: {finding['status']}")
            print(f"Severity: {finding['severity']}")
            if 'value' in finding:
                print(f"Current Value: {finding['value']}")
            if 'recommendation' in finding:
                print(f"Recommendation: {finding['recommendation']}")

