        cart_data = {
            "items": [{"id": 1, "quantity": 999999, "price": 10}],
            "total": 9999990
        }

        try:
            response = self.session.post(
                self.base_url + "/api/cart/checkout",
                json=cart_data,
                timeout=5
            )

            if response.status_code == 200:
                cart_tests.append("Excessive quantity accepted")
        except Exception:
            pass

        # Test 3: Price mismatch
        cart_data = {
            "items": [{"id": 1, "quantity": 1, "price": 0.01}],
            "total": 100.00  # Different from calculated
        }

        try:
            response = self.session.post(
                self.base_url + "/api/cart/checkout",
                json=cart_data,
                timeout=5
            )

            if response.status_code == 200:
                cart_tests.append("Price mismatch not validated")
        except Exception:
            pass

        if cart_tests:
            self.log_result(
                test_name,
                "FAIL",
                f"Business logic flaws: {', '.join(cart_tests)}",
                "HIGH"
            )
        else:
            self.log_result(test_name, "PASS", "No business logic flaws detected")

    def test_api_rate_limiting(self):
        """Test for missing or weak rate limiting"""
        test_name = "API Rate Limiting"

        endpoint = self.base_url + "/api/login"
        requests_count = 50
        successful_requests = 0

        for i in range(requests_count):
            try:
                response = self.session.post(
                    endpoint,
                    json={"username": f"test{i}", "password": "password"},
                    timeout=2
                )

                if response.status_code == 200:
                    successful_requests += 1

            except Exception:
                continue

        if successful_requests == requests_count:
            self.log_result(
                test_name,
                "FAIL",
                f"No rate limiting detected ({requests_count} successful requests)",
                "MEDIUM"
            )
        else:
            blocked_requests = requests_count - successful_requests
            self.log_result(
                test_name,
                "PASS",
                f"Rate limiting working ({blocked_requests} requests blocked)"
            )

    def run_all_tests(self):
        """Run all custom security tests"""
        print(f"\n=== Running Custom Security Tests for {self.base_url} ===\n")

        tests = [
            self.test_authentication_bypass,
            self.test_idor,
            self.test_business_logic_flaws,
            self.test_api_rate_limiting
        ]

        for test in tests:
            test()

        return self.generate_report()

    def generate_report(self):
        """Generate test report"""
        total_tests = len(self.results)
        passed_tests = sum(1 for r in self.results if r["status"] == "PASS")
        failed_tests = total_tests - passed_tests

        # Count by severity
        severity_counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}
        for result in self.results:
            if result["status"] == "FAIL":
                severity = result["severity"]
                severity_counts[severity] = severity_counts.get(severity, 0) + 1

        report = {
            "summary": {
                "total_tests": total_tests,
                "passed": passed_tests,
                "failed": failed_tests,
                "severity_breakdown": severity_counts
            },
            "results": self.results,
            "timestamp": datetime.now().isoformat()
        }

        print(f"\n=== Test Summary ===")
        print(f"Total Tests: {total_tests}")
        print(f"Passed: {passed_tests}")
        print(f"Failed: {failed_tests}")

        if failed_tests > 0:
            print(f"\nSeverity Breakdown:")
            for severity, count in severity_counts.items():
                if count > 0:
                    print(f"  {severity}: {count}")

        return report

# Example usage
if __name__ == "__main__":
    # Initialize with target URL
    tester = CustomSecurityTests("http://testphp.vulnweb.com")

    # Run all tests
    report = tester.run_all_tests()

    # Save report to file
    with open("custom_security_report.json", "w") as f:
        json.dump(report, f, indent=2)

    print(f"\nReport saved to custom_security_report.json")

#!/usr/bin/env python3
"""
Simple SAST Scanner for Python Code
Detects common security vulnerabilities in Python source code
"""

import ast
import os
import re
from pathlib import Path

class SimpleSASTScanner:
    def __init__(self):
        self.vulnerabilities = []
        self.patterns = self.load_security_patterns()

    def load_security_patterns(self):
        """Load security vulnerability patterns"""
        patterns = {
            "sql_injection": [
                (r"execute\(.*\+.*\)", "String concatenation in SQL execution"),
                (r"cursor\.execute\(.*%.*%\)", "String formatting in SQL execution"),
                (r"\.format\(.*SELECT.*\)", "String formatting with SQL query"),
                (r"f'SELECT.*{.*}'", "f-string with SQL query")
            ],
            "command_injection": [
                (r"os\.system\(.*\+.*\)", "String concatenation in os.system"),
                (r"subprocess\.call\(.*\+.*\)", "String concatenation in subprocess"),
                (r"subprocess\.Popen\(.*\+.*\)", "String concatenation in Popen"),
                (r"eval\(.*input.*\)", "eval with user input")
            ],
            "xss": [
                (r"Flask\.render_template_string\(.*request\.form.*\)", 
                 "User input in render_template_string"),
                (r"return.*\+.*request\.args.*", "User input in response"),
                (r"make_response\(.*\+.*request\.*\).*\)", "User input in response")
            ],
            "hardcoded_secrets": [
                (r"password\s*=\s*['\"].*['\"]", "Hardcoded password"),
                (r"api_key\s*=\s*['\"].*['\"]", "Hardcoded API key"),
                (r"secret\s*=\s*['\"].*['\"]", "Hardcoded secret"),
                (r"token\s*=\s*['\"].*['\"]", "Hardcoded token"),
                (r"AUTH_TOKEN\s*=\s*['\"].*['\"]", "Hardcoded auth token")
            ],
            "insecure_deserialization": [
                (r"pickle\.loads\(.*\)", "Pickle deserialization"),
                (r"yaml\.load\(.*\)", "YAML load without safe loader"),
                (r"json\.loads\(.*request\.*\)", "JSON load with user input")
            ],
            "file_operations": [
                (r"open\(.*\+.*\)", "String concatenation in file path"),
                (r"\.write\(.*request\.files.*\)", "User file upload without validation")
            ]
        }
        return patterns

    def scan_file(self, filepath):
        """Scan a single Python file"""
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                content = f.read()

            # Get AST for more advanced analysis
            try:
                tree = ast.parse(content)
                self.analyze_ast(tree, filepath)
            except SyntaxError:
                print(f"Syntax error in {filepath}, using regex only")

            # Pattern-based scanning
            self.pattern_scan(content, filepath)

        except Exception as e:
            print(f"Error scanning {filepath}: {e}")

    def pattern_scan(self, content, filepath):
        """Scan content using regex patterns"""
        lines = content.split('\n')

        for category, patterns in self.patterns.items():
            for pattern, description in patterns:
                matches = re.finditer(pattern, content, re.IGNORECASE)
                for match in matches:
                    # Find line number
                    line_no = content[:match.start()].count('\n') + 1
                    line_content = lines[line_no - 1].strip() if line_no <= len(lines) else ""

                    self.vulnerabilities.append({
                        "file": str(filepath),
                        "line": line_no,
                        "category": category,
                        "description": description,
                        "code_snippet": line_content[:100],
                        "severity": self.get_severity(category),
                        "type": "PATTERN"
                    })

    def analyze_ast(self, tree, filepath):
        """Analyze AST for security issues"""
        for node in ast.walk(tree):
            # Check for dangerous function calls
            if isinstance(node, ast.Call):
                self.check_dangerous_call(node, filepath)

            # Check for assignments with hardcoded secrets
            if isinstance(node, ast.Assign):
                self.check_hardcoded_secrets(node, filepath)

    def check_dangerous_call(self, node, filepath):
        """Check for dangerous function calls"""
        dangerous_funcs = {
            "eval": "HIGH",
            "exec": "HIGH",
            "pickle.loads": "HIGH",
            "os.system": "HIGH",
            "subprocess.call": "MEDIUM",
            "subprocess.Popen": "MEDIUM"
        }

        if isinstance(node.func, ast.Name):
            func_name = node.func.id
            if func_name in dangerous_funcs:
                # Get line number
                line_no = node.lineno if hasattr(node, 'lineno') else 0

                self.vulnerabilities.append({
                    "file": str(filepath),
                    "line": line_no,
                    "category": "dangerous_function",
                    "description": f"Dangerous function call: {func_name}",
                    "severity": dangerous_funcs[func_name],
                    "type": "AST"
                })

    def check_hardcoded_secrets(self, node, filepath):
        """Check for hardcoded secrets in assignments"""
        secret_keywords = [
            "password", "secret", "token", "key", "credential",
            "api_key", "auth_token", "private_key", "client_secret"
        ]

        for target in node.targets:
            if isinstance(target, ast.Name):
                var_name = target.id.lower()

                # Check if variable name suggests a secret
                if any(keyword in var_name for keyword in secret_keywords):
                    # Check if value is a string constant
                    if isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
                        line_no = node.lineno if hasattr(node, 'lineno') else 0

                        self.vulnerabilities.append({
                            "file": str(filepath),
                            "line": line_no,
                            "category": "hardcoded_secret",
                            "description": f"Hardcoded secret in variable: {var_name}",
                            "severity": "CRITICAL",
                            "type": "AST"
                        })

    def get_severity(self, category):
        """Determine severity based on category"""
        severity_map = {
            "sql_injection": "CRITICAL",
            "command_injection": "CRITICAL",
            "xss": "HIGH",
            "hardcoded_secrets": "CRITICAL",
            "insecure_deserialization": "HIGH",
            "file_operations": "MEDIUM",
            "dangerous_function": "HIGH"
        }
        return severity_map.get(category, "MEDIUM")

    def scan_directory(self, directory_path):
        """Scan all Python files in directory"""
        directory = Path(directory_path)

        if not directory.exists():
            print(f"Directory not found: {directory}")
            return

        # Find all Python files
        python_files = list(directory.rglob("*.py"))
        print(f"Found {len(python_files)} Python files to scan")

        for py_file in python_files:
            print(f"Scanning: {py_file}")
            self.scan_file(py_file)

        return self.generate_report()

    def generate_report(self):
        """Generate SAST scan report"""
        # Group by severity
        severity_counts = {
            "CRITICAL": 0,
            "HIGH": 0,
            "MEDIUM": 0,
            "LOW": 0
        }

        for vuln in self.vulnerabilities:
            severity = vuln["severity"]
            severity_counts[severity] = severity_counts.get(severity, 0) + 1

        # Group by category
        category_counts = {}
        for vuln in self.vulnerabilities:
            category = vuln["category"]
            category_counts[category] = category_counts.get(category, 0) + 1

        report = {
            "summary": {
                "total_vulnerabilities": len(self.vulnerabilities),
                "severity_distribution": severity_counts,
                "category_distribution": category_counts
            },
            "vulnerabilities": self.vulnerabilities,
            "recommendations": [
                "Use parameterized queries for database operations",
                "Avoid eval() and exec() with user input",
                "Store secrets in environment variables or secret managers",
                "Validate and sanitize all user inputs",
                "Use safe deserialization methods"
            ]
        }

        return report

# Example usage
if __name__ == "__main__":
    scanner = SimpleSASTScanner()

    # Scan current directory
    report = scanner.scan_directory(".")

    print("\n=== SAST Scan Results ===")
    print(f"Total vulnerabilities found: {report['summary']['total_vulnerabilities']}")

    if report["summary"]["total_vulnerabilities"] > 0:
        print("\nSeverity Distribution:")
        for severity, count in report["summary"]["severity_distribution"].items():
            if count > 0:
                print(f"  {severity}: {count}")

        print("\nCategory Distribution:")
        for category, count in report["summary"]["category_distribution"].items():
            if count > 0:
                print(f"  {category}: {count}")

        # Show top vulnerabilities
        print("\nTop Vulnerabilities:")
        critical_vulns = [v for v in report["vulnerabilities"] if v["severity"] == "CRITICAL"]
        for i, vuln in enumerate(critical_vulns[:5]):
            print(f"\n{i+1}. {vuln['category'].upper()} - {vuln['severity']}")
            print(f"   File: {vuln['file']}")
            print(f"   Line: {vuln['line']}")
            print(f"   Description: {vuln['description']}")
    else:
        print("No vulnerabilities found!")

#!/usr/bin/env python3
"""
Secrets Detector
Finds hardcoded secrets and credentials in source code
"""

import re
import os
import json
import math
from pathlib import Path
from typing import List, Dict, Any

class SecretsDetector:
    def __init__(self):
        self.secrets_found = []
        self.patterns = self.load_detection_patterns()
        self.entropy_threshold = 4.5  # Minimum entropy for random strings

    def load_detection_patterns(self) -> List[Dict[str, Any]]:
        """Load patterns for secret detection"""
        return [
            {
                "name": "API Key",
                "patterns": [
                    r"api[_-]?key\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"apikey\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"api_key\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]"
                ],
                "severity": "HIGH"
            },
            {
                "name": "Access Token",
                "patterns": [
                    r"access[_-]?token\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"access_token\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"bearer\s+([a-zA-Z0-9_\-\.]{20,})"
                ],
                "severity": "HIGH"
            },
            {
                "name": "Secret Key",
                "patterns": [
                    r"secret[_-]?key\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"secret_key\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"SECRET_KEY\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]"
                ],
                "severity": "CRITICAL"
            },
            {
                "name": "Password",
                "patterns": [
                    r"password\s*[=:]\s*['\"]([^'\"]{6,})['\"]",
                    r"passwd\s*[=:]\s*['\"]([^'\"]{6,})['\"]",
                    r"pwd\s*[=:]\s*['\"]([^'\"]{6,})['\"]",
                    r"\bpass\s*[=:]\s*['\"]([^'\"]{6,})['\"]"
                ],
                "severity": "CRITICAL"
            },
            {
                "name": "AWS Credentials",
                "patterns": [
                    r"aws[_-]?access[_-]?key[_-]?id\s*[=:]\s*['\"]([A-Z0-9]{20})['\"]",
                    r"aws[_-]?secret[_-]?access[_-]?key\s*[=:]\s*['\"]([A-Za-z0-9/+=]{40})['\"]",
                    r"AKIA[0-9A-Z]{16}"
                ],
                "severity": "CRITICAL"
            },
            {
                "name": "Database Connection",
                "patterns": [
                    r"mysql://[^:]+:([^@]+)@",
                    r"postgresql://[^:]+:([^@]+)@",
                    r"mongodb://[^:]+:([^@]+)@",
                    r"database[_-]?password\s*[=:]\s*['\"]([^'\"]+)['\"]"
                ],
                "severity": "HIGH"
            },
            {
                "name": "Cryptographic Key",
                "patterns": [
                    r"private[_-]?key\s*[=:]\s*['\"](-----BEGIN[\s\S]+?-----END[\s\S]+?)['\"]",
                    r"rsa[_-]?key\s*[=:]\s*['\"](-----BEGIN[\s\S]+?-----END[\s\S]+?)['\"]",
                    r"ecdsa[_-]?key\s*[=:]\s*['\"](-----BEGIN[\s\S]+?-----END[\s\S]+?)['\"]"
                ],
                "severity": "CRITICAL"
            },
            {
                "name": "OAuth Credentials",
                "patterns": [
                    r"client[_-]?secret\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"oauth[_-]?token\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]",
                    r"refresh[_-]?token\s*[=:]\s*['\"]([a-zA-Z0-9_\-]{20,})['\"]"
                ],
                "severity": "HIGH"
            }
        ]

    def calculate_entropy(self, string: str) -> float:
        """Calculate Shannon entropy of a string"""
        if not string:
            return 0

        # Count frequency of each character
        freq = {}
        for char in string:
            freq[char] = freq.get(char, 0) + 1

        # Calculate entropy
        entropy = 0.0
        length = len(string)
        for count in freq.values():
            probability = count / length
            entropy -= probability * math.log2(probability)

        return entropy

    def is_likely_secret(self, value: str) -> bool:
        """Determine if a value is likely a secret based on entropy"""
        # Check if value looks like a random string
        if len(value) < 8:
            return False

        # Calculate entropy
        entropy = self.calculate_entropy(value)

        # Check for high entropy (random-looking strings)
        if entropy >= self.entropy_threshold:
            return True

        # Check for common secret patterns
        secret_patterns = [
            r"^[A-Z0-9]{20}$",  # AWS Access Key ID
            r"^[A-Za-z0-9/+=]{40}$",  # AWS Secret Access Key
            r"^[a-f0-9]{32}$",  # MD5 hash
            r"^[a-f0-9]{40}$",  # SHA-1 hash
            r"^[a-f0-9]{64}$",  # SHA-256 hash
            r"^[A-Za-z0-9_\-]{20,}$"  # General token
        ]

        for pattern in secret_patterns:
            if re.match(pattern, value):
                return True

        return False

    def scan_file(self, filepath: Path) -> List[Dict[str, Any]]:
        """Scan a single file for secrets"""
        file_secrets = []

        try:
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
                lines = content.split('\n')

                # Skip binary files
                if '\x00' in content:
                    return []

                for line_num, line in enumerate(lines, 1):
                    # Check against patterns
                    for pattern_info in self.patterns:
                        for pattern in pattern_info["patterns"]:
                            matches = re.finditer(pattern, line, re.IGNORECASE)
                            for match in matches:
                                secret_value = match.group(1) if match.groups() else match.group(0)

                                if self.is_likely_secret(secret_value):
                                    file_secrets.append({
                                        "file": str(filepath),
                                        "line": line_num,
                                        "type": pattern_info["name"],
                                        "severity": pattern_info["severity"],
                                        "value_preview": secret_value[:50] + ("..." if len(secret_value) > 50 else ""),
                                        "full_line": line.strip(),
                                        "entropy": self.calculate_entropy(secret_value)
                                    })

                # Additional entropy-based scanning
                if len(content) > 100:  # Only for reasonably sized files
                    words = re.findall(r'\b[a-zA-Z0-9_\-]{10,}\b', content)
                    for word in words:
                        if self.is_likely_secret(word) and not any(w in word for w in ['http', 'https', 'www', 'example']):
                            # Find which line contains this word
                            for line_num, line in enumerate(lines, 1):
                                if word in line:
                                    # Check if we already found this
                                    existing = any(s["value_preview"].startswith(word[:50]) for s in file_secrets)
                                    if not existing:
                                        file_secrets.append({
                                            "file": str(filepath),
                                            "line": line_num,
                                            "type": "High Entropy String",
                                            "severity": "MEDIUM",
                                            "value_preview": word[:50] + ("..." if len(word) > 50 else ""),
                                            "full_line": line.strip(),
                                            "entropy": self.calculate_entropy(word)
                                        })
                                    break

        except Exception as e:
            print(f"Error scanning {filepath}: {e}")

        return file_secrets

    def scan_directory(self, directory: str, extensions: List[str] = None) -> Dict[str, Any]:
        """Scan a directory for secrets"""
        if extensions is None:
            extensions = ['.py', '.js', '.ts', '.java', '.php', '.rb', '.go', 
                         '.cpp', '.c', '.h', '.cs', '.sql', '.json', '.yml', 
                         '.yaml', '.toml', '.ini', '.cfg', '.conf', '.env', 
                         '.properties']

        dir_path = Path(directory)
        if not dir_path.exists():
            print(f"Directory not found: {directory}")
            return {}

        print(f"Scanning directory: {directory}")
        print(f"File extensions: {', '.join(extensions)}")

        # Scan all files
        total_files = 0
        for ext in extensions:
            for filepath in dir_path.rglob(f"*{ext}"):
                total_files += 1
                if total_files % 100 == 0:
                    print(f"Scanned {total_files} files...")

                file_secrets = self.scan_file(filepath)
                self.secrets_found.extend(file_secrets)

        print(f"\nScan complete. Scanned {total_files} files.")

        return self.generate_report()

    def generate_report(self) -> Dict[str, Any]:
        """Generate secrets detection report"""
        # Group by severity
        severity_counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}
        type_counts = {}
        file_counts = {}

        for secret in self.secrets_found:
            severity = secret["severity"]
            secret_type = secret["type"]
            file_path = secret["file"]

            severity_counts[severity] = severity_counts.get(severity, 0) + 1
            type_counts[secret_type] = type_counts.get(secret_type, 0) + 1
            file_counts[file_path] = file_counts.get(file_path, 0) + 1

        report = {
            "summary": {
                "total_secrets": len(self.secrets_found),
                "severity_distribution": severity_counts,
                "type_distribution": type_counts,
                "files_with_secrets": len(file_counts),
                "most_affected_files": sorted(file_counts.items(), key=lambda x: x[1], reverse=True)[:5]
            },
            "secrets": self.secrets_found,
            "recommendations": [
                "Store secrets in environment variables or secret managers",
                "Use .gitignore to prevent committing sensitive files",
                "Implement pre-commit hooks for secret detection",
                "Rotate exposed secrets immediately",
                "Use CI/CD integration for automatic secret detection"
            ]
        }

        return report

# Example usage
if __name__ == "__main__":
    detector = SecretsDetector()

    # Scan current directory
    report = detector.scan_directory(".", [".py", ".js", ".json", ".yml", ".yaml", ".env"])

    print("\n=== Secrets Detection Report ===")
    print(f"Total secrets found: {report['summary']['total_secrets']}")
    print(f"Files with secrets: {report['summary']['files_with_secrets']}")

    if report["summary"]["total_secrets"] > 0:
        print("\nSeverity Distribution:")
        for severity, count in report["summary"]["severity_distribution"].items():
            if count > 0:
                print(f"  {severity}: {count}")

        print("\nSecret Types Found:")
        for secret_type, count in report["summary"]["type_distribution"].items():
            if count > 0:
                print(f"  {secret_type}: {count}")

        # Show critical secrets
        critical_secrets = [s for s in report["secrets"] if s["severity"] == "CRITICAL"]
        if critical_secrets:
            print("\nCritical Secrets Found:")
            for i, secret in enumerate(critical_secrets[:5]):
                print(f"\n{i+1}. {secret['type']}")
                print(f"   File: {secret['file']}")
                print(f"   Line: {secret['line']}")
                print(f"   Preview: {secret['value_preview']}")
                print(f"   Line Content: {secret['full_line'][:100]}...")

    # Save report to file
    with open("secrets_report.json", "w") as f:
        json.dump(report, f, indent=2)

    print("\nReport saved to secrets_report.json")

