import { test, expect } from '@playwright/test';

const breakpoints = [
  { name: 'mobile', width: 375, height: 667 },
  { name: 'tablet', width: 768, height: 1024 },
  { name: 'desktop', width: 1366, height: 768 },
  { name: 'widescreen', width: 1920, height: 1080 }
];

breakpoints.forEach(({ name, width, height }) => {
  test(`Responsive layout - ${name}`, async ({ page }) => {
    // Set viewport
    await page.setViewportSize({ width, height });

    // Navigate to page
    await page.goto('https://your-app.com');

    // Test responsive elements
    await test.step(`Check navigation on ${name}`, async () => {
      const nav = page.locator('.main-nav');
      await expect(nav).toBeVisible();

      if (width < 768) {
        // Mobile: Hamburger menu should exist
        await expect(page.locator('.hamburger-menu')).toBeVisible();
        await expect(page.locator('.desktop-nav-items')).toBeHidden();
      } else {
        // Desktop: Full navigation should be visible
        await expect(page.locator('.hamburger-menu')).toBeHidden();
        await expect(page.locator('.desktop-nav-items')).toBeVisible();
      }
    });

    // Test content layout
    await test.step(`Check content layout on ${name}`, async () => {
      const container = page.locator('.content-container');
      const computedWidth = await container.evaluate(el => {
        return window.getComputedStyle(el).width;
      });

      // Verify responsive CSS is working
      if (width < 768) {
        expect(computedWidth).toBe('100%');
      } else if (width < 1200) {
        expect(computedWidth).toBe('90%');
      } else {
        expect(computedWidth).toBe('1200px');
      }
    });

    // Take screenshot for visual regression
    await page.screenshot({
      path: `screenshots/responsive-${name}-${width}x${height}.png`,
      fullPage: true
    });
  });
});

