import platform
import sys
import time
import json
import csv
from pathlib import Path
from dataclasses import dataclass, asdict
from typing import Dict, List, Optional, Tuple
from enum import Enum
import psutil
import cpuinfo

class DeviceType(Enum):
    DESKTOP = "desktop"
    MOBILE = "mobile"
    TABLET = "tablet"
    TV = "tv"
    WEARABLE = "wearable"

class OSType(Enum):
    WINDOWS = "windows"
    MACOS = "macos"
    LINUX = "linux"
    IOS = "ios"
    ANDROID = "android"
    CHROMEOS = "chromeos"

@dataclass
class SystemInfo:
    os_type: OSType
    os_version: str
    architecture: str
    processor: str
    ram_gb: float
    disk_gb: float
    screen_resolution: Optional[Tuple[int, int]] = None
    dpi: Optional[int] = None

    @classmethod
    def detect(cls):
        """Detect current system information"""
        system = platform.system().lower()

        if system == "windows":
            os_type = OSType.WINDOWS
            os_version = platform.version()
        elif system == "darwin":
            os_type = OSType.MACOS
            os_version = platform.mac_ver()[0]
        elif system == "linux":
            os_type = OSType.LINUX
            os_version = platform.version()
        else:
            os_type = OSType.LINUX  # Default
            os_version = "unknown"

        # Get processor info
        try:
            cpu_info = cpuinfo.get_cpu_info()
            processor = cpu_info.get('brand_raw', 'Unknown')
        except:
            processor = platform.processor()

        # Get RAM info
        ram_gb = psutil.virtual_memory().total / (1024**3)

        # Get disk info
        try:
            disk_gb = psutil.disk_usage('/').total / (1024**3)
        except:
            disk_gb = 0

        return cls(
            os_type=os_type,
            os_version=os_version,
            architecture=platform.machine(),
            processor=processor,
            ram_gb=round(ram_gb, 2),
            disk_gb=round(disk_gb, 2)
        )

@dataclass
class PlatformTestConfig:
    """Configuration for platform-specific testing"""
    platform_name: str
    device_type: DeviceType
    system_info: SystemInfo
    browser: str
    browser_version: str
    viewport_width: int
    viewport_height: int
    pixel_ratio: float = 1.0
    touch_enabled: bool = False
    geolocation_enabled: bool = True
    notifications_enabled: bool = False
    cookies_enabled: bool = True
    javascript_enabled: bool = True

    def get_viewport_string(self) -> str:
        return f"{self.viewport_width}x{self.viewport_height}"

    def is_mobile(self) -> bool:
        return self.device_type in [DeviceType.MOBILE, DeviceType.TABLET, DeviceType.WEARABLE]

class PlatformTestingFramework:
    def __init__(self, base_url: str):
        self.base_url = base_url
        self.configs: List[PlatformTestConfig] = []
        self.results: List[Dict] = []

    def add_config(self, config: PlatformTestConfig):
        self.configs.append(config)

    def load_configs_from_json(self, file_path: str):
        """Load test configurations from JSON file"""
        with open(file_path, 'r') as f:
            configs_data = json.load(f)

        for config_data in configs_data:
            system_info_data = config_data.pop('system_info')
            system_info = SystemInfo(**system_info_data)

            config = PlatformTestConfig(
                system_info=system_info,
                **config_data
            )
            self.add_config(config)

    def execute_platform_test(self, config: PlatformTestConfig, 
                            test_scenarios: List[Dict]) -> Dict:
        """Execute tests for a specific platform configuration"""
        from selenium import webdriver
        from selenium.webdriver.common.by import By

        test_result = {
            'platform': config.platform_name,
            'device_type': config.device_type.value,
            'viewport': config.get_viewport_string(),
            'start_time': time.time(),
            'scenarios': [],
            'performance_metrics': {},
            'accessibility_issues': [],
            'compatibility_issues': [],
            'status': 'pending'
        }

        driver = None
        try:
            # Setup WebDriver with platform-specific options
            driver = self.create_platform_driver(config)

            # Navigate to base URL
            driver.get(self.base_url)

            # Execute test scenarios
            for scenario in test_scenarios:
                scenario_result = self.execute_scenario(driver, config, scenario)
                test_result['scenarios'].append(scenario_result)

                # If any scenario fails, mark overall as failed
                if scenario_result.get('status') == 'failed':
                    test_result['status'] = 'failed'

            # Collect performance metrics
            test_result['performance_metrics'] = self.collect_performance_metrics(driver)

            # Check accessibility
            test_result['accessibility_issues'] = self.check_accessibility(driver)

            # Check compatibility issues
            test_result['compatibility_issues'] = self.check_compatibility(driver, config)

            # Update status if all passed
            if test_result['status'] == 'pending':
                test_result['status'] = 'passed'

        except Exception as e:
            test_result['status'] = 'error'
            test_result['error'] = str(e)

        finally:
            test_result['end_time'] = time.time()
            test_result['duration'] = test_result['end_time'] - test_result['start_time']

            if driver:
                try:
                    # Take screenshot
                    screenshot_path = f"screenshots/{config.platform_name}_{int(time.time())}.png"
                    driver.save_screenshot(screenshot_path)
                    test_result['screenshot'] = screenshot_path

                    driver.quit()
                except:
                    pass

        return test_result

    def create_platform_driver(self, config: PlatformTestConfig):
        """Create WebDriver instance with platform-specific configuration"""
        from selenium import webdriver
        from selenium.webdriver.common.desired_capabilities import DesiredCapabilities

        # Base capabilities
        capabilities = {
            'browserName': config.browser.lower(),
            'version': config.browser_version,
            'platform': config.system_info.os_type.value.upper(),
            'acceptInsecureCerts': True
        }

        # Add mobile emulation if needed
        if config.is_mobile() and config.browser.lower() == 'chrome':
            mobile_emulation = {
                "deviceMetrics": {
                    "width": config.viewport_width,
                    "height": config.viewport_height,
                    "pixelRatio": config.pixel_ratio
                },
                "userAgent": self.generate_mobile_user_agent(config)
            }

            capabilities['goog:chromeOptions'] = {
                'mobileEmulation': mobile_emulation,
                'args': [
                    '--no-sandbox',
                    '--disable-dev-shm-usage',
                    f'--window-size={config.viewport_width},{config.viewport_height}'
                ]
            }

        # For desktop browsers
        else:
            if config.browser.lower() == 'chrome':
                options = webdriver.ChromeOptions()
                options.add_argument(f'--window-size={config.viewport_width},{config.viewport_height}')
                if config.device_type == DeviceType.DESKTOP:
                    options.add_argument('--start-maximized')
                capabilities.update(options.to_capabilities())

        # Create driver (assuming Selenium Grid)
        driver = webdriver.Remote(
            command_executor='http://localhost:4444/wd/hub',
            desired_capabilities=capabilities
        )

        # Set viewport size
        driver.set_window_size(config.viewport_width, config.viewport_height)

        return driver

    def generate_mobile_user_agent(self, config: PlatformTestConfig) -> str:
        """Generate mobile user agent string"""
        if config.device_type == DeviceType.MOBILE:
            if config.system_info.os_type == OSType.IOS:
                return "Mozilla/5.0 (iPhone; CPU iPhone OS 14_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/14.0 Mobile/15E148 Safari/604.1"
            else:  # Android
                return "Mozilla/5.0 (Linux; Android 11; SM-G991B) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.114 Mobile Safari/537.36"
        else:  # Tablet
            if config.system_info.os_type == OSType.IOS:
                return "Mozilla/5.0 (iPad; CPU OS 14_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/14.0 Mobile/15E148 Safari/604.1"
            else:  # Android
                return "Mozilla/5.0 (Linux; Android 11; SM-T870) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.114 Safari/537.36"

    def execute_scenario(self, driver, config: PlatformTestConfig, scenario: Dict) -> Dict:
        """Execute a single test scenario"""
        from selenium.webdriver.support.ui import WebDriverWait
        from selenium.webdriver.support import expected_conditions as EC

        scenario_result = {
            'name': scenario['name'],
            'description': scenario.get('description', ''),
            'steps': [],
            'status': 'pending',
            'start_time': time.time()
        }

        try:
            for step in scenario['steps']:
                step_result = self.execute_step(driver, config, step)
                scenario_result['steps'].append(step_result)

                # If step fails, mark scenario as failed
                if step_result.get('status') == 'failed':
                    scenario_result['status'] = 'failed'
                    break

            # If all steps passed
            if scenario_result['status'] == 'pending':
                scenario_result['status'] = 'passed'

        except Exception as e:
            scenario_result['status'] = 'error'
            scenario_result['error'] = str(e)

        finally:
            scenario_result['end_time'] = time.time()
            scenario_result['duration'] = scenario_result['end_time'] - scenario_result['start_time']

        return scenario_result

    def execute_step(self, driver, config: PlatformTestConfig, step: Dict) -> Dict:
        """Execute a single test step"""
        step_result = {
            'action': step['action'],
            'element': step.get('element'),
            'value': step.get('value'),
            'status': 'pending',
            'timestamp': time.time()
        }

        try:
            # Handle platform-specific behaviors
            if config.is_mobile():
                self.handle_mobile_specific(driver, step)
            else:
                self.handle_desktop_specific(driver, step)

            step_result['status'] = 'passed'

        except Exception as e:
            step_result['status'] = 'failed'
            step_result['error'] = str(e)

        return step_result

    def handle_mobile_specific(self, driver, step: Dict):
        """Handle mobile-specific interactions"""
        from selenium.webdriver.common.touch_actions import TouchActions

        action = step['action']
        element = None

        if 'element' in step:
            element = driver.find_element(By.CSS_SELECTOR, step['element'])

        if action == 'tap':
            if element:
                touch_actions = TouchActions(driver)
                touch_actions.tap(element).perform()
            else:
                # Tap at coordinates
                driver.tap([(step.get('x', 100), step.get('y', 100))])

        elif action == 'swipe':
            # Implement swipe gesture
            pass

        elif action == 'pinch_zoom':
            # Implement pinch zoom
            pass

        elif action == 'rotate':
            # Implement rotation
            pass

    def handle_desktop_specific(self, driver, step: Dict):
        """Handle desktop-specific interactions"""
        action = step['action']
        element = None

        if 'element' in step:
            element = driver.find_element(By.CSS_SELECTOR, step['element'])

        if action == 'click':
            element.click()

        elif action == 'double_click':
            from selenium.webdriver.common.action_chains import ActionChains
            actions = ActionChains(driver)
            actions.double_click(element).perform()

        elif action == 'right_click':
            from selenium.webdriver.common.action_chains import ActionChains
            actions = ActionChains(driver)
            actions.context_click(element).perform()

        elif action == 'hover':
            from selenium.webdriver.common.action_chains import ActionChains
            actions = ActionChains(driver)
            actions.move_to_element(element).perform()

        elif action == 'drag_and_drop':
            from selenium.webdriver.common.action_chains import ActionChains
            target = driver.find_element(By.CSS_SELECTOR, step['target'])
            actions = ActionChains(driver)
            actions.drag_and_drop(element, target).perform()

    def collect_performance_metrics(self, driver) -> Dict:
        """Collect performance metrics from browser"""
        try:
            # Use JavaScript to get performance metrics
            metrics_script = """
            var perfData = window.performance.timing;
            var paintData = window.performance.getEntriesByType('paint');
            var navData = window.performance.getEntriesByType('navigation')[0];

            return {
                'navigationStart': perfData.navigationStart,
                'domInteractive': perfData.domInteractive - perfData.navigationStart,
                'domContentLoaded': perfData.domContentLoadedEventEnd - perfData.navigationStart,
                'loadEventEnd': perfData.loadEventEnd - perfData.navigationStart,
                'firstPaint': paintData.find(e => e.name === 'first-paint')?.startTime || 0,
                'firstContentfulPaint': paintData.find(e => e.name === 'first-contentful-paint')?.startTime || 0,
                'domSize': document.getElementsByTagName('*').length,
                'resourceCount': navData?.transferSize || 0,
                'memory': window.performance.memory ? {
                    'usedJSHeapSize': window.performance.memory.usedJSHeapSize,
                    'totalJSHeapSize': window.performance.memory.totalJSHeapSize
                } : null
            };
            """

            metrics = driver.execute_script(metrics_script)
            return metrics

        except:
            return {}

    def check_accessibility(self, driver) -> List[Dict]:
        """Check for accessibility issues"""
        issues = []

        try:
            # Check for missing alt text on images
            images = driver.find_elements(By.TAG_NAME, 'img')
            for img in images:
                alt = img.get_attribute('alt')
                if not alt or alt.strip() == '':
                    issues.append({
                        'type': 'missing_alt_text',
                        'element': 'img',
                        'message': 'Image missing alt attribute'
                    })

            # Check for proper heading structure
            headings = driver.find_elements(By.XPATH, '//h1|//h2|//h3|//h4|//h5|//h6')
            heading_levels = []
            for heading in headings:
                tag_name = heading.tag_name
                level = int(tag_name[1])
                heading_levels.append(level)

            # Check for heading hierarchy
            if heading_levels:
                if 1 not in heading_levels:
                    issues.append({
                        'type': 'missing_h1',
                        'message': 'No H1 heading found'
                    })

            # Check for form labels
            inputs = driver.find_elements(By.TAG_NAME, 'input')
            for inp in inputs:
                input_type = inp.get_attribute('type')
                if input_type not in ['hidden', 'submit', 'button']:
                    input_id = inp.get_attribute('id')
                    if input_id:
                        label = driver.find_elements(By.XPATH, f"//label[@for='{input_id}']")
                        if not label:
                            issues.append({
                                'type': 'missing_label',
                                'element': 'input',
                                'message': f'Input field missing label (id: {input_id})'
                            })

            # Check for sufficient color contrast (simplified)
            # In real implementation, use a proper contrast checking algorithm

        except Exception as e:
            issues.append({
                'type': 'accessibility_check_error',
                'message': f'Error checking accessibility: {str(e)}'
            })

        return issues

    def check_compatibility(self, driver, config: PlatformTestConfig) -> List[Dict]:
        """Check for compatibility issues"""
        issues = []

        try:
            # Check viewport rendering
            actual_width = driver.execute_script("return window.innerWidth")
            actual_height = driver.execute_script("return window.innerHeight")

            if actual_width != config.viewport_width or actual_height != config.viewport_height:
                issues.append({
                    'type': 'viewport_mismatch',
                    'expected': f"{config.viewport_width}x{config.viewport_height}",
                    'actual': f"{actual_width}x{actual_height}",
                    'message': 'Viewport size does not match expected size'
                })

            # Check for unsupported CSS features
            css_grid_supported = driver.execute_script("""
                var el = document.createElement('div');
                el.style.display = 'grid';
                return el.style.display === 'grid';
            """)

            if not css_grid_supported and config.browser in ['safari', 'ie']:
                issues.append({
                    'type': 'css_grid_unsupported',
                    'message': 'CSS Grid not fully supported in this browser'
                })

            # Check for JavaScript errors
            log_entries = driver.get_log('browser')
            js_errors = [entry for entry in log_entries if entry['level'] == 'SEVERE']

            for error in js_errors:
                issues.append({
                    'type': 'javascript_error',
                    'message': error['message'],
                    'timestamp': error['timestamp']
                })

        except Exception as e:
            issues.append({
                'type': 'compatibility_check_error',
                'message': f'Error checking compatibility: {str(e)}'
            })

        return issues

    def run_all_tests(self, test_scenarios: List[Dict]) -> List[Dict]:
        """Run tests across all platform configurations"""
        results = []

        print(f"Starting platform testing with {len(self.configs)} configurations...")

        for config in self.configs:
            print(f"Testing: {config.platform_name} ({config.device_type.value})")

            result = self.execute_platform_test(config, test_scenarios)
            results.append(result)

            print(f"  Status: {result['status']}, Duration: {result['duration']:.2f}s")

        # Generate summary report
        self.generate_summary_report(results)

        return results

    def generate_summary_report(self, results: List[Dict]):
        """Generate summary report of all test results"""
        total_tests = len(results)
        passed = sum(1 for r in results if r['status'] == 'passed')
        failed = sum(1 for r in results if r['status'] == 'failed')
        errors = sum(1 for r in results if r['status'] == 'error')

        # Calculate average duration
        durations = [r.get('duration', 0) for r in results]
        avg_duration = sum(durations) / len(durations) if durations else 0

        # Count issues
        total_accessibility_issues = sum(len(r.get('accessibility_issues', [])) for r in results)
        total_compatibility_issues = sum(len(r.get('compatibility_issues', [])) for r in results)

        summary = {
            'total_configurations': total_tests,
            'passed': passed,
            'failed': failed,
            'errors': errors,
            'pass_rate': (passed / total_tests * 100) if total_tests > 0 else 0,
            'average_duration_seconds': avg_duration,
            'total_accessibility_issues': total_accessibility_issues,
            'total_compatibility_issues': total_compatibility_issues,
            'results_by_platform': {},
            'generated_at': time.strftime('%Y-%m-%d %H:%M:%S')
        }

        # Group results by platform
        for result in results:
            platform_name = result['platform']
            if platform_name not in summary['results_by_platform']:
                summary['results_by_platform'][platform_name] = {
                    'total': 0,
                    'passed': 0,
                    'failed': 0,
                    'errors': 0
                }

            summary['results_by_platform'][platform_name]['total'] += 1
            summary['results_by_platform'][platform_name][result['status']] += 1

        # Save summary to file
        with open('platform_test_summary.json', 'w') as f:
            json.dump(summary, f, indent=2)

        # Also save detailed results
        detailed_report = {
            'summary': summary,
            'detailed_results': results
        }

        with open('platform_test_detailed.json', 'w') as f:
            json.dump(detailed_report, f, indent=2)

        # Generate CSV report
        self.generate_csv_report(results)

        print("\n" + "="*60)
        print("PLATFORM TESTING SUMMARY")
        print("="*60)
        print(f"Total Configurations Tested: {summary['total_configurations']}")
        print(f"Passed: {summary['passed']} ({summary['pass_rate']:.1f}%)")
        print(f"Failed: {summary['failed']}")
        print(f"Errors: {summary['errors']}")
        print(f"Average Duration: {summary['average_duration_seconds']:.2f}s")
        print(f"Accessibility Issues: {summary['total_accessibility_issues']}")
        print(f"Compatibility Issues: {summary['total_compatibility_issues']}")
        print("="*60)

        return summary

    def generate_csv_report(self, results: List[Dict]):
        """Generate CSV report for easy analysis"""
        csv_file = 'platform_test_results.csv'

        with open(csv_file, 'w', newline='') as f:
            writer = csv.writer(f)

            # Write header
            writer.writerow([
                'Platform',
                'Device Type',
                'Viewport',
                'Browser',
                'Status',
                'Duration (s)',
                'Accessibility Issues',
                'Compatibility Issues',
                'Scenarios Passed',
                'Scenarios Failed',
                'Performance Score'
            ])

            # Write data rows
            for result in results:
                scenarios_passed = sum(1 for s in result.get('scenarios', []) 
                                     if s.get('status') == 'passed')
                scenarios_failed = sum(1 for s in result.get('scenarios', []) 
                                     if s.get('status') == 'failed')

                writer.writerow([
                    result['platform'],
                    result.get('device_type', 'N/A'),
                    result.get('viewport', 'N/A'),
                    result.get('browser', 'N/A'),
                    result['status'],
                    f"{result.get('duration', 0):.2f}",
                    len(result.get('accessibility_issues', [])),
                    len(result.get('compatibility_issues', [])),
                    scenarios_passed,
                    scenarios_failed,
                    result.get('performance_metrics', {}).get('score', 'N/A')
                ])

        print(f"CSV report saved to: {csv_file}")

