import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.NoSuchElementException;
import org.openqa.selenium.StaleElementReferenceException;
import org.openqa.selenium.TimeoutException;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.FluentWait;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;
import java.util.Arrays;
import java.util.List;

public class RobustElementFinder {

    private WebDriver driver;
    private static final Duration DEFAULT_TIMEOUT = Duration.ofSeconds(10);
    private static final Duration POLLING_INTERVAL = Duration.ofMillis(500);

    /**
     * Find element with multiple locator strategies (fallback approach)
     */
    public WebElement findElementWithFallback(String identifier) {
        List<By> locatorStrategies = Arrays.asList(
            By.id(identifier),
            By.cssSelector("[data-testid='" + identifier + "']"),
            By.name(identifier),
            By.cssSelector("[name='" + identifier + "']"),
            By.xpath("//*[@id='" + identifier + "' or @name='" + identifier + "' or @data-testid='" + identifier + "']")
        );

        for (By locator : locatorStrategies) {
            try {
                List<WebElement> elements = driver.findElements(locator);
                if (!elements.isEmpty() && elements.get(0).isDisplayed()) {
                    return elements.get(0);
                }
            } catch (Exception e) {
                // Try next strategy
                continue;
            }
        }

        throw new NoSuchElementException("Element not found with any strategy for: " + identifier);
    }

    /**
     * Wait for element with explicit wait
     */
    public WebElement waitForElement(By locator, Duration timeout) {
        WebDriverWait wait = new WebDriverWait(driver, timeout);
        return wait.until(ExpectedConditions.presenceOfElementLocated(locator));
    }

    public WebElement waitForElementVisible(By locator, Duration timeout) {
        WebDriverWait wait = new WebDriverWait(driver, timeout);
        return wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
    }

    public WebElement waitForElementClickable(By locator, Duration timeout) {
        WebDriverWait wait = new WebDriverWait(driver, timeout);
        return wait.until(ExpectedConditions.elementToBeClickable(locator));
    }

    /**
     * Fluent wait with custom conditions
     */
    public WebElement waitForElementWithFluentWait(By locator) {
        FluentWait<WebDriver> wait = new FluentWait<>(driver)
            .withTimeout(DEFAULT_TIMEOUT)
            .pollingEvery(POLLING_INTERVAL)
            .ignoring(NoSuchElementException.class)
            .ignoring(StaleElementReferenceException.class)
            .withMessage("Element not found: " + locator);

        return wait.until(driver -> {
            WebElement element = driver.findElement(locator);
            return element.isDisplayed() && element.isEnabled() ? element : null;
        });
    }

    /**
     * Find element with retry logic for flaky situations
     */
    public WebElement findElementWithRetry(By locator, int maxAttempts) {
        int attempts = 0;
        WebElement element = null;

        while (attempts < maxAttempts && element == null) {
            try {
                element = driver.findElement(locator);
                if (element.isDisplayed()) {
                    return element;
                }
                element = null; // Element found but not displayed
            } catch (NoSuchElementException | StaleElementReferenceException e) {
                // Wait and retry
                try {
                    Thread.sleep(1000);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
            attempts++;
        }

        throw new NoSuchElementException("Element not found after " + maxAttempts + " attempts: " + locator);
    }

    /**
     * Check if element exists without throwing exception
     */
    public boolean isElementPresent(By locator) {
        try {
            driver.findElement(locator);
            return true;
        } catch (NoSuchElementException e) {
            return false;
        }
    }

    public boolean isElementVisible(By locator) {
        try {
            WebElement element = driver.findElement(locator);
            return element.isDisplayed();
        } catch (NoSuchElementException e) {
            return false;
        }
    }

    /**
     * Get element text safely
     */
    public String getSafeText(By locator) {
        try {
            WebElement element = waitForElementVisible(locator, DEFAULT_TIMEOUT);
            return element.getText().trim();
        } catch (TimeoutException e) {
            return "";
        }
    }
}

import org.openqa.selenium.By;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.Keys;
import org.openqa.selenium.interactions.Actions;
import org.openqa.selenium.JavascriptExecutor;
import org.openqa.selenium.support.ui.Select;
import java.time.Duration;
import java.util.List;

public class AdvancedInteractions {

    private WebDriver driver;
    private Actions actions;
    private JavascriptExecutor js;

    public AdvancedInteractions(WebDriver driver) {
        this.driver = driver;
        this.actions = new Actions(driver);
        this.js = (JavascriptExecutor) driver;
    }

    /**
     * Comprehensive form filling with validation
     */
    public void fillFormWithValidation(FormData formData) {
        // Text input with clearing
        fillTextField(By.id("firstName"), formData.getFirstName());
        fillTextField(By.id("lastName"), formData.getLastName());

        // Email with validation
        fillEmailField(By.id("email"), formData.getEmail());

        // Dropdown selection
        selectFromDropdown(By.id("country"), formData.getCountry());

        // Radio button selection
        selectRadioButton(By.name("gender"), formData.getGender());

        // Checkbox handling
        setCheckbox(By.id("newsletter"), formData.isSubscribeToNewsletter());

        // Date picker (custom method)
        selectDate(By.id("birthDate"), formData.getBirthDate());

        // File upload
        uploadFile(By.id("resume"), formData.getResumePath());

        // Text area with special characters
        fillTextArea(By.id("comments"), formData.getComments());

        // Validate form before submission
        validateForm();
    }

    private void fillTextField(By locator, String text) {
        WebElement field = driver.findElement(locator);

        // Clear existing text
        field.clear();

        // Type text
        field.sendKeys(text);

        // Verify text was entered
        String enteredText = field.getAttribute("value");
        if (!enteredText.equals(text)) {
            // Retry with JavaScript if normal method fails
            js.executeScript("arguments[0].value = arguments[1]", field, text);
        }
    }

    private void fillEmailField(By locator, String email) {
        WebElement field = driver.findElement(locator);
        field.clear();
        field.sendKeys(email);

        // Trigger validation (blur event)
        field.sendKeys(Keys.TAB);

        // Check for validation errors
        if (isElementPresent(By.cssSelector(".error-message"))) {
            throw new IllegalArgumentException("Invalid email format: " + email);
        }
    }

    private void selectFromDropdown(By locator, String value) {
        WebElement dropdownElement = driver.findElement(locator);
        Select dropdown = new Select(dropdownElement);

        // Try different selection methods
        try {
            dropdown.selectByVisibleText(value);
        } catch (Exception e1) {
            try {
                dropdown.selectByValue(value);
            } catch (Exception e2) {
                dropdown.selectByIndex(0); // Default to first option
            }
        }
    }

    private void selectRadioButton(By nameLocator, String value) {
        List<WebElement> radioButtons = driver.findElements(nameLocator);

        for (WebElement radio : radioButtons) {
            if (radio.getAttribute("value").equals(value)) {
                if (!radio.isSelected()) {
                    // Use JavaScript click for better compatibility
                    js.executeScript("arguments[0].click();", radio);
                }
                break;
            }
        }
    }

    private void setCheckbox(By locator, boolean shouldCheck) {
