// Base Page with common functionality
public abstract class BasePage {
    protected WebDriver driver;
    protected WebDriverWait wait;

    public BasePage(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(15));
        this.waitForPageLoad();
    }

    protected abstract void waitForPageLoad();

    protected WebElement waitForElement(By locator) {
        return wait.until(ExpectedConditions.presenceOfElementLocated(locator));
    }

    protected void clickWithRetry(By locator, int maxRetries) {
        for (int i = 0; i < maxRetries; i++) {
            try {
                wait.until(ExpectedConditions.elementToBeClickable(locator)).click();
                return;
            } catch (StaleElementReferenceException e) {
                if (i == maxRetries - 1) throw e;
            }
        }
    }
}

// Concrete Page Implementation
public class LoginPage extends BasePage {
    // Locators - Consider moving to separate class for large projects
    private static final By USERNAME = By.id("username");
    private static final By PASSWORD = By.id("password");
    private static final By LOGIN_BUTTON = By.id("login-btn");
    private static final By ERROR_MESSAGE = By.cssSelector(".alert.error");

    public LoginPage(WebDriver driver) {
        super(driver);
    }

    @Override
    protected void waitForPageLoad() {
        wait.until(ExpectedConditions.visibilityOfElementLocated(USERNAME));
    }

    // Business methods return next page object
    public DashboardPage login(String username, String password) {
        enterUsername(username);
        enterPassword(password);
        clickLogin();
        return new DashboardPage(driver);
    }

    public LoginPage loginExpectingError(String username, String password) {
        enterUsername(username);
        enterPassword(password);
        clickLogin();
        return this; // Stay on same page
    }

    public String getErrorMessage() {
        return waitForElement(ERROR_MESSAGE).getText();
    }

    // Private helper methods
    private void enterUsername(String username) {
        waitForElement(USERNAME).clear();
        waitForElement(USERNAME).sendKeys(username);
    }

    private void enterPassword(String password) {
        waitForElement(PASSWORD).sendKeys(password);
    }

    private void clickLogin() {
        clickWithRetry(LOGIN_BUTTON, 3);
    }
}

