public class StabilityUtils {

    // Retry mechanism for flaky operations
    public static <T> T retry(Callable<T> operation, int maxAttempts, 
                              Class<? extends Exception>... exceptions) {
        Exception lastException = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return operation.call();
            } catch (Exception e) {
                lastException = e;
                boolean retryable = Arrays.stream(exceptions)
                    .anyMatch(ex -> ex.isInstance(e));
                if (!retryable || attempt == maxAttempts) {
                    throw new RuntimeException("Operation failed after " + 
                        attempt + " attempts", lastException);
                }
                waitBeforeRetry(attempt);
            }
        }
        throw new RuntimeException("Should not reach here");
    }

    private static void waitBeforeRetry(int attempt) {
        try {
            Thread.sleep(1000 * attempt); // Exponential backoff
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    // Custom Expected Conditions
    public static ExpectedCondition<Boolean> animationCompleted(By locator) {
        return driver -> {
            WebElement element = driver.findElement(locator);
            String classes = element.getAttribute("class");
            return !classes.contains("animating") && 
                   !classes.contains("transition");
        };
    }

    public static ExpectedCondition<Boolean> networkIdle() {
        return driver -> {
            JavascriptExecutor js = (JavascriptExecutor) driver;
            Long activeRequests = (Long) js.executeScript(
                "return window.performance.getEntriesByType('resource')
                 .filter(r => !r.name.includes('analytics')).length;");
            return activeRequests == 0;
        };
    }
}

