      return new Promise(resolve => {
        new PerformanceObserver((entryList) => {
          const entries = entryList.getEntries();
          resolve(entries[entries.length - 1]);
        }).observe({ type: 'largest-contentful-paint', buffered: true });
      });
    });

    expect(lcp.startTime).toBeLessThan(2500); // LCP under 2.5s

    // Check memory usage
    const metrics = await page.metrics();
    console.log('JS Heap Size:', metrics.JSHeapUsedSize);

    // Network request analysis
    const requests = await page.evaluate(() => 
      performance.getEntriesByType('resource')
    );

    const totalResourceSize = requests.reduce((sum, req) => 
      sum + (req.transferSize || 0), 0
    );
    expect(totalResourceSize).toBeLessThan(5 * 1024 * 1024); // < 5MB
  });
});

