/**
 * Login Page Object Model
 */
class LoginPage {
  constructor(page) {
    this.page = page;

    // Locators
    this.emailInput = page.locator('[data-test="email-input"]');
    this.passwordInput = page.locator('[data-test="password-input"]');
    this.submitButton = page.locator('[data-test="login-submit"]');
    this.errorMessage = page.locator('[data-test="login-error"]');
    this.rememberMe = page.locator('[data-test="remember-me"]');
    this.forgotPassword = page.locator('[data-test="forgot-password"]');
    this.registerLink = page.locator('[data-test="register-link"]');
  }

  /**
   * Navigate to login page
   */
  async navigate() {
    await this.page.goto('/login');
    await this.page.waitForLoadState('networkidle');
    await this.emailInput.waitFor({ state: 'visible' });
  }

  /**
   * Perform login
   * @param {string} email - User email
   * @param {string} password - User password
   * @param {boolean} rememberMe - Remember login
   */
  async login(email, password, rememberMe = false) {
    await this.emailInput.fill(email);
    await this.passwordInput.fill(password);

    if (rememberMe) {
      await this.rememberMe.check();
    }

    await this.submitButton.click();

    // Wait for navigation or error
    await Promise.race([
      this.page.waitForURL(/.*dashboard/),
      this.errorMessage.waitFor({ state: 'visible' })
    ]);
  }

  /**
   * Get error message text
   */
  async getErrorMessage() {
    await this.errorMessage.waitFor({ state: 'visible' });
    return await this.errorMessage.textContent();
  }

  /**
   * Navigate to registration
   */
  async goToRegistration() {
    await this.registerLink.click();
    await this.page.waitForURL(/.*register/);
  }

  /**
   * Navigate to forgot password
   */
  async goToForgotPassword() {
    await this.forgotPassword.click();
    await this.page.waitForURL(/.*forgot-password/);
  }

  /**
   * Check if login page is displayed
   */
  async isDisplayed() {
    return await this.emailInput.isVisible() && 
           await this.passwordInput.isVisible();
  }
}

module.exports = { LoginPage };

