// ============================================

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.List;

public class AdvancedFrameHandler {
    private WebDriver driver;
    private WebDriverWait wait;

    public AdvancedFrameHandler(WebDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(15));
    }

    /**
     * Wait for iframe to be available and switch to it
     */
    public void switchToFrame(By frameLocator) {
        try {
            // Wait for frame to exist
            WebElement frame = wait.until(
                ExpectedConditions.presenceOfElementLocated(frameLocator)
            );

            // Wait for frame to be visible
            wait.until(ExpectedConditions.visibilityOf(frame));

            // Wait for frame to load
            wait.until(driver -> {
                try {
                    driver.switchTo().frame(frame);

                    // Check if frame document is ready
                    return ((JavascriptExecutor) driver)
                        .executeScript("return document.readyState").equals("complete");
                } catch (Exception e) {
                    return false;
                }
            });

            System.out.println("Successfully switched to frame: " + frameLocator);

        } catch (TimeoutException e) {
            throw new RuntimeException("Frame not available: " + frameLocator, e);
        }
    }

    /**
     * Handle nested frames
     */
    public void switchToNestedFrame(By[] frameLocators) {
        // Switch to default content first
        driver.switchTo().defaultContent();

        for (By frameLocator : frameLocators) {
            switchToFrame(frameLocator);
        }
    }

    /**
     * Find and switch to frame by partial URL match
     */
    public void switchToFrameByPartialUrl(String partialUrl) {
        List<WebElement> frames = driver.findElements(By.tagName("iframe"));

        for (WebElement frame : frames) {
            String src = frame.getAttribute("src");
            if (src != null && src.contains(partialUrl)) {
                driver.switchTo().frame(frame);
                return;
            }
        }

        throw new NoSuchFrameException("No frame found with URL containing: " + partialUrl);
    }

    /**
     * Execute JavaScript in iframe context
     */
    public Object executeInFrame(By frameLocator, String script, Object... args) {
        // Store current context
        String originalWindow = driver.getWindowHandle();

        try {
            switchToFrame(frameLocator);
            JavascriptExecutor js = (JavascriptExecutor) driver;
            return js.executeScript(script, args);
        } finally {
            // Always return to default content
            driver.switchTo().defaultContent();
            driver.switchTo().window(originalWindow);
        }
    }

    /**
     * Handle dynamic iframe that loads asynchronously
     */
    public void waitForDynamicFrame(String frameId, int timeoutSeconds) {
        wait.until(driver -> {
            try {
                // Check if frame exists
                List<WebElement> frames = driver.findElements(By.id(frameId));
                if (frames.isEmpty()) {
                    return false;
                }

                WebElement frame = frames.get(0);

                // Switch to frame and check if content loaded
                driver.switchTo().frame(frame);
                boolean isLoaded = ((JavascriptExecutor) driver)
                    .executeScript("return document.readyState").equals("complete");

                driver.switchTo().defaultContent();
                return isLoaded;

            } catch (Exception e) {
                return false;
            }
        });
    }

    /**
     * Get all iframes on page with their properties
     */
    public Map<String, Map<String, String>> getAllFramesInfo() {
        Map<String, Map<String, String>> framesInfo = new HashMap<>();

        List<WebElement> frames = driver.findElements(By.tagName("iframe"));

        for (int i = 0; i < frames.size(); i++) {
            WebElement frame = frames.get(i);
            Map<String, String> info = new HashMap<>();

            info.put("id", frame.getAttribute("id"));
            info.put("name", frame.getAttribute("name"));
            info.put("src", frame.getAttribute("src"));
            info.put("title", frame.getAttribute("title"));
            info.put("width", frame.getAttribute("width"));
            info.put("height", frame.getAttribute("height"));
            info.put("sandbox", frame.getAttribute("sandbox"));
            info.put("allow", frame.getAttribute("allow"));

            framesInfo.put("frame_" + i, info);
        }

        return framesInfo;
    }
}

