import { test, expect, Frame } from '@playwright/test';

class PlaywrightFrameHandler {

    /**
     * Get frame by name, URL, or selector
     */
    async getFrame(page, identifier) {
        // Wait for frame to be attached
        await page.waitForLoadState('networkidle');

        // Try different ways to find frame
        let frame;

        if (typeof identifier === 'string') {
            // Try by name first
            frame = page.frame({ name: identifier });

            // Try by URL if not found by name
            if (!frame) {
                frame = page.frame({ url: new RegExp(identifier) });
            }

            // Try by selector
            if (!frame) {
                const frameElement = page.locator(identifier).first();
                if (await frameElement.count() > 0) {
                    frame = await frameElement.contentFrame();
                }
            }
        } else if (identifier.url) {
            frame = page.frame(identifier);
        }

        if (!frame) {
            throw new Error(`Frame not found: ${identifier}`);
        }

        // Wait for frame content
        await frame.waitForLoadState('domcontentloaded');

        return frame;
    }

    /**
     * Handle nested frames
     */
    async switchToNestedFrame(page, framePath) {
        let currentFrame = page;

        for (const frameIdentifier of framePath) {
            currentFrame = await this.getFrame(currentFrame, frameIdentifier);

            if (!currentFrame) {
                throw new Error(`Failed to find frame: ${frameIdentifier}`);
            }
        }

        return currentFrame;
    }

    /**
     * Interact with element inside frame
     */
    async interactInFrame(page, frameIdentifier, elementSelector, action) {
        const frame = await this.getFrame(page, frameIdentifier);

        switch (action.type) {
            case 'click':
                await frame.click(elementSelector);
                break;
            case 'fill':
                await frame.fill(elementSelector, action.value);
                break;
            case 'select':
                await frame.selectOption(elementSelector, action.value);
                break;
            case 'check':
                await frame.check(elementSelector);
                break;
            case 'uncheck':
                await frame.uncheck(elementSelector);
                break;
            case 'hover':
                await frame.hover(elementSelector);
                break;
            default:
                throw new Error(`Unknown action: ${action.type}`);
        }
    }

    /**
     * Handle cross-origin iframes
     */
    async handleCrossOriginFrame(page, frameUrl) {
        // For cross-origin frames, we need to handle them differently
        // since direct DOM access is restricted

        // Method 1: Use page.frames() to find the frame
        const frames = page.frames();
        const targetFrame = frames.find(f => f.url().includes(frameUrl));

        if (!targetFrame) {
            throw new Error(`Cross-origin frame not found: ${frameUrl}`);
        }

        // We can still interact with some elements
        // But DOM inspection is limited

        return targetFrame;
    }
}

