// WINDOW MANAGEMENT UTILITY CLASS (Selenium Java)
// ============================================

import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.*;
import java.util.function.Function;

public class WindowManager {
    private WebDriver driver;
    private String mainWindowHandle;
    private Map<String, String> windowContexts;

    public WindowManager(WebDriver driver) {
        this.driver = driver;
        this.mainWindowHandle = driver.getWindowHandle();
        this.windowContexts = new HashMap<>();
        saveWindowContext(mainWindowHandle, "MAIN");
    }

    /**
     * Save window context with description
     */
    private void saveWindowContext(String handle, String description) {
        windowContexts.put(handle, description);
        System.out.println("Saved window context: " + description + " - " + handle);
    }

    /**
     * Open new window/tab and switch to it
     */
    public String openNewWindow(String url, String description) {
        // Open new window using JavaScript
        ((JavascriptExecutor) driver).executeScript("window.open();");

        // Get all window handles
        Set<String> handles = driver.getWindowHandles();
        List<String> handlesList = new ArrayList<>(handles);

        // Find new window (last in list)
        String newWindowHandle = handlesList.get(handlesList.size() - 1);

        // Switch to new window
        driver.switchTo().window(newWindowHandle);

        // Navigate to URL if provided
        if (url != null && !url.isEmpty()) {
            driver.get(url);
        }

        // Save context
        saveWindowContext(newWindowHandle, description);

        return newWindowHandle;
    }

    /**
     * Switch to window by description or partial title
     */
    public void switchToWindow(String identifier) {
        Set<String> handles = driver.getWindowHandles();

        for (String handle : handles) {
            driver.switchTo().window(handle);

            // Check by description
            if (windowContexts.containsKey(handle) && 
                windowContexts.get(handle).equals(identifier)) {
                System.out.println("Switched to window: " + identifier);
                return;
            }

            // Check by partial title
            if (driver.getTitle().contains(identifier)) {
                System.out.println("Switched to window with title containing: " + identifier);
                return;
            }

            // Check by URL
            if (driver.getCurrentUrl().contains(identifier)) {
                System.out.println("Switched to window with URL containing: " + identifier);
                return;
            }
        }

        throw new NoSuchWindowException("Window not found: " + identifier);
    }

    /**
     * Switch to main window
     */
    public void switchToMainWindow() {
        driver.switchTo().window(mainWindowHandle);
        System.out.println("Switched to main window");
    }

    /**
     * Close current window and switch to specified window
     */
    public void closeWindowAndSwitchTo(String targetWindowIdentifier) {
        String currentHandle = driver.getWindowHandle();

        // Close current window
        driver.close();

        // Remove from contexts
        windowContexts.remove(currentHandle);

        // Switch to target window
        switchToWindow(targetWindowIdentifier);
    }

    /**
     * Close all windows except main
     */
    public void closeAllExceptMain() {
        Set<String> handles = driver.getWindowHandles();

        for (String handle : handles) {
            if (!handle.equals(mainWindowHandle)) {
                driver.switchTo().window(handle);
                driver.close();
                windowContexts.remove(handle);
            }
        }

        // Switch back to main window
        switchToMainWindow();
    }

    /**
     * Execute function in specific window
     */
    public <T> T executeInWindow(String windowIdentifier, Function<WebDriver, T> function) {
        // Store current window
        String originalWindow = driver.getWindowHandle();

        try {
            // Switch to target window
            switchToWindow(windowIdentifier);

            // Execute function
            return function.apply(driver);

        } finally {
            // Always return to original window
            driver.switchTo().window(originalWindow);
        }
    }

    /**
     * Wait for new window to open
     */
    public String waitForNewWindow(int timeoutSeconds) {
        int originalCount = driver.getWindowHandles().size();

        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));

        return wait.until(driver -> {
            Set<String> handles = driver.getWindowHandles();
            if (handles.size() > originalCount) {
                // Find new handle
                List<String> handlesList = new ArrayList<>(handles);
                return handlesList.get(handlesList.size() - 1);
            }
            return null;
        });
    }

    /**
     * Get information about all open windows
     */
    public List<Map<String, String>> getAllWindowsInfo() {
        List<Map<String, String>> windowsInfo = new ArrayList<>();
        String originalHandle = driver.getWindowHandle();

        Set<String> handles = driver.getWindowHandles();

        for (String handle : handles) {
            driver.switchTo().window(handle);

            Map<String, String> info = new HashMap<>();
            info.put("handle", handle);
            info.put("title", driver.getTitle());
            info.put("url", driver.getCurrentUrl());
            info.put("context", windowContexts.getOrDefault(handle, "UNKNOWN"));

            windowsInfo.add(info);
        }

        // Return to original window
        driver.switchTo().window(originalHandle);

        return windowsInfo;
    }

    /**
     * Handle OAuth flow with popup window
     */
    public void handleOAuthPopup(String providerName) {
        // Click login button (opens popup)
        driver.findElement(By.cssSelector(".login-with-" + providerName)).click();

        // Wait for popup window
        String popupHandle = waitForNewWindow(10);

        // Switch to popup
        driver.switchTo().window(popupHandle);

        // Perform OAuth steps
        if (providerName.equals("google")) {
            driver.findElement(By.id("identifierId")).sendKeys("test@example.com");
            driver.findElement(By.id("identifierNext")).click();
            // ... more steps
        }

        // Wait for redirect back to main app
        wait.until(ExpectedConditions.urlContains("oauth-callback"));

        // Popup should close automatically after OAuth
        // If not, close it manually
        if (driver.getWindowHandles().size() > 1) {
            driver.close();
            switchToMainWindow();
        }
    }
}

