// UTILITY WRAPPER FOR ALL INTERACTIONS
class BrowserInteractionManager {
    constructor(page, browser) {
        this.page = page;
        this.browser = browser;
        this.frameHandler = new FrameHandler(page);
        this.dialogHandler = new DialogHandler(page);
        this.windowManager = new WindowManager(page);

        this.setupGlobalListeners();
    }

    setupGlobalListeners() {
        // Global dialog handler
        this.page.on('dialog', async dialog => {
            console.log(`[DIALOG] ${dialog.type()}: ${dialog.message()}`);

            // Default behavior: accept alerts, handle others based on test
            if (dialog.type() === 'alert') {
                await dialog.accept();
            }
            // Confirm and prompt should be handled explicitly in tests
        });

        // Global new page handler
        this.page.context().on('page', async newPage => {
            console.log(`[WINDOW] New page opened: ${await newPage.url()}`);
            this.windowManager.registerNewPage(newPage);
        });
    }

    async safeClick(selector, options = {}) {
        const { inFrame, inWindow, expectDialog } = options;

        // Set up dialog expectation if specified
        if (expectDialog) {
            this.page.once('dialog', expectDialog);
        }

        // Handle frame context if specified
        if (inFrame) {
            const frame = await this.frameHandler.getFrame(inFrame);
            await frame.click(selector);
        } else if (inWindow) {
            // Handle window context
            await this.windowManager.switchToWindow(inWindow);
            await this.page.click(selector);
        } else {
            // Default: current page context
            await this.page.click(selector);
        }
    }

    async fillInFrame(frameIdentifier, selector, value) {
        const frame = await this.frameHandler.getFrame(frameIdentifier);
        await frame.fill(selector, value);
    }

    async handleAuthentication(username, password) {
        // Multiple strategies for authentication
        try {
            // Try HTTP credentials in URL first
            const url = this.page.url();
            const authUrl = url.replace('://', `://${username}:${password}@`);
            await this.page.goto(authUrl);
        } catch (error) {
            // Fallback to alert handling
            this.page.once('dialog', async dialog => {
                if (dialog.type() === 'prompt') {
                    await dialog.accept(username);
                }
            });

            // Trigger re-auth
            await this.page.reload();
        }
    }
}

