import org.openqa.selenium.WebDriver;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.interactions.Actions;
import org.openqa.selenium.interactions.Action;
import org.openqa.selenium.Keys;

public class SeleniumActionsDemo {
    private WebDriver driver;
    private Actions actions;

    public SeleniumActionsDemo(WebDriver driver) {
        this.driver = driver;
        this.actions = new Actions(driver);
    }

    // Actions Class Examples
    public void demonstrateActionsClass() {
        WebElement element = driver.findElement(By.id("test-element"));

        // Method chaining with Actions class
        actions.moveToElement(element)
               .click()
               .sendKeys("Hello World")
               .doubleClick()
               .contextClick()
               .perform(); // Execution happens here
    }

    // Action Interface Examples
    public void demonstrateActionInterface() {
        WebElement source = driver.findElement(By.id("source"));
        WebElement target = driver.findElement(By.id("target"));

        // Build an Action for later execution
        Action dragAndDropAction = actions.clickAndHold(source)
                                         .moveToElement(target)
                                         .release()
                                         .build();

        // Store the action
        System.out.println("Action created: " + dragAndDropAction);

        // Execute later when needed
        dragAndDropAction.perform();

        // Execute multiple times
        dragAndDropAction.perform(); // Execute again
        dragAndDropAction.perform(); // Execute third time
    }

    // Key difference demonstration
    public void showDifference() {
        // Using Actions class directly
        actions.moveToElement(element).click().perform();

        // Using Action interface
        Action clickAction = actions.moveToElement(element).click().build();
        clickAction.perform(); // Same result

        // The advantage: Action can be reused
        for (int i = 0; i < 5; i++) {
            clickAction.perform(); // Execute 5 times
        }
    }
}

import org.openqa.selenium.Keys;
import org.openqa.selenium.WebElement;

public class KeyboardEvents {
    private Actions actions;

    // Single key events
    public void basicKeyEvents(WebElement element) {
        // Press a key
        actions.keyDown(Keys.SHIFT).perform();

        // Type while shift is held
        element.sendKeys("uppercase"); // Will be "UPPERCASE"

        // Release the key
        actions.keyUp(Keys.SHIFT).perform();
    }

    // Key up/down sequences
    public void keyUpDownSequences() {
        // Sequence: Press Ctrl, then A, then release Ctrl
        actions.keyDown(Keys.CONTROL)
               .sendKeys("a") // Select all
               .keyUp(Keys.CONTROL)
               .perform();

        // Complex sequence: Ctrl+Shift+Arrow
        actions.keyDown(Keys.CONTROL)
               .keyDown(Keys.SHIFT)
               .sendKeys(Keys.ARROW_RIGHT)
               .keyUp(Keys.SHIFT)
               .keyUp(Keys.CONTROL)
               .perform();
    }

    // Handle special keys
    public void handleSpecialKeys(WebElement element) {
        // Function keys
        actions.sendKeys(Keys.F1).perform(); // Help
        actions.sendKeys(Keys.F5).perform(); // Refresh
        actions.sendKeys(Keys.F11).perform(); // Fullscreen

        // Navigation keys
        element.sendKeys(Keys.HOME); // Move to beginning
        element.sendKeys(Keys.END);  // Move to end
        element.sendKeys(Keys.PAGE_UP);
        element.sendKeys(Keys.PAGE_DOWN);

        // System keys
        actions.sendKeys(Keys.ESCAPE).perform(); // Cancel/close
        actions.sendKeys(Keys.ENTER).perform();  // Submit
        actions.sendKeys(Keys.TAB).perform();    // Next field
        actions.sendKeys(Keys.BACK_SPACE).perform(); // Delete backward
        actions.sendKeys(Keys.DELETE).perform();     // Delete forward
    }

    // Copy and paste operations
    public void copyPasteOperations(WebElement source, WebElement target) {
        // Select all text in source
        source.click();
        actions.keyDown(Keys.CONTROL)
               .sendKeys("a")
               .keyUp(Keys.CONTROL)
               .perform();

        // Copy selected text
        actions.keyDown(Keys.CONTROL)
               .sendKeys("c")
               .keyUp(Keys.CONTROL)
               .perform();

        // Move to target and paste
        target.click();
        actions.keyDown(Keys.CONTROL)
               .sendKeys("v")
               .keyUp(Keys.CONTROL)
               .perform();

        // Verify paste operation
        String pastedText = target.getAttribute("value");
        System.out.println("Pasted text: " + pastedText);
    }

    // Typing special characters
    public void typeSpecialCharacters(WebElement element) {
        // Using Unicode characters
        element.sendKeys("Email: test@example.com");
        element.sendKeys("Price: $");
        element.sendKeys("Temperature: 25°C");
        element.sendKeys("Copyright: © 2024");
        element.sendKeys("Trademark: ™");
        element.sendKeys("Registered: ®");

        // Mathematical symbols
        element.sendKeys("π ≈ 3.14159");
        element.sendKeys("∑ x²");
        element.sendKeys("√16 = 4");

        // Currency symbols
        element.sendKeys("€100, £75, ¥10000, ₹500");
    }

    // Browser-specific keyboard shortcuts
    public void browserShortcuts() {
        // Chrome/Firefox shortcuts
        actions.keyDown(Keys.CONTROL) // Cmd on Mac
               .sendKeys("t") // New tab
               .keyUp(Keys.CONTROL)
               .perform();

        actions.keyDown(Keys.CONTROL)
               .sendKeys("w") // Close tab
               .keyUp(Keys.CONTROL)
               .perform();

        actions.keyDown(Keys.CONTROL)
               .sendKeys(Keys.F5) // Hard refresh
               .keyUp(Keys.CONTROL)
               .perform();
    }
}

import org.openqa.selenium.interactions.PointerInput;
import org.openqa.selenium.interactions.Sequence;
import java.time.Duration;
import java.util.Arrays;

public class MouseEvents {
    private WebDriver driver;
    private Actions actions;

    // Basic mouse operations
    public void basicMouseOperations() {
        WebElement element = driver.findElement(By.id("test-element"));

        // Left click
        actions.click(element).perform();

        // Double click
        actions.doubleClick(element).perform();

        // Right click (context menu)
        actions.contextClick(element).perform();

        // Click and hold
        actions.clickAndHold(element).perform();
        // ... do something while holding
        actions.release().perform();
    }

    // Mouse movement and hover
    public void mouseMovement() {
        WebElement menuItem = driver.findElement(By.id("menu-item"));
        WebElement submenu = driver.findElement(By.id("submenu"));

        // Move to element (hover)
        actions.moveToElement(menuItem).perform();

        // Wait for hover effect
        try { Thread.sleep(500); } catch (InterruptedException e) {}

        // Verify submenu appears
        assert submenu.isDisplayed();

        // Move to specific coordinates
        actions.moveByOffset(100, 50).perform();

        // Move to element with offset
        actions.moveToElement(menuItem, 10, 20).perform(); // 10px right, 20px down
    }

    // Advanced mouse events using W3C Actions API
    public void advancedMouseEvents() {
        // Create pointer input for mouse
        PointerInput mouse = new PointerInput(
            PointerInput.Kind.MOUSE, 
            "precision-mouse"
        );

        // Create sequence of actions
        Sequence sequence = new Sequence(mouse, 0);

        // Move to origin
        sequence.addAction(mouse.createPointerMove(
            Duration.ZERO,
            PointerInput.Origin.viewport(),
            0, 0
        ));

        // Press left button
        sequence.addAction(mouse.createPointerDown(
            PointerInput.MouseButton.LEFT.asArg()
        ));

        // Move while holding
        sequence.addAction(mouse.createPointerMove(
            Duration.ofMillis(1000),
            PointerInput.Origin.viewport(),
            500, 300
        ));

        // Release button
        sequence.addAction(mouse.createPointerUp(
            PointerInput.MouseButton.LEFT.asArg()
        ));

        // Execute sequence
        driver.perform(Arrays.asList(sequence));
    }

    // Mouse wheel operations
    public void mouseWheelOperations() {
        // Scroll down
        actions.scrollByAmount(0, 100).perform();

        // Scroll up
        actions.scrollByAmount(0, -100).perform();

        // Scroll horizontally
        actions.scrollByAmount(100, 0).perform();

        // Scroll to element
        WebElement footer = driver.findElement(By.id("footer"));
        actions.scrollToElement(footer).perform();

        // Scroll with modifier (Ctrl+Wheel for zoom)
        actions.keyDown(Keys.CONTROL)
               .scrollByAmount(0, -50) // Zoom in
               .keyUp(Keys.CONTROL)
               .perform();
    }

    // Pen events simulation (for touch devices/styluses)
    public void simulatePenEvents() {
        PointerInput pen = new PointerInput(
            PointerInput.Kind.PEN,
            "digital-pen"
        );

        Sequence penSequence = new Sequence(pen, 0);

        // Pen hover (before touching surface)
        penSequence.addAction(pen.createPointerMove(
            Duration.ZERO,
            PointerInput.Origin.viewport(),
            100, 100
        ));

        // Pen contact with surface
        penSequence.addAction(pen.createPointerDown(
            PointerInput.MouseButton.LEFT.asArg()
        ));

        // Draw a curved line
        penSequence.addAction(pen.createPointerMove(
            Duration.ofMillis(500),
            PointerInput.Origin.viewport(),
            200, 150
        ));

        penSequence.addAction(pen.createPointerMove(
            Duration.ofMillis(500),
            PointerInput.Origin.viewport(),
            300, 100
        ));

        // Add pressure variation (simulated)
        // Note: Real pressure data requires browser/device support

        // Lift pen
        penSequence.addAction(pen.createPointerUp(
            PointerInput.MouseButton.LEFT.asArg()
        ));

        driver.perform(Arrays.asList(penSequence));
    }
}

import org.openqa.selenium.Point;
import org.openqa.selenium.Rectangle;

public class DragAndDropOperations {
    private WebDriver driver;
    private Actions actions;

    // Basic drag and drop
    public void basicDragAndDrop(WebElement source, WebElement target) {
        // Simplest method
        actions.dragAndDrop(source, target).perform();

        // Alternative: manual implementation
        actions.clickAndHold(source)
               .moveToElement(target)
               .release()
               .perform();
    }

    // Drag and drop with offset
    public void dragAndDropByOffset(WebElement source, int xOffset, int yOffset) {
        // Move element by specific pixels
        actions.dragAndDropBy(source, xOffset, yOffset).perform();

        // Manual implementation with offset
        actions.clickAndHold(source)
               .moveByOffset(xOffset, yOffset)
               .release()
               .perform();
    }

    // Precision drag and drop
    public void precisionDragAndDrop(WebElement source, WebElement target) {
        // Get element positions and dimensions
        Point sourceLocation = source.getLocation();
        Dimension sourceSize = source.getSize();
        Point targetLocation = target.getLocation();
        Dimension targetSize = target.getSize();

        // Calculate center points
        int sourceCenterX = sourceLocation.getX() + sourceSize.getWidth() / 2;
        int sourceCenterY = sourceLocation.getY() + sourceSize.getHeight() / 2;
        int targetCenterX = targetLocation.getX() + targetSize.getWidth() / 2;
        int targetCenterY = targetLocation.getY() + targetSize.getHeight() / 2;

        // Calculate offset to move
        int xOffset = targetCenterX - sourceCenterX;
        int yOffset = targetCenterY - sourceCenterY;

        // Perform precise drag and drop
        actions.clickAndHold(source)
               .moveByOffset(xOffset, yOffset)
               .release()
               .perform();
    }

    // Sortable list operations
    public void reorderSortableList(String listId, int fromIndex, int toIndex) {
        WebElement list = driver.findElement(By.id(listId));
        List<WebElement> items = list.findElements(By.cssSelector(".sortable-item"));

        if (fromIndex < items.size() && toIndex < items.size()) {
            WebElement source = items.get(fromIndex);
            WebElement target = items.get(toIndex);

            // For vertical lists, drop below the target
            Rectangle targetRect = target.getRect();
            int dropY = targetRect.y + targetRect.height + 5; // 5px below

            actions.clickAndHold(source)
                   .moveByOffset(0, 10) // Initial move to start drag
                   .moveToLocation(targetRect.x, dropY)
                   .release()
                   .perform();
        }
    }

    // HTML5 drag and drop (for modern applications)
    public void html5DragAndDrop(WebElement source, WebElement target) {
        // JavaScript implementation for HTML5 DnD
        String jsCode = ""
            + "function createEvent(type) {"
            + "    var event = document.createEvent('CustomEvent');"
            + "    event.initCustomEvent(type, true, true, null);"
            + "    event.dataTransfer = {"
            + "        data: {},"
            + "        setData: function(key, value) {"
            + "            this.data[key] = value;"
            + "        },"
            + "        getData: function(key) {"
            + "            return this.data[key];"
            + "        }"
            + "    };"
            + "    return event;"
            + "}"
            + ""
            + "var source = arguments[0];"
            + "var target = arguments[1];"
            + ""
            + "// Dispatch dragstart event"
            + "var dragStartEvent = createEvent('dragstart');"
            + "source.dispatchEvent(dragStartEvent);"
            + ""
            + "// Dispatch dragover event"
            + "var dragOverEvent = createEvent('dragover');"
            + "target.dispatchEvent(dragOverEvent);"
            + ""
            + "// Dispatch drop event"
            + "var dropEvent = createEvent('drop');"
            + "dropEvent.dataTransfer = dragStartEvent.dataTransfer;"
            + "target.dispatchEvent(dropEvent);"
            + ""
            + "// Dispatch dragend event"
            + "var dragEndEvent = createEvent('dragend');"
            + "source.dispatchEvent(dragEndEvent);";

        JavascriptExecutor js = (JavascriptExecutor) driver;
        js.executeScript(jsCode, source, target);
    }

    // File drag and drop upload
    public void fileDragAndDropUpload(WebElement dropZone, String filePath) {
        // Make file input visible if hidden
        String makeVisibleJs = ""
            + "var input = document.createElement('input');"
            + "input.type = 'file';"
            + "input.multiple = true;"
            + "input.style.display = 'block';"
            + "arguments[0].appendChild(input);"
            + "return input;";

        JavascriptExecutor js = (JavascriptExecutor) driver;
        WebElement fileInput = (WebElement) js.executeScript(makeVisibleJs, dropZone);

        // Set file path
        fileInput.sendKeys(filePath);

        // Trigger drop event
        String triggerDropJs = ""
            + "var dropEvent = new DragEvent('drop', {"
            + "    bubbles: true,"
            + "    dataTransfer: {"
            + "        files: arguments[1].files"
            + "    }"
            + "});"
            + "arguments[0].dispatchEvent(dropEvent);";

        js.executeScript(triggerDropJs, dropZone, fileInput);
    }
}

import org.openqa.selenium.JavascriptExecutor;

public class ScrollOperations {
    private WebDriver driver;
    private Actions actions;
    private JavascriptExecutor js;

    public ScrollOperations(WebDriver driver) {
        this.driver = driver;
        this.actions = new Actions(driver);
        this.js = (JavascriptExecutor) driver;
    }

    // Basic scroll operations
    public void basicScrolling() {
        // Scroll down by pixels
        actions.scrollByAmount(0, 500).perform();

        // Scroll up
        actions.scrollByAmount(0, -500).perform();

        // Scroll horizontally
        actions.scrollByAmount(500, 0).perform();

        // Scroll to element
        WebElement footer = driver.findElement(By.id("footer"));
        actions.scrollToElement(footer).perform();
    }

    // JavaScript scrolling methods
    public void javascriptScrolling() {
        // Scroll to bottom of page
        js.executeScript("window.scrollTo(0, document.body.scrollHeight)");

        // Scroll to top
        js.executeScript("window.scrollTo(0, 0)");

        // Scroll to specific position
        js.executeScript("window.scrollTo(0, 1000)");

        // Scroll by specific amount
        js.executeScript("window.scrollBy(0, 500)");

        // Scroll element into view
        WebElement element = driver.findElement(By.id("hidden-element"));
        js.executeScript("arguments[0].scrollIntoView(true);", element);

        // Smooth scrolling
        js.executeScript(""
            + "arguments[0].scrollIntoView({"
            + "    behavior: 'smooth',"
            + "    block: 'center',"
            + "    inline: 'center'"
            + "});", element);
    }

    // Scroll within specific containers
    public void containerScrolling() {
        WebElement scrollableDiv = driver.findElement(By.cssSelector(".scrollable-container"));

        // Scroll to bottom of container
        js.executeScript("arguments[0].scrollTop = arguments[0].scrollHeight", scrollableDiv);

        // Scroll to specific position in container
        js.executeScript("arguments[0].scrollLeft = 500", scrollableDiv);

        // Get scroll position
        Long scrollTop = (Long) js.executeScript("return arguments[0].scrollTop", scrollableDiv);
        Long scrollLeft = (Long) js.executeScript("return arguments[0].scrollLeft", scrollableDiv);

        System.out.println("Scroll position - Top: " + scrollTop + ", Left: " + scrollLeft);
    }

    // Infinite scroll testing
    public void testInfiniteScroll() {
        long previousHeight;
        long currentHeight;
        int scrollAttempts = 0;
        int maxAttempts = 10;

        do {
            previousHeight = (Long) js.executeScript("return document.body.scrollHeight");

            // Scroll to bottom
            js.executeScript("window.scrollTo(0, document.body.scrollHeight)");

            // Wait for content to load
            try { Thread.sleep(2000); } catch (InterruptedException e) {}

            currentHeight = (Long) js.executeScript("return document.body.scrollHeight");
            scrollAttempts++;

            System.out.println("Attempt " + scrollAttempts + ": " + previousHeight + " -> " + currentHeight);

        } while (currentHeight > previousHeight && scrollAttempts < maxAttempts);

        System.out.println("Total scroll attempts: " + scrollAttempts);
    }

    // Mouse wheel scrolling simulation
    public void mouseWheelScrolling() {
        // Create wheel input
        PointerInput wheel = new PointerInput(
            PointerInput.Kind.WHEEL,
            "mouse-wheel"
        );

        // Scroll down
        Sequence scrollDown = new Sequence(wheel, 0);
        scrollDown.addAction(wheel.createScroll(
            Duration.ofMillis(100),
            PointerInput.Origin.viewport(),
            0, 100 // deltaX, deltaY
        ));
        driver.perform(Arrays.asList(scrollDown));

        // Scroll up
        Sequence scrollUp = new Sequence(wheel, 1);
        scrollUp.addAction(wheel.createScroll(
            Duration.ofMillis(100),
            PointerInput.Origin.viewport(),
            0, -100
        ));
        driver.perform(Arrays.asList(scrollUp));

        // Horizontal scroll (shift + wheel)
        actions.keyDown(Keys.SHIFT)
               .scrollByAmount(100, 0)
               .keyUp(Keys.SHIFT)
               .perform();
    }

    // Scroll performance testing
    public void measureScrollPerformance() {
        // Start timing
        long startTime = System.currentTimeMillis();

        // Perform multiple scroll operations
        for (int i = 0; i < 10; i++) {
            actions.scrollByAmount(0, 100).perform();
        }

        // End timing
        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;

        System.out.println("Scroll performance: " + duration + "ms for 10 scrolls");

        // Calculate frames per second (approximate)
        double fps = 10000.0 / duration; // 10 scrolls / duration in seconds
        System.out.println("Approximate FPS: " + String.format("%.1f", fps));
    }
}

