const { test, expect } = require('@playwright/test');
const pixelmatch = require('pixelmatch');
const { PNG } = require('pngjs');
const fs = require('fs');

async function compareScreenshots(page, testName) {
  // Capture current screenshot
  const currentScreenshot = await page.screenshot({
    path: `./screenshots/current/${testName}.png`,
    fullPage: true
  });

  // Load baseline screenshot
  const baselinePath = `./screenshots/baseline/${testName}.png`;

  if (!fs.existsSync(baselinePath)) {
    // No baseline exists, save current as baseline
    fs.writeFileSync(baselinePath, currentScreenshot);
    return { match: true, diff: 0, message: 'Baseline created' };
  }

  const baselineScreenshot = fs.readFileSync(baselinePath);

  // Parse PNG images
  const img1 = PNG.sync.read(currentScreenshot);
  const img2 = PNG.sync.read(baselineScreenshot);

  // Ensure same dimensions
  if (img1.width !== img2.width || img1.height !== img2.height) {
    return { match: false, diff: 100, message: 'Different dimensions' };
  }

  // Create diff image
  const diff = new PNG({ width: img1.width, height: img1.height });

  // Compare pixels
  const numDiffPixels = pixelmatch(
    img1.data, img2.data, diff.data,
    img1.width, img1.height,
    { threshold: 0.1 }
  );

  // Calculate difference percentage
  const totalPixels = img1.width * img1.height * 4;
  const diffPercentage = (numDiffPixels / totalPixels) * 100;

  // Save diff image if there are differences
  if (numDiffPixels > 0) {
    fs.writeFileSync(`./screenshots/diff/${testName}.png`, PNG.sync.write(diff));
  }

  return {
    match: diffPercentage < 1, // Less than 1% difference
    diff: diffPercentage,
    diffPixels: numDiffPixels,
    message: diffPercentage < 1 ? 'Visual match' : 'Visual mismatch'
  };
}

