// Simulating screen reader announcements
async function testScreenReaderAnnouncements(page) {
  const announcements = [];

  // Capture live region announcements
  await page.exposeFunction('logAnnouncement', (text) => {
    announcements.push({
      timestamp: Date.now(),
      text: text.trim(),
      type: 'live-region'
    });
  });

  await page.addInitScript(() => {
    // Override aria-live behavior to log announcements
    const originalSetAttribute = Element.prototype.setAttribute;
    Element.prototype.setAttribute = function(name, value) {
      originalSetAttribute.call(this, name, value);

      if (name === 'aria-live' && (value === 'polite' || value === 'assertive')) {
        // Log when live regions are created
        window.logAnnouncement(`Live region created: ${this.textContent}`);
      }
    };

    // Monitor DOM mutations for dynamic content
    const observer = new MutationObserver((mutations) => {
      mutations.forEach(mutation => {
        if (mutation.type === 'childList') {
          mutation.addedNodes.forEach(node => {
            if (node.nodeType === Node.ELEMENT_NODE && 
                (node.getAttribute('aria-live') === 'polite' || 
                 node.getAttribute('aria-live') === 'assertive')) {
              window.logAnnouncement(`Dynamic content: ${node.textContent}`);
            }
          });
        }
      });
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true
    });
  });

  return announcements;
}

// Testing ARIA attributes
async function testAriaAttributes(page) {
  const ariaIssues = await page.evaluate(() => {
    const issues = [];

    // Check for missing aria-labels on interactive elements
    const interactiveElements = document.querySelectorAll(
      'button, [role="button"], a, input, select, textarea'
    );

    interactiveElements.forEach(el => {
      const hasLabel = el.getAttribute('aria-label') || 
                      el.getAttribute('aria-labelledby') ||
                      el.textContent.trim().length > 0;

      if (!hasLabel && !el.hasAttribute('aria-hidden')) {
        issues.push({
          element: el.outerHTML.slice(0, 200),
          issue: 'Missing accessible name',
          type: 'missing-label'
        });
      }
    });

    // Check for invalid ARIA roles
    const elementsWithRole = document.querySelectorAll('[role]');
    const validRoles = [
      'button', 'checkbox', 'dialog', 'gridcell', 'link', 'listbox',
      'menu', 'menubar', 'menuitem', 'menuitemcheckbox', 'menuitemradio',
      'option', 'progressbar', 'radio', 'scrollbar', 'searchbox',
      'slider', 'spinbutton', 'switch', 'tab', 'tabpanel', 'textbox',
      'toolbar', 'tooltip', 'tree', 'treegrid', 'treeitem'
    ];

    elementsWithRole.forEach(el => {
      const role = el.getAttribute('role');
      if (!validRoles.includes(role)) {
        issues.push({
          element: el.outerHTML.slice(0, 200),
          issue: `Invalid ARIA role: ${role}`,
          type: 'invalid-role'
        });
      }
    });

    return issues;
  });

  return ariaIssues;
}

class CombinedUITestRunner {
  constructor(page, options = {}) {
    this.page = page;
    this.options = {
      visualTool: options.visualTool || 'applitools',
      accessibilityTool: options.accessibilityTool || 'axe',
      viewports: options.viewports || [
        { width: 1920, height: 1080, name: 'desktop' },
        { width: 768, height: 1024, name: 'tablet' },
        { width: 375, height: 667, name: 'mobile' }
      ],
      ...options
    };

    this.results = {
      visual: {},
      accessibility: {},
      combined: {}
    };
  }

  async testPage(url, testName) {
    console.log(`Testing: ${testName} (${url})`);

    await this.page.goto(url);

    // Run visual tests for each viewport
    this.results.visual = await this.runVisualTests(testName);

    // Run accessibility tests
    this.results.accessibility = await this.runAccessibilityTests(testName);

    // Generate combined report
    this.results.combined = this.generateCombinedReport();

    return this.results;
  }

  async runVisualTests(testName) {
    const visualResults = {};

    for (const viewport of this.options.viewports) {
      await this.page.setViewportSize(viewport);

      // Wait for stability
      await this.page.waitForLoadState('networkidle');
      await this.page.waitForTimeout(1000); // Wait for animations

      const viewportName = `${testName}_${viewport.name}`;

      if (this.options.visualTool === 'applitools') {
        // Use Applitools for visual testing
        const eyes = new Eyes();
        const config = eyes.getConfiguration();
        config.setApiKey(process.env.APPLITOOLS_API_KEY);
        config.setAppName(this.options.appName || 'MyApp');
        config.setTestName(viewportName);
        eyes.setConfiguration(config);

        await eyes.open(this.page);
        await eyes.check(viewportName, Target.window().fully());
        await eyes.close(false); // Don't throw on mismatch

        visualResults[viewport.name] = {
          tool: 'applitools',
          testName: viewportName,
          passed: true // Would check actual results in real implementation
        };
      } else {
        // Use custom visual comparison
        const screenshot = await this.page.screenshot({
          path: `./screenshots/current/${viewportName}.png`,
          fullPage: true
        });

        visualResults[viewport.name] = {
          tool: 'custom',
          screenshotPath: `./screenshots/current/${viewportName}.png`,
          timestamp: Date.now()
        };
      }
    }

    return visualResults;
  }

  async runAccessibilityTests(testName) {
    const accessibilityResults = {};

    if (this.options.accessibilityTool === 'axe') {
      const axeResults = await new axeBuilder({ page: this.page })
        .withTags(['wcag2a', 'wcag2aa'])
        .analyze();

      accessibilityResults.summary = {
        violations: axeResults.violations.length,
        passes: axeResults.passes.length,
        incomplete: axeResults.incomplete.length,
        inapplicable: axeResults.inapplicable.length
      };

      accessibilityResults.violations = axeResults.violations.map(v => ({
        id: v.id,
        impact: v.impact,
        description: v.description,
        helpUrl: v.helpUrl,
        nodes: v.nodes.length
      }));

      // Calculate accessibility score
      accessibilityResults.score = this.calculateAccessibilityScore(axeResults);
    }

    return accessibilityResults;
  }

  calculateAccessibilityScore(axeResults) {
    const totalChecks = axeResults.passes.length + axeResults.violations.length;
    if (totalChecks === 0) return 100;

    const violationWeight = {
      critical: 10,
      serious: 5,
      moderate: 2,
      minor: 1
    };

    let penalty = 0;
    axeResults.violations.forEach(violation => {
      penalty += violationWeight[violation.impact] || 1;
    });

    // Cap penalty at 50 points
    penalty = Math.min(penalty, 50);

    return Math.max(50, 100 - penalty); // Minimum score of 50
  }

  generateCombinedReport() {
    const visualPassed = Object.values(this.results.visual)
      .every(result => result.passed !== false);

    const accessibilityPassed = 
      this.results.accessibility.score >= (this.options.minAccessibilityScore || 80);

    return {
      overallPassed: visualPassed && accessibilityPassed,
      visualStatus: visualPassed ? 'PASS' : 'FAIL',
      accessibilityStatus: accessibilityPassed ? 'PASS' : 'FAIL',
      accessibilityScore: this.results.accessibility.score,
      criticalIssues: this.results.accessibility.violations
        .filter(v => v.impact === 'critical').length,
      recommendations: this.generateRecommendations()
    };
  }

  generateRecommendations() {
    const recommendations = [];

    // Visual recommendations
    if (Object.keys(this.results.visual).length === 0) {
      recommendations.push('No visual tests were run');
    }

    // Accessibility recommendations
    if (this.results.accessibility.violations) {
      const criticalViolations = this.results.accessibility.violations
        .filter(v => v.impact === 'critical');

      if (criticalViolations.length > 0) {
        recommendations.push(
          `Fix ${criticalViolations.length} critical accessibility issues before release`
        );
      }

      if (this.results.accessibility.score < 90) {
        recommendations.push(
          `Improve accessibility score from ${this.results.accessibility.score} to at least 90`
        );
      }
    }

    return recommendations;
  }
}

