// Advanced: Custom performance monitoring
class PerformanceMonitor {
  constructor() {
    this.metrics = {};
    this.performanceObserver = null;
    this.setupObservers();
  }

  setupObservers() {
    // Observe Largest Contentful Paint
    this.performanceObserver = new PerformanceObserver((entryList) => {
      const entries = entryList.getEntries();
      const lastEntry = entries[entries.length - 1];
      this.metrics.LCP = lastEntry.renderTime || lastEntry.loadTime;
    });
    this.performanceObserver.observe({ type: 'largest-contentful-paint', buffered: true });

    // Observe First Input Delay
    this.performanceObserver.observe({ type: 'first-input', buffered: true });
  }

  measureCustomMetrics() {
    // Navigation Timing API
    const navigationTiming = performance.getEntriesByType('navigation')[0];
    this.metrics = {
      TTFB: navigationTiming.responseStart - navigationTiming.requestStart,
      FCP: navigationTiming.domContentLoadedEventEnd - navigationTiming.fetchStart,
      DOMComplete: navigationTiming.domComplete,
      LoadTime: navigationTiming.loadEventEnd
    };

    // Resource Timing
    const resources = performance.getEntriesByType('resource');
    this.metrics.resourceCount = resources.length;
    this.metrics.totalResourceSize = resources.reduce((total, resource) => 
      total + (resource.transferSize || 0), 0
    );

    return this.metrics;
  }
}

