// .github/workflows/lighthouse-ci.yml
name: Lighthouse CI

on:
  push:
    branches: [ main, develop ]
  pull_request:
    branches: [ main ]
  schedule:
    - cron: '0 2 * * 1'  # Weekly on Monday at 2 AM

jobs:
  lighthouse:
    runs-on: ubuntu-latest

    steps:
    - name: Checkout code
      uses: actions/checkout@v3
      with:
        fetch-depth: 0

    - name: Setup Node.js
      uses: actions/setup-node@v3
      with:
        node-version: '18'
        cache: 'npm'

    - name: Install dependencies
      run: npm ci

    - name: Start application
      run: |
        npm start &
        sleep 10  # Wait for app to start

    - name: Run Lighthouse CI
      uses: treosh/lighthouse-ci-action@v9
      with:
        configPath: './.lighthouserc.json'
        uploadArtifacts: true
        temporaryPublicStorage: true
        runs: 3  # Run 3 times for consistent results
        serverBaseUrl: 'http://localhost:3000'
        urls: |
          /
          /products
          /about

    - name: Check performance budget
      run: |
        # Parse Lighthouse results and check against budget
        npm run check-performance-budget

    - name: Upload Lighthouse reports
      uses: actions/upload-artifact@v3
      with:
        name: lighthouse-reports
        path: '.lighthouseci/'
        retention-days: 30

    - name: Comment PR with results
      if: github.event_name == 'pull_request'
      uses: actions/github-script@v6
      with:
        script: |
          const fs = require('fs');
          const path = require('path');

          // Read Lighthouse results
          const resultsPath = path.join('.lighthouseci', 'manifest.json');
          const manifest = JSON.parse(fs.readFileSync(resultsPath, 'utf8'));

          // Generate summary
          const summary = manifest.map(result => {
            const report = JSON.parse(fs.readFileSync(
              path.join('.lighthouseci', result.reportPath),
              'utf8'
            ));

            return {
              url: result.url,
              performance: Math.round(report.categories.performance.score * 100),
              accessibility: Math.round(report.categories.accessibility.score * 100),
              bestPractices: Math.round(report.categories['best-practices'].score * 100),
              seo: Math.round(report.categories.seo.score * 100)
            };
          });

          const comment = `
          ## Lighthouse CI Results

          ${summary.map(s => `
          ### ${s.url}
          - Performance: ${s.performance}/100
          - Accessibility: ${s.accessibility}/100
          - Best Practices: ${s.bestPractices}/100
          - SEO: ${s.seo}/100
          `).join('')}

          [View detailed reports ↗](https://github.com/${{ github.repository }}/actions/runs/${{ github.run_id }})
          `;

          github.rest.issues.createComment({
            issue_number: context.issue.number,
            owner: context.repo.owner,
            repo: context.repo.repo,
            body: comment
          });

