// rum-collector.js - Collect RUM data from browsers
const express = require('express');
const app = express();
app.use(express.json());

// Store for RUM data
const rumData = [];

// Endpoint to receive RUM data
app.post('/collect', (req, res) => {
  const data = req.body;

  // Validate and sanitize data
  const validatedData = {
    timestamp: new Date().toISOString(),
    sessionId: data.sessionId,
    pageUrl: data.pageUrl,
    userAgent: data.userAgent,
    device: data.device,
    connection: data.connection,
    metrics: {
      LCP: validateNumber(data.metrics?.LCP),
      FID: validateNumber(data.metrics?.FID),
      CLS: validateNumber(data.metrics?.CLS),
      FCP: validateNumber(data.metrics?.FCP),
      TTFB: validateNumber(data.metrics?.TTFB),
      TBT: validateNumber(data.metrics?.TBT)
    },
    customEvents: data.customEvents || [],
    errors: data.errors || []
  };

  // Store data
  rumData.push(validatedData);

  // Keep only last 10000 records
  if (rumData.length > 10000) {
    rumData.splice(0, rumData.length - 10000);
  }

  res.status(200).json({ success: true });
});

// Analytics endpoint
app.get('/analytics', (req, res) => {
  const { startDate, endDate, pageUrl } = req.query;

  let filteredData = rumData;

  // Filter by date range
  if (startDate && endDate) {
    filteredData = filteredData.filter(record => 
      new Date(record.timestamp) >= new Date(startDate) &&
      new Date(record.timestamp) <= new Date(endDate)
    );
  }

  // Filter by page URL
  if (pageUrl) {
    filteredData = filteredData.filter(record => 
      record.pageUrl.includes(pageUrl)
    );
  }

  // Calculate metrics
  const metrics = ['LCP', 'FID', 'CLS', 'FCP', 'TTFB', 'TBT'];
  const analytics = {
    totalSamples: filteredData.length,
    averages: {},
    percentiles: {},
    byConnection: {},
    byDevice: {},
    alerts: []
  };

  // Calculate averages and percentiles
  metrics.forEach(metric => {
    const values = filteredData
      .map(d => d.metrics[metric])
      .filter(v => v !== null && v !== undefined);

    if (values.length > 0) {
      analytics.averages[metric] = values.reduce((a, b) => a + b, 0) / values.length;

      // Calculate 75th and 95th percentiles
      const sorted = values.sort((a, b) => a - b);
      analytics.percentiles[metric] = {
        p75: sorted[Math.floor(sorted.length * 0.75)],
        p95: sorted[Math.floor(sorted.length * 0.95)]
      };

      // Check for performance issues
      const threshold = getThresholdForMetric(metric);
      if (analytics.averages[metric] > threshold) {
        analytics.alerts.push({
          metric,
          value: analytics.averages[metric],
          threshold,
          severity: 'warning'
        });
      }
    }
  });

  // Group by connection type
  const connections = {};
  filteredData.forEach(record => {
    const conn = record.connection || 'unknown';
    if (!connections[conn]) connections[conn] = [];
    connections[conn].push(record);
  });

  Object.keys(connections).forEach(conn => {
    analytics.byConnection[conn] = {
      count: connections[conn].length,
      avgLCP: connections[conn].reduce((sum, r) => sum + (r.metrics.LCP || 0), 0) / connections[conn].length
    };
  });

  res.json(analytics);
});

function validateNumber(value) {
  const num = Number(value);
  return isNaN(num) ? null : num;
}

function getThresholdForMetric(metric) {
  const thresholds = {
    LCP: 2500,
    FID: 100,
    CLS: 0.1,
    FCP: 1000,
    TTFB: 600,
    TBT: 200
  };
  return thresholds[metric] || Infinity;
}

// Start server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`RUM collector listening on port ${PORT}`);
});

// Client-side RUM collection script
// rum-client.js - To be included in web pages
(function() {
  'use strict';

  const RUM = {
    config: {
      endpoint: '/collect',
      sampleRate: 1.0, // 100% sampling
      sessionTimeout: 30 * 60 * 1000, // 30 minutes
      metricsToTrack: ['LCP', 'FID', 'CLS', 'FCP', 'TTFB']
    },

    sessionId: null,
    data: {
      pageUrl: window.location.href,
      userAgent: navigator.userAgent,
      device: {
        screen: `${window.screen.width}x${window.screen.height}`,
        viewport: `${window.innerWidth}x${window.innerHeight}`
      },
      connection: navigator.connection ? {
        effectiveType: navigator.connection.effectiveType,
        downlink: navigator.connection.downlink,
        rtt: navigator.connection.rtt
      } : null,
      metrics: {},
      customEvents: [],
      errors: []
    },

    init() {
      this.generateSessionId();
      this.setupErrorHandling();
      this.setupPerformanceObservers();
      this.setupVisibilityChange();
      this.setupBeforeUnload();

      // Sample rate check
      if (Math.random() > this.config.sampleRate) {
        return;
      }

      this.collectInitialMetrics();
    },

    generateSessionId() {
      const storedSession = sessionStorage.getItem('rum_session');
      const storedTime = sessionStorage.getItem('rum_session_time');

      if (storedSession && storedTime && 
          Date.now() - parseInt(storedTime) < this.config.sessionTimeout) {
        this.sessionId = storedSession;
      } else {
        this.sessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
        sessionStorage.setItem('rum_session', this.sessionId);
        sessionStorage.setItem('rum_session_time', Date.now().toString());
      }
    },

    setupPerformanceObservers() {
      // LCP observer
      new PerformanceObserver((entryList) => {
        const entries = entryList.getEntries();
        const lastEntry = entries[entries.length - 1];
        this.data.metrics.LCP = lastEntry.renderTime || lastEntry.loadTime;
      }).observe({ type: 'largest-contentful-paint', buffered: true });

      // CLS observer
      let clsValue = 0;
      new PerformanceObserver((entryList) => {
        for (const entry of entryList.getEntries()) {
          if (!entry.hadRecentInput) {
            clsValue += entry.value;
          }
        }
        this.data.metrics.CLS = clsValue;
      }).observe({ type: 'layout-shift', buffered: true });

      // FID observer
      new PerformanceObserver((entryList) => {
        for (const entry of entryList.getEntries()) {
          this.data.metrics.FID = entry.processingStart - entry.startTime;
        }
      }).observe({ type: 'first-input', buffered: true });
    },

    collectInitialMetrics() {
      // Navigation timing
      const navigation = performance.getEntriesByType('navigation')[0];
      if (navigation) {
        this.data.metrics.TTFB = navigation.responseStart - navigation.requestStart;
        this.data.metrics.FCP = navigation.domContentLoadedEventEnd - navigation.fetchStart;
      }
    },

    setupErrorHandling() {
      // JavaScript errors
      window.addEventListener('error', (event) => {
        this.data.errors.push({
          type: 'javascript',
          message: event.message,
          filename: event.filename,
          lineno: event.lineno,
          colno: event.colno,
          timestamp: new Date().toISOString()
        });
      });

      // Promise rejections
      window.addEventListener('unhandledrejection', (event) => {
        this.data.errors.push({
          type: 'promise',
          reason: event.reason?.toString(),
          timestamp: new Date().toISOString()
        });
      });

      // Resource errors
      window.addEventListener('error', (event) => {
        if (event.target && (event.target.tagName === 'IMG' || 
            event.target.tagName === 'SCRIPT' || 
            event.target.tagName === 'LINK')) {
          this.data.errors.push({
            type: 'resource',
            tag: event.target.tagName,
            src: event.target.src || event.target.href,
            timestamp: new Date().toISOString()
          });
        }
      }, true);
    },

    setupVisibilityChange() {
      document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
          this.sendData();
        }
      });
    },

    setupBeforeUnload() {
      window.addEventListener('beforeunload', () => {
        // Use sendBeacon for reliable delivery on page unload
        this.sendData(true);
      });
    },

    sendData(useBeacon = false) {
      const data = {
        sessionId: this.sessionId,
        ...this.data
      };

      const url = this.config.endpoint;
      const body = JSON.stringify(data);

      if (useBeacon && navigator.sendBeacon) {
        navigator.sendBeacon(url, body);
      } else {
        // Use fetch with keepalive
        fetch(url, {
          method: 'POST',
          body: body,
          headers: {
            'Content-Type': 'application/json'
          },
          keepalive: true
        }).catch(console.error);
      }
    },

    trackEvent(name, properties = {}) {
      this.data.customEvents.push({
        name,
        properties,
        timestamp: new Date().toISOString()
      });
    }
  };

  // Initialize when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => RUM.init());
  } else {
    RUM.init();
  }

  // Expose to global scope for manual event tracking
  window.RUM = RUM;
})();

