        choice(name: 'BROWSER', choices: ['chrome', 'firefox', 'edge', 'all'], description: 'Browser to test on')
        choice(name: 'ENVIRONMENT', choices: ['staging', 'production', 'development'], description: 'Environment to test')
        booleanParam(name: 'RUN_VISUAL_TESTS', defaultValue: true, description: 'Run visual regression tests')
        booleanParam(name: 'RUN_PERFORMANCE_TESTS', defaultValue: false, description: 'Run performance tests')
        booleanParam(name: 'RUN_ACCESSIBILITY_TESTS', defaultValue: true, description: 'Run accessibility tests')
        string(name: 'TEST_TAGS', defaultValue: '', description: 'Specific tags to run (comma-separated)')
    }

    stages {
        // Stage 1: Code checkout and setup
        stage('Checkout & Setup') {
            steps {
                script {
                    // Clean workspace
                    cleanWs()

                    // Checkout source code
                    checkout([
                        $class: 'GitSCM',
                        branches: [[name: env.GIT_BRANCH ?: '*/main']],
                        extensions: [
                            [$class: 'RelativeTargetDirectory', relativeTargetDir: 'src'],
                            [$class: 'LocalBranch', localBranch: true],
                            [$class: 'CloneOption', depth: 1, noTags: true, shallow: true]
