// flaky-test-manager.js
const fs = require('fs');
const path = require('path');
const { exec } = require('child_process');
const { promisify } = require('util');
const execAsync = promisify(exec);

class FlakyTestManager {
  constructor(config) {
    this.config = {
      testRunsThreshold: 10,        // Minimum runs to analyze
      flakinessThreshold: 0.1,      // 10% flakiness rate
      quarantineThreshold: 0.3,     // 30% flakiness rate
      maxRetries: 3,               // Maximum retries for suspected flaky tests
      analysisWindow: 30,          // Days to analyze
      dataFile: '.flaky-test-data.json',
      quarantineFile: '.quarantine-tests.json',
      ...config
    };

    this.testData = this.loadTestData();
    this.quarantinedTests = this.loadQuarantinedTests();
  }

  loadTestData() {
    try {
      if (fs.existsSync(this.config.dataFile)) {
        return JSON.parse(fs.readFileSync(this.config.dataFile, 'utf8'));
      }
    } catch (error) {
      console.error('Error loading test data:', error.message);
    }
    return {};
  }

  loadQuarantinedTests() {
    try {
      if (fs.existsSync(this.config.quarantineFile)) {
        return JSON.parse(fs.readFileSync(this.config.quarantineFile, 'utf8'));
      }
    } catch (error) {
      console.error('Error loading quarantined tests:', error.message);
    }
    return [];
  }

  saveTestData() {
    try {
      fs.writeFileSync(
        this.config.dataFile, 
        JSON.stringify(this.testData, null, 2)
      );
    } catch (error) {
      console.error('Error saving test data:', error.message);
    }
  }

  saveQuarantinedTests() {
    try {
      fs.writeFileSync(
        this.config.quarantineFile, 
        JSON.stringify(this.quarantinedTests, null, 2)
      );
    } catch (error) {
      console.error('Error saving quarantined tests:', error.message);
    }
  }

  async recordTestRun(testFile, testName, passed, duration, metadata = {}) {
    const testKey = `${testFile}::${testName}`;

    if (!this.testData[testKey]) {
      this.testData[testKey] = {
        file: testFile,
        name: testName,
        runs: [],
        statistics: {
          totalRuns: 0,
          passedRuns: 0,
          failedRuns: 0,
          flakyRuns: 0,
          avgDuration: 0,
          lastUpdated: new Date().toISOString()
        }
      };
    }

    const test = this.testData[testKey];

    // Add run record
    test.runs.push({
      timestamp: new Date().toISOString(),
      passed,
      duration,
      metadata
    });

    // Keep only recent runs within analysis window
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - this.config.analysisWindow);

    test.runs = test.runs.filter(run => 
      new Date(run.timestamp) > cutoffDate
    );

    // Update statistics
    this.updateTestStatistics(testKey);

    // Check for flakiness
    await this.checkForFlakiness(testKey);

    // Save updated data
    this.saveTestData();
  }

  updateTestStatistics(testKey) {
    const test = this.testData[testKey];
    const runs = test.runs;

    if (runs.length === 0) return;

    const totalRuns = runs.length;
    const passedRuns = runs.filter(r => r.passed).length;
    const failedRuns = totalRuns - passedRuns;

    // Calculate flaky runs (runs that have both pass and fail outcomes)
    let flakyRuns = 0;
    if (passedRuns > 0 && failedRuns > 0) {
      // A test is considered flaky if it has both passes and failures
      flakyRuns = Math.min(passedRuns, failedRuns) * 2;
    }

    const avgDuration = runs.reduce((sum, r) => sum + r.duration, 0) / totalRuns;

    test.statistics = {
      totalRuns,
      passedRuns,
      failedRuns,
      flakyRuns,
      avgDuration,
      passRate: (passedRuns / totalRuns) * 100,
      flakinessRate: (flakyRuns / totalRuns) * 100,
      lastUpdated: new Date().toISOString()
    };
  }

  async checkForFlakiness(testKey) {
    const test = this.testData[testKey];
    const stats = test.statistics;

    if (stats.totalRuns < this.config.testRunsThreshold) {
      return; // Not enough data
    }

    const flakinessRate = stats.flakinessRate;

    // Check if test should be quarantined
    if (flakinessRate >= this.config.quarantineThreshold * 100) {
      await this.quarantineTest(testKey, 'high_flakiness_rate');
    } 
    // Check if test is flaky but not quarantine-level
    else if (flakinessRate >= this.config.flakinessThreshold * 100) {
      await this.flagFlakyTest(testKey, 'moderate_flakiness_rate');
    }

    // Check for temporal patterns (fails at certain times)
    const temporalPattern = this.detectTemporalPattern(test.runs);
    if (temporalPattern) {
      await this.flagFlakyTest(testKey, `temporal_pattern_${temporalPattern}`);
    }

    // Check for environmental dependencies
    const envPattern = this.detectEnvironmentalPattern(test.runs);
    if (envPattern) {
      await this.flagFlakyTest(testKey, `environmental_pattern_${envPattern}`);
    }
  }

  detectTemporalPattern(runs) {
    // Analyze if tests fail at certain times
    const failuresByHour = new Array(24).fill(0);
    const passesByHour = new Array(24).fill(0);

    runs.forEach(run => {
      const hour = new Date(run.timestamp).getHours();
      if (run.passed) {
        passesByHour[hour]++;
      } else {
        failuresByHour[hour]++;
      }
    });

    // Find hours with disproportionate failure rates
    for (let hour = 0; hour < 24; hour++) {
      const total = failuresByHour[hour] + passesByHour[hour];
      if (total > 5) { // At least 5 runs in this hour
        const failureRate = failuresByHour[hour] / total;
        if (failureRate > 0.7) { // 70% failure rate in this hour
          return `hour_${hour}`;
        }
      }
    }

    return null;
  }

  detectEnvironmentalPattern(runs) {
    // Check if failures correlate with environmental factors
    const factors = {};

    runs.forEach(run => {
      const metadata = run.metadata || {};
      Object.keys(metadata).forEach(key => {
        const value = metadata[key];
        const factorKey = `${key}=${value}`;

        if (!factors[factorKey]) {
          factors[factorKey] = { total: 0, failures: 0 };
        }

        factors[factorKey].total++;
        if (!run.passed) {
          factors[factorKey].failures++;
        }
      });
    });

    // Find factors with high failure rates
    for (const [factor, data] of Object.entries(factors)) {
      if (data.total >= 3) { // At least 3 occurrences
        const failureRate = data.failures / data.total;
        if (failureRate > 0.8) { // 80% failure rate with this factor
          return factor;
        }
      }
    }

    return null;
  }

  async quarantineTest(testKey, reason) {
    const test = this.testData[testKey];

    // Check if already quarantined
    const alreadyQuarantined = this.quarantinedTests.some(
      q => q.testKey === testKey
    );

    if (!alreadyQuarantined) {
      console.log(`🚨 Quarantining test: ${test.name} (${reason})`);

      this.quarantinedTests.push({
        testKey,
        testFile: test.file,
        testName: test.name,
        reason,
        quarantinedAt: new Date().toISOString(),
        statistics: test.statistics,
        lastRuns: test.runs.slice(-5)
      });

      // Keep only recent quarantines
      this.quarantinedTests = this.quarantinedTests.slice(-100);

      this.saveQuarantinedTests();

      // Notify team (in real implementation, this would send to Slack/email)
      await this.notifyTeam('quarantine', test, reason);
    }
  }

  async flagFlakyTest(testKey, reason) {
    const test = this.testData[testKey];

    console.log(`⚠️  Flagging flaky test: ${test.name} (${reason})`);

    // Add flaky flag to test data
    if (!test.flags) {
      test.flags = [];
    }

    if (!test.flags.includes(reason)) {
      test.flags.push(reason);
      test.lastFlagged = new Date().toISOString();

      // Notify team
      await this.notifyTeam('flaky', test, reason);
    }
  }

  async notifyTeam(type, test, reason) {
    // In a real implementation, this would send notifications
    // For now, just log
    const message = type === 'quarantine' 
      ? `Test quarantined: ${test.name}\nReason: ${reason}\nPass rate: ${test.statistics.passRate.toFixed(1)}%`
      : `Flaky test detected: ${test.name}\nReason: ${reason}\nFlakiness rate: ${test.statistics.flakinessRate.toFixed(1)}%`;

    console.log(`\n📢 Notification:\n${message}\n`);
  }

  async runWithFlakyDetection(testFile, testName, testFn) {
    let lastError = null;
    let attempts = 0;
    const maxAttempts = this.config.maxRetries + 1;

    // Check if test is quarantined
    const isQuarantined = this.quarantinedTests.some(
      q => q.testFile === testFile && q.testName === testName
    );

    if (isQuarantined) {
      console.log(`⏸️  Skipping quarantined test: ${testName}`);
      return {
        skipped: true,
        reason: 'quarantined',
        testFile,
        testName
      };
    }

    // Check if test is flaky (based on history)
    const testKey = `${testFile}::${testName}`;
    const testData = this.testData[testKey];
    const isSuspectedFlaky = testData && 
      testData.statistics.flakinessRate >= this.config.flakinessThreshold * 100;

    const startTime = Date.now();

    while (attempts < maxAttempts) {
      attempts++;

      try {
        const result = await testFn();
        const duration = Date.now() - startTime;

        // Record successful run
        await this.recordTestRun(testFile, testName, true, duration, {
          attempts,
          suspectedFlaky: isSuspectedFlaky
        });

        return {
          passed: true,
          attempts,
          duration,
          testFile,
          testName
        };

      } catch (error) {
        lastError = error;
        const duration = Date.now() - startTime;

        // If this is the last attempt, record failure
        if (attempts === maxAttempts) {
          await this.recordTestRun(testFile, testName, false, duration, {
            attempts,
            error: error.message,
            suspectedFlaky: isSuspectedFlaky
          });

          return {
            passed: false,
            attempts,
            duration,
            error: error.message,
            testFile,
            testName
          };
        }

        // Exponential backoff before retry
        const backoffTime = Math.pow(2, attempts) * 100;
        console.log(`Retrying ${testName} in ${backoffTime}ms (attempt ${attempts}/${maxAttempts})`);
        await new Promise(resolve => setTimeout(resolve, backoffTime));
      }
    }
  }

  generateFlakyTestReport() {
    const now = new Date();
    const flakyTests = [];
    const quarantinedTests = this.quarantinedTests;

    // Find flaky tests (not quarantined)
    Object.entries(this.testData).forEach(([testKey, test]) => {
      const stats = test.statistics;

      if (stats.totalRuns >= this.config.testRunsThreshold &&
          stats.flakinessRate >= this.config.flakinessThreshold * 100) {

        // Check if not quarantined
        const isQuarantined = quarantinedTests.some(
          q => q.testKey === testKey
        );

        if (!isQuarantined) {
          flakyTests.push({
            testKey,
            ...test,
            quarantined: false
          });
        }
      }
    });

    // Generate report
    const report = {
      generatedAt: now.toISOString(),
      summary: {
        totalTestsTracked: Object.keys(this.testData).length,
        flakyTests: flakyTests.length,
        quarantinedTests: quarantinedTests.length,
        totalRuns: Object.values(this.testData)
          .reduce((sum, test) => sum + test.statistics.totalRuns, 0),
        flakyRunPercentage: (Object.values(this.testData)
          .reduce((sum, test) => sum + test.statistics.flakyRuns, 0) /
          Object.values(this.testData)
            .reduce((sum, test) => sum + test.statistics.totalRuns, 0) * 100
        ).toFixed(2)
      },
      flakyTests: flakyTests.map(test => ({
        file: test.file,
        name: test.name,
        statistics: test.statistics,
        flags: test.flags || []
      })),
      quarantinedTests: quarantinedTests.map(test => ({
        file: test.testFile,
        name: test.testName,
        reason: test.reason,
        quarantinedAt: test.quarantinedAt,
        statistics: test.statistics
      })),
      recommendations: this.generateRecommendations(flakyTests, quarantinedTests)
    };

    return report;
  }

  generateRecommendations(flakyTests, quarantinedTests) {
    const recommendations = [];

    // General recommendations
    if (flakyTests.length > 10) {
      recommendations.push({
        type: 'critical',
        message: `High number of flaky tests (${flakyTests.length}). Consider implementing better test isolation.`
      });
    }

    if (quarantinedTests.length > 5) {
      recommendations.push({
        type: 'warning',
        message: `${quarantinedTests.length} tests are quarantined and need attention.`
      });
    }

    // Specific recommendations based on patterns
    const temporalTests = flakyTests.filter(test => 
      test.flags && test.flags.some(flag => flag.startsWith('temporal_pattern_'))
    );

    if (temporalTests.length > 0) {
      recommendations.push({
        type: 'info',
        message: `${temporalTests.length} tests show temporal patterns. Check for time-dependent logic.`
      });
    }

    const envTests = flakyTests.filter(test => 
      test.flags && test.flags.some(flag => flag.startsWith('environmental_pattern_'))
    );

    if (envTests.length > 0) {
      recommendations.push({
        type: 'info',
        message: `${envTests.length} tests show environmental dependencies. Check for external service dependencies.`
      });
    }

    return recommendations;
  }
}

// Usage example
async function exampleUsage() {
  const manager = new FlakyTestManager({
    dataFile: './.flaky-test-data.json',
    quarantineFile: './.quarantine-tests.json'
  });

  // Example test function
  async function runExampleTest() {
    // Simulate a flaky test
    const random = Math.random();
    if (random < 0.3) { // 30% chance of failure
      throw new Error('Random test failure');
    }
    return 'Test passed';
  }

  // Run test with flaky detection
  const result = await manager.runWithFlakyDetection(
    'example.test.js',
    'should pass randomly',
    runExampleTest
  );

  console.log('Test result:', result);

  // Generate report
  const report = manager.generateFlakyTestReport();
  console.log('\nFlaky Test Report:');
  console.log(JSON.stringify(report, null, 2));

  // Save reports
  fs.writeFileSync('./flaky-report.json', JSON.stringify(report, null, 2));
}

