package com.appiumsetup.config;

import io.appium.java_client.remote.AndroidMobileCapabilityType;
import io.appium.java_client.remote.IOSMobileCapabilityType;
import io.appium.java_client.remote.MobileCapabilityType;
import org.openqa.selenium.remote.DesiredCapabilities;

import java.io.File;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;

/**
 * Comprehensive capabilities management system for enterprise mobile automation.
 * This class demonstrates professional patterns for capability configuration,
 * including validation, environment-specific overrides, and security best practices.
 */
public class EnterpriseCapabilitiesManager {

    // Configuration constants loaded from properties or environment
    private static final Properties CONFIG = loadConfiguration();

    // Platform constants
    private static final String PLATFORM_ANDROID = "ANDROID";
    private static final String PLATFORM_IOS = "IOS";

    // Environment constants
    private static final String ENV_DEV = "DEV";
    private static final String ENV_TEST = "TEST";
    private static final String ENV_STAGING = "STAGING";
    private static final String ENV_PROD = "PROD";

    // Test type constants
    private static final String TEST_TYPE_SMOKE = "SMOKE";
    private static final String TEST_TYPE_REGRESSION = "REGRESSION";
    private static final String TEST_TYPE_PERFORMANCE = "PERFORMANCE";
    private static final String TEST_TYPE_ACCESSIBILITY = "ACCESSIBILITY";

    /**
     * Main entry point: Get capabilities for a specific test scenario
     */
    public static DesiredCapabilities getCapabilities(String platform, 
                                                     String environment,
                                                     String testType,
                                                     Map<String, Object> overrides) {

        // Validate inputs
        validateInputs(platform, environment, testType);

        // Get base capabilities for the platform
        DesiredCapabilities caps = getBaseCapabilities(platform);

        // Apply environment-specific configurations
        applyEnvironmentConfig(caps, environment);

        // Apply test type optimizations
        applyTestTypeConfig(caps, testType);

        // Apply any runtime overrides
        if (overrides != null && !overrides.isEmpty()) {
            applyOverrides(caps, overrides);
        }

        // Validate final capability set
        validateCapabilities(caps);

        return caps;
    }

    /**
     * Get base capabilities for a platform
     */
    private static DesiredCapabilities getBaseCapabilities(String platform) {
        DesiredCapabilities caps = new DesiredCapabilities();

        if (PLATFORM_ANDROID.equalsIgnoreCase(platform)) {
            configureAndroidBaseCapabilities(caps);
        } else if (PLATFORM_IOS.equalsIgnoreCase(platform)) {
            configureIOSBaseCapabilities(caps);
        }

        return caps;
    }

    /**
     * Configure Android-specific base capabilities
     */
    private static void configureAndroidBaseCapabilities(DesiredCapabilities caps) {
        // Required capabilities
        caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "Android");
        caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "UiAutomator2");

        // Performance defaults
        caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
        caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, true);
        caps.setCapability(AndroidMobileCapabilityType.IGNORE_UNIMPORTANT_VIEWS, true);

        // Input settings
        caps.setCapability(AndroidMobileCapabilityType.UNICODE_KEYBOARD, true);
        caps.setCapability(AndroidMobileCapabilityType.RESET_KEYBOARD, true);

        // Reset behavior
        caps.setCapability(MobileCapabilityType.NO_RESET, false);
        caps.setCapability(MobileCapabilityType.FULL_RESET, false);

        // Debugging (disabled by default, enabled via environment)
        caps.setCapability(MobileCapabilityType.PRINT_PAGE_SOURCE_ON_FIND_FAILURE, false);

        // Appium 2.0+ specific (using appium: prefix)
        caps.setCapability("appium:enforceXPath1", false);
        caps.setCapability("appium:disableWindowAnimation", true);
    }

    /**
     * Configure iOS-specific base capabilities
     */
    private static void configureIOSBaseCapabilities(DesiredCapabilities caps) {
        // Required capabilities
        caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "iOS");
        caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "XCUITest");

        // Performance defaults
        caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
        caps.setCapability(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS, true);
        caps.setCapability(IOSMobileCapabilityType.REDUCE_MOTION, true);

        // WebDriverAgent configuration
        caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, 8100);
        caps.setCapability(IOSMobileCapabilityType.USE_NEW_WDA, true);
        caps.setCapability(IOSMobileCapabilityType.WDA_LAUNCH_TIMEOUT, 120000);

        // Reset behavior
        caps.setCapability(MobileCapabilityType.NO_RESET, false);
        caps.setCapability(MobileCapabilityType.FULL_RESET, false);

        // Debugging (disabled by default)
        caps.setCapability(IOSMobileCapabilityType.SHOW_XCODE_LOG, false);

        // Safari web view support
        caps.setCapability(IOSMobileCapabilityType.INCLUDE_SAFARI_IN_WEB_VIEWS, true);
        caps.setCapability(IOSMobileCapabilityType.START_IWDP, true);
    }

    /**
     * Apply environment-specific configurations
     */
    private static void applyEnvironmentConfig(DesiredCapabilities caps, String environment) {
        switch (environment.toUpperCase()) {
            case ENV_DEV:
                // Development environment: Fast, preserves state
                caps.setCapability(MobileCapabilityType.NO_RESET, true);
                caps.setCapability(MobileCapabilityType.FULL_RESET, false);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 600); // Longer for debugging
                break;

            case ENV_TEST:
            case ENV_STAGING:
                // Test/Staging: Balanced approach
                caps.setCapability(MobileCapabilityType.NO_RESET, false);
                caps.setCapability(MobileCapabilityType.FULL_RESET, false);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
                break;

            case ENV_PROD:
                // Production-like: Clean state, security focused
                caps.setCapability(MobileCapabilityType.NO_RESET, false);
                caps.setCapability(MobileCapabilityType.FULL_RESET, true);
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 180);
                // Disable auto permissions in prod-like tests
                if (caps.getCapability(MobileCapabilityType.PLATFORM_NAME).equals("Android")) {
                    caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, false);
                }
                break;
        }

        // Set app path based on environment
        String appPath = getAppPathForEnvironment(
            (String) caps.getCapability(MobileCapabilityType.PLATFORM_NAME),
            environment
        );

        if (appPath != null && new File(appPath).exists()) {
            caps.setCapability(MobileCapabilityType.APP, appPath);
        }
    }

    /**
     * Apply optimizations for different test types
     */
    private static void applyTestTypeConfig(DesiredCapabilities caps, String testType) {
        switch (testType.toUpperCase()) {
            case TEST_TYPE_SMOKE:
                // Smoke tests: Fast execution
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 120);
                caps.setCapability("appium:skipUnlock", true);
                caps.setCapability("appium:skipDeviceInitialization", true);
                break;

            case TEST_TYPE_REGRESSION:
                // Regression tests: Comprehensive
                caps.setCapability(MobileCapabilityType.PRINT_PAGE_SOURCE_ON_FIND_FAILURE, true);
                caps.setCapability("appium:enablePerformanceLogging", true);
                break;

            case TEST_TYPE_PERFORMANCE:
                // Performance tests: Detailed metrics
                caps.setCapability("appium:enablePerformanceLogging", true);
                caps.setCapability("appium:disableWindowAnimation", false); // Keep animations for realistic timing
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 600);
                break;

            case TEST_TYPE_ACCESSIBILITY:
                // Accessibility tests: Focus on accessibility features
                caps.setCapability("appium:accessibilityChecks", true);
                caps.setCapability("appium:nativeWebScreenshot", true);
                break;
        }
    }

    /**
     * Builder pattern for fluent capability configuration
     */
    public static class CapabilityBuilder {
        private final DesiredCapabilities caps = new DesiredCapabilities();
        private String platform;

        public CapabilityBuilder forPlatform(String platform) {
            this.platform = platform.toUpperCase();
            if (PLATFORM_ANDROID.equals(this.platform)) {
                caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "Android");
                caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "UiAutomator2");
            } else if (PLATFORM_IOS.equals(this.platform)) {
                caps.setCapability(MobileCapabilityType.PLATFORM_NAME, "iOS");
                caps.setCapability(MobileCapabilityType.AUTOMATION_NAME, "XCUITest");
            }
            return this;
        }

        public CapabilityBuilder withApp(String appPath) {
            if (appPath != null && new File(appPath).exists()) {
                caps.setCapability(MobileCapabilityType.APP, new File(appPath).getAbsolutePath());
            }
            return this;
        }

        public CapabilityBuilder withDevice(String deviceName) {
            caps.setCapability(MobileCapabilityType.DEVICE_NAME, deviceName);
            return this;
        }

        public CapabilityBuilder withUdid(String udid) {
            caps.setCapability(MobileCapabilityType.UDID, udid);
            return this;
        }

        public CapabilityBuilder withAvd(String avdName) {
            if (PLATFORM_ANDROID.equals(platform)) {
                caps.setCapability(AndroidMobileCapabilityType.AVD, avdName);
            }
            return this;
        }

        public CapabilityBuilder withResetBehavior(boolean noReset, boolean fullReset) {
            caps.setCapability(MobileCapabilityType.NO_RESET, noReset);
            caps.setCapability(MobileCapabilityType.FULL_RESET, fullReset);
            return this;
        }

        public CapabilityBuilder withTimeout(int seconds) {
            caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, seconds);
            return this;
        }

        public CapabilityBuilder withParallelPort(int port) {
            if (PLATFORM_ANDROID.equals(platform)) {
                caps.setCapability(AndroidMobileCapabilityType.SYSTEM_PORT, port);
            } else if (PLATFORM_IOS.equals(platform)) {
                caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, port);
            }
            return this;
        }

        public CapabilityBuilder withCustomCapability(String key, Object value) {
            caps.setCapability(key, value);
            return this;
        }

        public DesiredCapabilities build() {
            // Apply defaults if not set
            if (!caps.asMap().containsKey(MobileCapabilityType.NEW_COMMAND_TIMEOUT)) {
                caps.setCapability(MobileCapabilityType.NEW_COMMAND_TIMEOUT, 300);
            }

            // Platform-specific defaults
            if (PLATFORM_ANDROID.equals(platform)) {
                if (!caps.asMap().containsKey(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS)) {
                    caps.setCapability(AndroidMobileCapabilityType.AUTO_GRANT_PERMISSIONS, true);
                }
            } else if (PLATFORM_IOS.equals(platform)) {
                if (!caps.asMap().containsKey(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS)) {
                    caps.setCapability(IOSMobileCapabilityType.AUTO_ACCEPT_ALERTS, true);
                }
            }

            validateCapabilities(caps);
            return caps;
        }
    }

    /**
     * Get capabilities for parallel execution across multiple devices
     */
    public static Map<String, DesiredCapabilities> getParallelCapabilities(
            String platform, 
            int deviceCount,
            String environment) {

        Map<String, DesiredCapabilities> allCaps = new HashMap<>();

        if (PLATFORM_ANDROID.equalsIgnoreCase(platform)) {
            // For Android: Use different system ports
            String[] avds = getAvailableAvds();

            for (int i = 0; i < Math.min(deviceCount, avds.length); i++) {
                DesiredCapabilities caps = getCapabilities(platform, environment, TEST_TYPE_REGRESSION, null);
                caps.setCapability(AndroidMobileCapabilityType.AVD, avds[i]);
                caps.setCapability(MobileCapabilityType.DEVICE_NAME, avds[i]);
                caps.setCapability(AndroidMobileCapabilityType.SYSTEM_PORT, 8200 + i);

                allCaps.put("Android_Device_" + (i + 1), caps);
            }

        } else if (PLATFORM_IOS.equalsIgnoreCase(platform)) {
            // For iOS: Use different WDA ports
            String[] simulators = getAvailableSimulators();

            for (int i = 0; i < Math.min(deviceCount, simulators.length); i++) {
                DesiredCapabilities caps = getCapabilities(platform, environment, TEST_TYPE_REGRESSION, null);
                caps.setCapability(MobileCapabilityType.DEVICE_NAME, simulators[i]);
                caps.setCapability(IOSMobileCapabilityType.WDA_LOCAL_PORT, 8100 + i);

                allCaps.put("iOS_Device_" + (i + 1), caps);
            }
        }

        return allCaps;
    }

    // Helper methods (implementations would read from configuration)
    private static Properties loadConfiguration() {
        // Load from properties file, environment variables, etc.
        Properties props = new Properties();
        // Implementation would read from config files
        return props;
    }

    private static void validateInputs(String platform, String environment, String testType) {
        if (!PLATFORM_ANDROID.equalsIgnoreCase(platform) && 
            !PLATFORM_IOS.equalsIgnoreCase(platform)) {
            throw new IllegalArgumentException("Unsupported platform: " + platform);
        }

        // Additional validation logic here
    }

    private static void applyOverrides(DesiredCapabilities caps, Map<String, Object> overrides) {
        for (Map.Entry<String, Object> entry : overrides.entrySet()) {
            caps.setCapability(entry.getKey(), entry.getValue());
        }
    }

    private static void validateCapabilities(DesiredCapabilities caps) {
        // Check required capabilities
        if (!caps.asMap().containsKey(MobileCapabilityType.PLATFORM_NAME)) {
            throw new IllegalStateException("Missing required capability: platformName");
        }

        if (!caps.asMap().containsKey(MobileCapabilityType.AUTOMATION_NAME)) {
            throw new IllegalStateException("Missing required capability: automationName");
        }

        // Platform-specific validation
        String platform = (String) caps.getCapability(MobileCapabilityType.PLATFORM_NAME);

        if ("Android".equalsIgnoreCase(platform)) {
            // Android specific validation
            if (!caps.asMap().containsKey(MobileCapabilityType.DEVICE_NAME) &&
                !caps.asMap().containsKey(MobileCapabilityType.UDID)) {
                throw new IllegalStateException("Android requires either deviceName or udid");
            }

        } else if ("iOS".equalsIgnoreCase(platform)) {
            // iOS specific validation
            if (!caps.asMap().containsKey(MobileCapabilityType.DEVICE_NAME) &&
                !caps.asMap().containsKey(MobileCapabilityType.UDID)) {
                throw new IllegalStateException("iOS requires either deviceName or udid");
            }
        }
    }

    private static String getAppPathForEnvironment(String platform, String environment) {
