import io.appium.java_client.AppiumDriver;
import io.appium.java_client.android.AndroidDriver;
import io.appium.java_client.ios.IOSDriver;
import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.remote.DesiredCapabilities;
import org.testng.annotations.AfterClass;
import org.testng.annotations.BeforeClass;
import org.testng.annotations.Test;

import java.net.URL;
import java.time.Duration;

public class FirstAppiumTest {

    private AppiumDriver driver;

    @BeforeClass
    public void setUp() throws Exception {
        // Configure desired capabilities
        DesiredCapabilities caps = new DesiredCapabilities();

        // Common capabilities for both platforms
        caps.setCapability("platformName", "Android"); // or "iOS"
        caps.setCapability("deviceName", "Pixel_6_Pro_API_33");
        caps.setCapability("automationName", "UiAutomator2"); // "XCUITest" for iOS

        // Application under test
        caps.setCapability("appPackage", "com.android.calculator2");
        caps.setCapability("appActivity", "com.android.calculator2.Calculator");

        // Optional: App path if not pre-installed
        // caps.setCapability("app", "/path/to/app.apk");

        // Optional: Reset behavior
        caps.setCapability("noReset", true);
        caps.setCapability("fullReset", false);

        // Initialize driver
        URL appiumServerUrl = new URL("http://127.0.0.1:4723");

        // Platform-specific driver initialization
        String platform = caps.getCapability("platformName").toString();
        if (platform.equalsIgnoreCase("Android")) {
            driver = new AndroidDriver(appiumServerUrl, caps);
        } else if (platform.equalsIgnoreCase("iOS")) {
            driver = new IOSDriver(appiumServerUrl, caps);
        }

        // Configure implicit wait
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(10));
    }

    @Test
    public void testBasicCalculatorOperations() {
        // Test addition: 5 + 3 = 8

        // Locate number buttons
        WebElement digit5 = driver.findElement(By.id("com.android.calculator2:id/digit_5"));
        WebElement digit3 = driver.findElement(By.id("com.android.calculator2:id/digit_3"));
        WebElement plusBtn = driver.findElement(By.id("com.android.calculator2:id/op_add"));
        WebElement equalsBtn = driver.findElement(By.id("com.android.calculator2:id/eq"));
        WebElement resultField = driver.findElement(By.id("com.android.calculator2:id/result"));

        // Perform calculation
        digit5.click();
        plusBtn.click();
        digit3.click();
        equalsBtn.click();

        // Verify result
        String result = resultField.getText();
        assert result.equals("8") : "Expected 8 but got " + result;

        System.out.println("Test passed: 5 + 3 = " + result);
    }

    @Test
    public void testClearFunctionality() {
        // Test clear button functionality
        WebElement clearBtn = driver.findElement(By.id("com.android.calculator2:id/clr"));
        WebElement resultField = driver.findElement(By.id("com.android.calculator2:id/result"));

        // Enter some numbers
        driver.findElement(By.id("com.android.calculator2:id/digit_9")).click();
        driver.findElement(By.id("com.android.calculator2:id/digit_9")).click();

        // Clear the display
        clearBtn.click();

        // Verify display is cleared
        String result = resultField.getText();
        assert result.isEmpty() || result.equals("0") : "Display not cleared properly";

        System.out.println("Test passed: Clear functionality works");
    }

    @AfterClass
    public void tearDown() {
        if (driver != null) {
            // Take screenshot before closing (optional)
            // File screenshot = ((TakesScreenshot)driver).getScreenshotAs(OutputType.FILE);

            // Quit driver and close session
            driver.quit();
            System.out.println("Test completed and driver closed");
        }
    }
}

package com.mobileautomation.waits;

import io.appium.java_client.AppiumDriver;
import org.openqa.selenium.*;
import org.openqa.selenium.support.ui.*;
import java.time.Duration;
import java.util.List;
import java.util.function.Function;

public class AdvancedWaitStrategies {

    private final AppiumDriver driver;
    private WebDriverWait defaultWait;

    public AdvancedWaitStrategies(AppiumDriver driver) {
        this.driver = driver;
        // Configure default explicit wait
        this.defaultWait = new WebDriverWait(driver, Duration.ofSeconds(15));

        // Configure implicit wait (global timeout for element finding)
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(5));
    }

    /**
     * Wait for element to be visible and clickable
     */
    public WebElement waitForElementClickable(By locator) {
        return defaultWait.until(
            ExpectedConditions.elementToBeClickable(locator)
        );
    }

    /**
     * Wait for element to be visible
     */
    public WebElement waitForElementVisible(By locator) {
        return defaultWait.until(
            ExpectedConditions.visibilityOfElementLocated(locator)
        );
    }

    /**
     * Wait for element to disappear
     */
    public boolean waitForElementInvisible(By locator) {
        return defaultWait.until(
            ExpectedConditions.invisibilityOfElementLocated(locator)
        );
    }

    /**
     * Wait for element to contain specific text
     */
    public WebElement waitForElementWithText(By locator, String expectedText) {
        return defaultWait.until(
            ExpectedConditions.textToBe(locator, expectedText)
        );
    }

    /**
     * Wait for element to contain partial text
     */
    public WebElement waitForElementWithPartialText(By locator, String partialText) {
        return defaultWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                String actualText = element.getText();
                return actualText.contains(partialText) ? element : null;
            }
        );
    }

    /**
     * Wait for element attribute to have specific value
     */
    public WebElement waitForElementAttribute(By locator, String attribute, String expectedValue) {
        return defaultWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                String actualValue = element.getAttribute(attribute);
                return expectedValue.equals(actualValue) ? element : null;
            }
        );
    }

    /**
     * Wait for alert to be present
     */
    public Alert waitForAlert() {
        return defaultWait.until(
            ExpectedConditions.alertIsPresent()
        );
    }

    /**
     * Wait for activity to change (Android specific)
     */
    public void waitForActivity(String expectedActivity, int timeoutSeconds) {
        WebDriverWait activityWait = new WebDriverWait(driver, Duration.ofSeconds(timeoutSeconds));
        activityWait.until(
            driver -> {
                if (driver instanceof AndroidDriver) {
                    String currentActivity = ((AndroidDriver) driver).currentActivity();
                    return currentActivity.contains(expectedActivity);
                }
                return false;
            }
        );
    }

    /**
     * Wait for network idle (custom condition)
     */
    public void waitForNetworkIdle(int maxWaitSeconds) {
        WebDriverWait networkWait = new WebDriverWait(driver, Duration.ofSeconds(maxWaitSeconds));
        networkWait.until(
            driver -> {
                // Check for loading indicators
                List<WebElement> loadingIndicators = driver.findElements(
                    By.xpath("//*[contains(@text, 'Loading') or contains(@text, 'Please wait')]")
                );

                // Check for progress bars
                List<WebElement> progressBars = driver.findElements(
                    By.className("android.widget.ProgressBar")
                );

                // Network is idle if no loading indicators or progress bars are visible
                return loadingIndicators.isEmpty() && progressBars.isEmpty();
            }
        );
    }

    /**
     * Fluent wait with custom polling interval
     */
    public WebElement fluentWaitForElement(By locator, int timeoutSeconds, int pollingIntervalMillis) {
        Wait<WebDriver> fluentWait = new FluentWait<>(driver)
            .withTimeout(Duration.ofSeconds(timeoutSeconds))
            .pollingEvery(Duration.ofMillis(pollingIntervalMillis))
            .ignoring(NoSuchElementException.class)
            .ignoring(StaleElementReferenceException.class);

        return fluentWait.until(
            driver -> {
                WebElement element = driver.findElement(locator);
                return element.isDisplayed() && element.isEnabled() ? element : null;
            }
        );
    }

    /**
     * Wait with retry mechanism
     */
    public WebElement waitWithRetry(By locator, int maxRetries) {
        WebElement element = null;
        Exception lastException = null;

        for (int attempt = 0; attempt < maxRetries; attempt++) {
            try {
                element = waitForElementVisible(locator);
                break;
            } catch (TimeoutException e) {
                lastException = e;
                System.out.printf("Attempt %d failed, retrying...\n", attempt + 1);

                // Optional: Add small delay between retries
                try {
                    Thread.sleep(500);
                } catch (InterruptedException ie) {
                    Thread.currentThread().interrupt();
                }
            }
        }

        if (element == null && lastException != null) {
            throw new RuntimeException("Element not found after " + maxRetries + " attempts", lastException);
        }

        return element;
    }

    /**
     * Custom wait for list to have minimum items
     */
    public List<WebElement> waitForMinimumListItems(By listLocator, int minItems) {
        return defaultWait.until(
            driver -> {
                List<WebElement> items = driver.findElements(listLocator);
                return items.size() >= minItems ? items : null;
            }
        );
    }

    /**
     * Smart wait that adapts based on platform
     */
    public WebElement smartWaitForElement(By locator) {
        String platform = driver.getCapabilities().getCapability("platformName").toString();

        if (platform.equalsIgnoreCase("Android")) {
            // Android specific wait conditions
            return waitForElementVisible(locator);
        } else if (platform.equalsIgnoreCase("iOS")) {
            // iOS may need longer waits for animations
            WebDriverWait iosWait = new WebDriverWait(driver, Duration.ofSeconds(20));
            return iosWait.until(
                ExpectedConditions.visibilityOfElementLocated(locator)
            );
        } else {
            return waitForElementVisible(locator);
        }
    }

    /**
     * Utility method to reset implicit wait
     */
    public void resetImplicitWait(int seconds) {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(seconds));
    }

    /**
     * Disable implicit wait (useful for checking element absence)
     */
    public void disableImplicitWait() {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(0));
    }

    /**
     * Restore default implicit wait
     */
    public void restoreImplicitWait() {
        driver.manage().timeouts().implicitlyWait(Duration.ofSeconds(5));
    }
}

from appium.webdriver.common.appiumby import AppiumBy
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.common.exceptions import TimeoutException, NoSuchElementException
from selenium.webdriver.common.by import By
import time

class SmartWaits:
    """Comprehensive waiting strategies for Appium tests"""

    def __init__(self, driver, default_timeout=15):
        self.driver = driver
        self.default_timeout = default_timeout
        self.default_wait = WebDriverWait(driver, default_timeout)

        # Set implicit wait
        driver.implicitly_wait(5)

    def wait_for_element(self, locator, timeout=None):
        """Wait for element to be present"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.presence_of_element_located(locator))

    def wait_for_visible(self, locator, timeout=None):
        """Wait for element to be visible"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.visibility_of_element_located(locator))

    def wait_for_clickable(self, locator, timeout=None):
        """Wait for element to be clickable"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.element_to_be_clickable(locator))

    def wait_for_invisible(self, locator, timeout=None):
        """Wait for element to disappear"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.invisibility_of_element_located(locator))

    def wait_for_text(self, locator, expected_text, timeout=None):
        """Wait for element to contain specific text"""
        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.text_to_be_present_in_element(locator, expected_text))

    def wait_for_attribute(self, locator, attribute, expected_value, timeout=None):
        """Wait for element attribute to have specific value"""
        def attribute_condition(driver):
            try:
                element = driver.find_element(*locator)
                actual_value = element.get_attribute(attribute)
                return actual_value == expected_value
            except:
                return False

        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(attribute_condition)

    def wait_for_activity(self, expected_activity, timeout=30):
        """Wait for specific activity (Android only)"""
        wait = WebDriverWait(self.driver, timeout)
        return wait.until(
            lambda driver: expected_activity in driver.current_activity
        )

    def wait_for_list_items(self, list_locator, min_items=1, timeout=None):
        """Wait for list to have minimum number of items"""
        def list_condition(driver):
            items = driver.find_elements(*list_locator)
            return len(items) >= min_items

        wait = self.default_wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(list_condition)

    def wait_with_retry(self, locator, max_retries=3, delay=1):
        """Wait for element with retry mechanism"""
        for attempt in range(max_retries):
            try:
                return self.wait_for_visible(locator, timeout=5)
            except TimeoutException:
                if attempt < max_retries - 1:
                    print(f"Attempt {attempt + 1} failed, retrying in {delay} seconds...")
                    time.sleep(delay)
                else:
                    raise

    def is_element_present(self, locator, timeout=5):
        """Check if element is present without throwing exception"""
        try:
            self.wait_for_element(locator, timeout)
            return True
        except TimeoutException:
            return False

    def wait_for_network_idle(self, timeout=30, check_interval=1):
        """Wait for network activity to complete"""
        end_time = time.time() + timeout

        while time.time() < end_time:
            # Check for loading indicators
            loading_indicators = self.driver.find_elements(
                AppiumBy.ANDROID_UIAUTOMATOR,
                'new UiSelector().textContains("Loading")'
            )

            progress_bars = self.driver.find_elements(
                AppiumBy.CLASS_NAME, 'android.widget.ProgressBar'
            )

            if not loading_indicators and not progress_bars:
                return True

            time.sleep(check_interval)

        raise TimeoutException(f"Network not idle after {timeout} seconds")

    def disable_implicit_wait(self):
        """Temporarily disable implicit wait"""
        self.driver.implicitly_wait(0)

    def restore_implicit_wait(self):
        """Restore implicit wait to default"""
        self.driver.implicitly_wait(5)

# Usage example
def test_with_smart_waits(driver):
    waits = SmartWaits(driver)

    # Wait for login button to be clickable
    login_button = waits.wait_for_clickable(
        (AppiumBy.ACCESSIBILITY_ID, 'login_button')
    )
    login_button.click()

    # Wait for login form to appear
    waits.wait_for_visible(
        (AppiumBy.ID, 'com.app:id/login_form')
    )

    # Wait for specific text to appear
    waits.wait_for_text(
        (AppiumBy.ID, 'com.app:id/welcome_message'),
        'Welcome back'
    )

    # Check if element is present without failing test
    if waits.is_element_present((AppiumBy.ID, 'error_message'), timeout=2):
        print("Error message detected")

    # Wait with retry for flaky elements
    profile_image = waits.wait_with_retry(
        (AppiumBy.ID, 'profile_image'),
        max_retries=3
    )

