import org.openqa.selenium.By;
import org.openqa.selenium.WebElement;
import org.openqa.selenium.support.ui.ExpectedConditions;
import org.openqa.selenium.support.ui.WebDriverWait;
import java.time.Duration;
import java.util.List;

public class SmartElementFinder {

    public WebElement findElementWithFallback(String elementId, String elementText) {
        // Priority 1: Accessibility ID (cross-platform)
        try {
            return new WebDriverWait(driver, Duration.ofSeconds(3))
                .until(ExpectedConditions.presenceOfElementLocated(
                    AppiumBy.accessibilityId(elementId)
                ));
        } catch (Exception e) {
            // Priority 2: Platform-specific strategies
            if (isAndroid()) {
                return findAndroidElement(elementId, elementText);
            } else {
                return findIOSElement(elementId, elementText);
            }
        }
    }

    private WebElement findAndroidElement(String elementId, String elementText) {
        List<By> androidLocators = List.of(
            AppiumBy.id("com.app:id/" + elementId),
            AppiumBy.androidUIAutomator(
                "new UiSelector().text(\"" + elementText + "\")"
            ),
            AppiumBy.androidUIAutomator(
                "new UiSelector().description(\"" + elementText + "\")"
            ),
            By.xpath("//*[@text='" + elementText + "']"),
            By.xpath("//*[contains(@text, '" + elementText + "')]"),
            By.xpath("//*[@content-desc='" + elementText + "']")
        );

        return findWithCascadingStrategy(androidLocators);
    }

    private WebElement findIOSElement(String elementId, String elementText) {
        List<By> iosLocators = List.of(
            AppiumBy.name(elementId),
            AppiumBy.iOSNsPredicateString(
                "label == '" + elementText + "'"
            ),
            AppiumBy.iOSNsPredicateString(
                "label CONTAINS '" + elementText + "'"
            ),
            AppiumBy.iOSClassChain(
                "**/*[`label == '" + elementText + "'`]"
            ),
            By.xpath("//*[@label='" + elementText + "']")
        );

        return findWithCascadingStrategy(iosLocators);
    }

    private WebElement findWithCascadingStrategy(List<By> locators) {
        for (By locator : locators) {
            try {
                return new WebDriverWait(driver, Duration.ofSeconds(2))
                    .until(ExpectedConditions.presenceOfElementLocated(locator));
            } catch (Exception e) {
                continue; // Try next locator
            }
        }
        throw new RuntimeException("Element not found with any locator strategy");
    }

    private boolean isAndroid() {
        return driver.getCapabilities().getCapability("platformName")
            .equals("Android");
    }
}

import org.openqa.selenium.interactions.Actions;
import org.openqa.selenium.interactions.PointerInput;
import org.openqa.selenium.interactions.Sequence;
import java.time.Duration;
import java.util.Collections;

public class ModernGestureController {

    // Using W3C Actions API (recommended for new code)
    public void performSwipe(int startX, int startY, int endX, int endY) {
        PointerInput finger = new PointerInput(PointerInput.Kind.TOUCH, "finger");
        Sequence swipe = new Sequence(finger, 0)
            .addAction(finger.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), startX, startY))
            .addAction(finger.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger, Duration.ofMillis(100)))
            .addAction(finger.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), endX, endY))
            .addAction(finger.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        driver.perform(Collections.singletonList(swipe));
    }

    // Pinch-to-zoom with multi-touch
    public void pinchZoom(WebElement element, boolean zoomIn) {
        // Calculate element center
        Point center = getCenter(element);
        int offset = zoomIn ? 50 : 100;

        // First finger sequence
        PointerInput finger1 = new PointerInput(PointerInput.Kind.TOUCH, "finger1");
        Sequence seq1 = new Sequence(finger1, 0)
            .addAction(finger1.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), center.x - offset, center.y - offset))
            .addAction(finger1.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger1, Duration.ofMillis(100)))
            .addAction(finger1.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), 
                zoomIn ? center.x - offset * 2 : center.x - offset / 2, 
                zoomIn ? center.y - offset * 2 : center.y - offset / 2))
            .addAction(finger1.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        // Second finger sequence
        PointerInput finger2 = new PointerInput(PointerInput.Kind.TOUCH, "finger2");
        Sequence seq2 = new Sequence(finger2, 1)
            .addAction(finger2.createPointerMove(Duration.ZERO, 
                PointerInput.Origin.viewport(), center.x + offset, center.y + offset))
            .addAction(finger2.createPointerDown(PointerInput.MouseButton.LEFT.asArg()))
            .addAction(new Pause(finger2, Duration.ofMillis(100)))
            .addAction(finger2.createPointerMove(Duration.ofMillis(500), 
                PointerInput.Origin.viewport(), 
                zoomIn ? center.x + offset * 2 : center.x + offset / 2, 
                zoomIn ? center.y + offset * 2 : center.y + offset / 2))
            .addAction(finger2.createPointerUp(PointerInput.MouseButton.LEFT.asArg()));

        // Execute both sequences simultaneously
        driver.perform(Arrays.asList(seq1, seq2));
    }

    // Scroll to element utility
    public void scrollToElement(String elementText) {
        // Android UIAutomator scroll
        if (isAndroid()) {
            driver.findElement(AppiumBy.androidUIAutomator(
                "new UiScrollable(new UiSelector().scrollable(true))" +
                ".scrollIntoView(new UiSelector().text(\"" + elementText + "\"))"
            ));
        } else {
            // iOS scroll using JavaScript
            JavascriptExecutor js = (JavascriptExecutor) driver;
            HashMap<String, String> scrollObject = new HashMap<>();
            scrollObject.put("direction", "down");
            scrollObject.put("predicateString", "label == '" + elementText + "'");
            js.executeScript("mobile: scroll", scrollObject);
        }
    }
}

package com.mobileautomation.pages;

import io.appium.java_client.AppiumDriver;
import io.appium.java_client.android.AndroidDriver;
