// Layer 5: Driver & Configuration
public abstract class BasePage {
    protected AppiumDriver driver;
    protected WebDriverWait wait;
    protected String platform;

    public BasePage(AppiumDriver driver) {
        this.driver = driver;
        this.wait = new WebDriverWait(driver, Duration.ofSeconds(15));
        this.platform = driver.getCapabilities().getCapability("platformName").toString();
        PageFactory.initElements(new AppiumFieldDecorator(driver), this);
    }

    // Common utility methods
    protected boolean isAndroid() {
        return platform.equalsIgnoreCase("Android");
    }

    protected boolean isIOS() {
        return platform.equalsIgnoreCase("iOS");
    }

    protected void waitForVisibility(WebElement element) {
        wait.until(ExpectedConditions.visibilityOf(element));
    }

    protected void waitForClickable(WebElement element) {
        wait.until(ExpectedConditions.elementToBeClickable(element));
    }

    protected void tap(WebElement element) {
        waitForClickable(element);
        element.click();
    }

    protected void enterText(WebElement element, String text) {
        waitForVisibility(element);
        element.clear();
        element.sendKeys(text);
    }

    protected String getText(WebElement element) {
        waitForVisibility(element);
        return element.getText();
    }

    protected boolean isDisplayed(WebElement element) {
        try {
            return element.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    // Platform-specific element location
    protected By getPlatformSpecificLocator(String androidId, String iosAccessibilityId) {
        if (isAndroid()) {
            return By.id(androidId);
        } else {
            return By.xpath("//*[@name='" + iosAccessibilityId + "' or @label='" + iosAccessibilityId + "' or @value='" + iosAccessibilityId + "']");
        }
    }
}

// Layer 4: Component Objects
class MobileComponent extends BasePage {

    public MobileComponent(AppiumDriver driver) {
        super(driver);
    }

    // Navigation Bar Component
    public static class NavigationBar {
        private AppiumDriver driver;
        private By backButton;
        private By title;
        private By menuButton;

        public NavigationBar(AppiumDriver driver) {
            this.driver = driver;
            // Platform-specific locators
            if (driver instanceof AndroidDriver) {
                backButton = By.id("com.app:id/back_button");
                title = By.id("com.app:id/toolbar_title");
                menuButton = By.id("com.app:id/menu_button");
            } else {
                backButton = By.xpath("//XCUIElementTypeButton[@name='Back']");
                title = By.xpath("//XCUIElementTypeStaticText[@name='Screen Title']");
                menuButton = By.xpath("//XCUIElementTypeButton[@name='Menu']");
            }
        }

        public void goBack() {
            driver.findElement(backButton).click();
        }

        public String getTitle() {
            return driver.findElement(title).getText();
        }

        public void openMenu() {
            driver.findElement(menuButton).click();
        }
    }

    // Button Component
    public static class Button {
        private WebElement element;
        private AppiumDriver driver;

        public Button(AppiumDriver driver, WebElement element) {
            this.driver = driver;
            this.element = element;
        }

        public void tap() {
            element.click();
        }

        public boolean isEnabled() {
            return element.isEnabled();
        }

        public String getText() {
            return element.getText();
        }
    }

    // Text Input Component
    public static class TextInput {
        private WebElement element;
        private AppiumDriver driver;

        public TextInput(AppiumDriver driver, WebElement element) {
            this.driver = driver;
            this.element = element;
        }

        public void enter(String text) {
            element.clear();
            element.sendKeys(text);
        }

        public String getValue() {
            return element.getText();
        }

        public void clear() {
            element.clear();
        }
    }
}

// Layer 3: Page Objects
public class LoginPage extends BasePage {

    // Locators with platform abstraction
    private Map<String, By> emailField = new HashMap<>() {{
        put("Android", By.id("com.app:id/email_field"));
        put("iOS", By.xpath("//XCUIElementTypeTextField[@name='email']"));
    }};

    private Map<String, By> passwordField = new HashMap<>() {{
        put("Android", By.id("com.app:id/password_field"));
        put("iOS", By.xpath("//XCUIElementTypeSecureTextField[@name='password']"));
    }};

    private Map<String, By> loginButton = new HashMap<>() {{
        put("Android", By.id("com.app:id/login_button"));
        put("iOS", By.xpath("//XCUIElementTypeButton[@name='Login']"));
    }};

    private Map<String, By> forgotPasswordLink = new HashMap<>() {{
        put("Android", By.id("com.app:id/forgot_password"));
        put("iOS", By.xpath("//XCUIElementTypeButton[@name='Forgot Password?']"));
    }};

    private Map<String, By> errorMessage = new HashMap<>() {{
        put("Android", By.id("com.app:id/error_message"));
        put("iOS", By.xpath("//XCUIElementTypeStaticText[@name='error_message']"));
    }};

    public LoginPage(AppiumDriver driver) {
        super(driver);
    }

    // Business methods
    public void enterEmail(String email) {
        By locator = emailField.get(platform);
        WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        element.clear();
        element.sendKeys(email);
    }

    public void enterPassword(String password) {
        By locator = passwordField.get(platform);
        WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        element.clear();
        element.sendKeys(password);
    }

    public void tapLogin() {
        By locator = loginButton.get(platform);
        WebElement element = wait.until(ExpectedConditions.elementToBeClickable(locator));
        element.click();
    }

    public void login(String email, String password) {
        enterEmail(email);
        enterPassword(password);
        tapLogin();
    }

    public boolean isErrorMessageDisplayed() {
        try {
            By locator = errorMessage.get(platform);
            WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
            return element.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }

    public String getErrorMessage() {
        By locator = errorMessage.get(platform);
        WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        return element.getText();
    }

    public void tapForgotPassword() {
        By locator = forgotPasswordLink.get(platform);
        WebElement element = wait.until(ExpectedConditions.elementToBeClickable(locator));
        element.click();
    }

    public boolean isLoginButtonEnabled() {
        By locator = loginButton.get(platform);
        WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        return element.isEnabled();
    }
}

public class HomePage extends BasePage {

    // Using PageFactory annotations for element initialization
    @FindBy(id = "com.app:id/welcome_message")
    @iOSXCUITFindBy(iOSNsPredicate = "name == 'Welcome Message'")
    private WebElement welcomeMessage;

    @FindBy(id = "com.app:id/profile_button")
    @iOSXCUITFindBy(iOSNsPredicate = "name == 'Profile'")
    private WebElement profileButton;

    @FindBy(id = "com.app:id/search_field")
    @iOSXCUITFindBy(iOSNsPredicate = "name == 'Search'")
    private WebElement searchField;

    @FindBy(id = "com.app:id/logout_button")
    @iOSXCUITFindBy(accessibility = "Logout")
    private WebElement logoutButton;

    // List items - example of handling dynamic content
    private By listItems = getPlatformSpecificLocator(
        "com.app:id/list_item",
        "//XCUIElementTypeCell"
    );

    public HomePage(AppiumDriver driver) {
        super(driver);
        PageFactory.initElements(new AppiumFieldDecorator(driver), this);
    }

    public String getWelcomeMessage() {
        waitForVisibility(welcomeMessage);
        return welcomeMessage.getText();
    }

    public void navigateToProfile() {
        waitForClickable(profileButton);
        profileButton.click();
    }

    public void search(String query) {
        waitForVisibility(searchField);
        searchField.clear();
        searchField.sendKeys(query);

        // Hide keyboard if needed
        if (isAndroid()) {
            driver.hideKeyboard();
        } else {
            searchField.sendKeys(Keys.RETURN);
        }
    }

    public void logout() {
        waitForClickable(logoutButton);
        logoutButton.click();

        // Handle confirmation dialog
        if (isAndroid()) {
            driver.findElement(By.id("android:id/button1")).click(); // OK button
        } else {
            driver.findElement(By.xpath("//XCUIElementTypeButton[@name='OK']")).click();
        }
    }

    public int getListItemCount() {
        return driver.findElements(listItems).size();
    }

    public void tapListItem(int index) {
        List<WebElement> items = driver.findElements(listItems);
        if (index < items.size()) {
            items.get(index).click();
        }
    }

    public boolean isUserLoggedIn() {
        try {
            return welcomeMessage.isDisplayed();
        } catch (Exception e) {
            return false;
        }
    }
}

// Layer 2: Page Factory with enhanced platform support
class PageFactoryManager {
    private static Map<Class<?>, Object> pageCache = new HashMap<>();

    @SuppressWarnings("unchecked")
    public static <T> T getPage(AppiumDriver driver, Class<T> pageClass) {
        if (!pageCache.containsKey(pageClass)) {
            try {
                T page = pageClass.getConstructor(AppiumDriver.class).newInstance(driver);
                pageCache.put(pageClass, page);
            } catch (Exception e) {
                throw new RuntimeException("Failed to create page instance: " + pageClass.getName(), e);
            }
        }
        return (T) pageCache.get(pageClass);
    }

    public static void clearCache() {
        pageCache.clear();
    }
}

// Layer 1: Test Scripts
class LoginTests {
    private AppiumDriver driver;
    private LoginPage loginPage;
    private HomePage homePage;

    @BeforeMethod
    public void setup() {
        // Initialize driver (implementation omitted for brevity)
        // driver = new AndroidDriver(...) or new IOSDriver(...);

        // Initialize pages using PageFactoryManager
        loginPage = PageFactoryManager.getPage(driver, LoginPage.class);
        homePage = PageFactoryManager.getPage(driver, HomePage.class);
    }

    @Test
    public void testSuccessfulLogin() {
        // Business logic - no direct element interaction
        loginPage.login("test@example.com", "password123");

        // Verification
        Assert.assertTrue(homePage.isUserLoggedIn(), "User should be logged in");
        Assert.assertEquals(homePage.getWelcomeMessage(), "Welcome, Test User!");
    }

    @Test
    public void testInvalidLogin() {
        loginPage.login("wrong@example.com", "wrongpass");

        // Verification
        Assert.assertTrue(loginPage.isErrorMessageDisplayed(), "Error message should be displayed");
        Assert.assertEquals(loginPage.getErrorMessage(), "Invalid credentials");
    }

    @Test
    public void testLoginButtonState() {
        // Test empty fields
        Assert.assertFalse(loginPage.isLoginButtonEnabled(), "Login button should be disabled with empty fields");

        // Test with email only
        loginPage.enterEmail("test@example.com");
        Assert.assertFalse(loginPage.isLoginButtonEnabled(), "Login button should be disabled without password");

        // Test with both fields
        loginPage.enterPassword("password123");
        Assert.assertTrue(loginPage.isLoginButtonEnabled(), "Login button should be enabled with both fields");
    }

    @AfterMethod
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
        PageFactoryManager.clearCache();
    }
}

"""
Complete Page Object Model Implementation in Python
"""

from abc import ABC, abstractmethod
from typing import Dict, List, Optional
from appium.webdriver.common.appiumby import AppiumBy
from appium.webdriver.webdriver import WebDriver
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.remote.webelement import WebElement
from selenium.common.exceptions import TimeoutException, NoSuchElementException
import time

# Layer 5: Base Page & Utilities
class BasePage(ABC):
    """Base class for all page objects"""

    def __init__(self, driver: WebDriver, timeout: int = 15):
        self.driver = driver
        self.timeout = timeout
        self.wait = WebDriverWait(driver, timeout)
        self.platform = driver.capabilities.get('platformName', '').lower()

    @property
    def is_android(self) -> bool:
        return self.platform == 'android'

    @property
    def is_ios(self) -> bool:
        return self.platform == 'ios'

    def get_platform_locator(self, android_locator: tuple, ios_locator: tuple) -> tuple:
        """Get platform-specific locator"""
        return android_locator if self.is_android else ios_locator

    def wait_for_element(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be present"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.presence_of_element_located(locator))

    def wait_for_visible(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be visible"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.visibility_of_element_located(locator))

    def wait_for_clickable(self, locator: tuple, timeout: Optional[int] = None) -> WebElement:
        """Wait for element to be clickable"""
        wait = self.wait if timeout is None else WebDriverWait(self.driver, timeout)
        return wait.until(EC.element_to_be_clickable(locator))

    def tap(self, element: WebElement):
        """Tap on element"""
        element.click()

    def enter_text(self, element: WebElement, text: str):
        """Enter text into element"""
        element.clear()
        element.send_keys(text)

    def get_text(self, element: WebElement) -> str:
        """Get text from element"""
        return element.text

    def is_displayed(self, element: WebElement) -> bool:
        """Check if element is displayed"""
        try:
            return element.is_displayed()
        except:
            return False

# Layer 4: Component Objects
class MobileComponents:
    """Reusable mobile UI components"""

    @staticmethod
    class NavigationBar:
        def __init__(self, driver: WebDriver):
            self.driver = driver
            self.platform = driver.capabilities.get('platformName', '').lower()

            # Platform-specific locators
            if self.platform == 'android':
                self.back_button = (AppiumBy.ID, 'com.app:id/back_button')
                self.title = (AppiumBy.ID, 'com.app:id/toolbar_title')
                self.menu_button = (AppiumBy.ID, 'com.app:id/menu_button')
            else:
                self.back_button = (AppiumBy.ACCESSIBILITY_ID, 'Back')
                self.title = (AppiumBy.ACCESSIBILITY_ID, 'Screen Title')
                self.menu_button = (AppiumBy.ACCESSIBILITY_ID, 'Menu')

        def go_back(self):
            """Tap back button"""
            self.driver.find_element(*self.back_button).click()

        def get_title(self) -> str:
            """Get navigation bar title"""
            return self.driver.find_element(*self.title).text

        def open_menu(self):
            """Open navigation menu"""
            self.driver.find_element(*self.menu_button).click()

    @staticmethod
    class Button:
        def __init__(self, element: WebElement):
            self.element = element

        def tap(self):
            self.element.click()

        def is_enabled(self) -> bool:
            return self.element.is_enabled()

        def get_text(self) -> str:
            return self.element.text

    @staticmethod
    class TextInput:
        def __init__(self, element: WebElement):
            self.element = element

        def enter(self, text: str):
            self.element.clear()
            self.element.send_keys(text)

        def get_value(self) -> str:
            return self.element.text

        def clear(self):
            self.element.clear()

# Layer 3: Page Objects
class LoginPage(BasePage):
    """Login page object"""

    # Locator dictionaries for platform abstraction
    LOCATORS = {
        'android': {
            'email_field': (AppiumBy.ID, 'com.app:id/email_field'),
            'password_field': (AppiumBy.ID, 'com.app:id/password_field'),
            'login_button': (AppiumBy.ID, 'com.app:id/login_button'),
            'forgot_password': (AppiumBy.ID, 'com.app:id/forgot_password'),
            'error_message': (AppiumBy.ID, 'com.app:id/error_message'),
            'welcome_text': (AppiumBy.ID, 'com.app:id/welcome_text')
        },
        'ios': {
            'email_field': (AppiumBy.ACCESSIBILITY_ID, 'email_field'),
            'password_field': (AppiumBy.ACCESSIBILITY_ID, 'password_field'),
            'login_button': (AppiumBy.ACCESSIBILITY_ID, 'login_button'),
            'forgot_password': (AppiumBy.ACCESSIBILITY_ID, 'forgot_password'),
            'error_message': (AppiumBy.ACCESSIBILITY_ID, 'error_message'),
            'welcome_text': (AppiumBy.ACCESSIBILITY_ID, 'welcome_text')
        }
    }

    def __init__(self, driver: WebDriver):
        super().__init__(driver)
        self.locators = self.LOCATORS.get(self.platform, self.LOCATORS['android'])

    def enter_email(self, email: str):
        """Enter email into email field"""
        email_field = self.wait_for_visible(self.locators['email_field'])
        self.enter_text(email_field, email)

    def enter_password(self, password: str):
        """Enter password into password field"""
        password_field = self.wait_for_visible(self.locators['password_field'])
        self.enter_text(password_field, password)

    def tap_login(self):
        """Tap login button"""
        login_button = self.wait_for_clickable(self.locators['login_button'])
        self.tap(login_button)

    def login(self, email: str, password: str):
        """Complete login flow"""
        self.enter_email(email)
        self.enter_password(password)
        self.tap_login()

    def tap_forgot_password(self):
        """Tap forgot password link"""
        forgot_password = self.wait_for_clickable(self.locators['forgot_password'])
        self.tap(forgot_password)

    def is_error_message_displayed(self) -> bool:
        """Check if error message is displayed"""
        try:
            error_message = self.wait_for_visible(self.locators['error_message'], timeout=5)
            return self.is_displayed(error_message)
        except TimeoutException:
            return False

    def get_error_message(self) -> str:
        """Get error message text"""
        error_message = self.wait_for_visible(self.locators['error_message'])
        return self.get_text(error_message)

    def is_login_button_enabled(self) -> bool:
        """Check if login button is enabled"""
        login_button = self.wait_for_visible(self.locators['login_button'])
        return login_button.is_enabled()

    def get_welcome_text(self) -> str:
        """Get welcome text"""
        welcome_text = self.wait_for_visible(self.locators['welcome_text'])
        return self.get_text(welcome_text)

class HomePage(BasePage):
    """Home page object"""

    LOCATORS = {
        'android': {
            'welcome_message': (AppiumBy.ID, 'com.app:id/welcome_message'),
            'profile_button': (AppiumBy.ID, 'com.app:id/profile_button'),
            'search_field': (AppiumBy.ID, 'com.app:id/search_field'),
            'logout_button': (AppiumBy.ID, 'com.app:id/logout_button'),
            'list_items': (AppiumBy.ID, 'com.app:id/list_item'),
            'menu_button': (AppiumBy.ACCESSIBILITY_ID, 'Open navigation drawer')
        },
        'ios': {
            'welcome_message': (AppiumBy.ACCESSIBILITY_ID, 'Welcome Message'),
            'profile_button': (AppiumBy.ACCESSIBILITY_ID, 'Profile'),
            'search_field': (AppiumBy.ACCESSIBILITY_ID, 'Search'),
            'logout_button': (AppiumBy.ACCESSIBILITY_ID, 'Logout'),
            'list_items': (AppiumBy.CLASS_NAME, 'XCUIElementTypeCell'),
            'menu_button': (AppiumBy.ACCESSIBILITY_ID, 'Menu')
        }
    }

    def __init__(self, driver: WebDriver):
        super().__init__(driver)
        self.locators = self.LOCATORS.get(self.platform, self.LOCATORS['android'])
        self.navigation_bar = MobileComponents.NavigationBar(driver)

    def get_welcome_message(self) -> str:
        """Get welcome message text"""
        welcome_message = self.wait_for_visible(self.locators['welcome_message'])
        return self.get_text(welcome_message)

    def navigate_to_profile(self):
        """Navigate to profile screen"""
        profile_button = self.wait_for_clickable(self.locators['profile_button'])
        self.tap(profile_button)

    def search(self, query: str):
        """Perform search"""
        search_field = self.wait_for_visible(self.locators['search_field'])
        self.enter_text(search_field, query)

        # Hide keyboard
        if self.is_android:
            self.driver.hide_keyboard()
        else:
            from appium.webdriver.common.appiumby import AppiumBy
            search_field.send_keys('\n')

    def logout(self):
        """Logout from the app"""
        logout_button = self.wait_for_clickable(self.locators['logout_button'])
        self.tap(logout_button)

        # Handle confirmation dialog
        if self.is_android:
            confirm_button = (AppiumBy.ID, 'android:id/button1')
        else:
            confirm_button = (AppiumBy.ACCESSIBILITY_ID, 'OK')

        try:
            self.wait_for_clickable(confirm_button, timeout=5).click()
        except TimeoutException:
            pass  # No confirmation dialog

    def get_list_item_count(self) -> int:
        """Get number of list items"""
        items = self.driver.find_elements(*self.locators['list_items'])
        return len(items)

    def tap_list_item(self, index: int):
        """Tap list item at specified index"""
        items = self.driver.find_elements(*self.locators['list_items'])
        if index < len(items):
            items[index].click()

    def is_user_logged_in(self) -> bool:
        """Check if user is logged in"""
        try:
            return self.wait_for_visible(self.locators['welcome_message'], timeout=5).is_displayed()
        except TimeoutException:
            return False

    def open_menu(self):
        """Open navigation menu"""
        self.navigation_bar.open_menu()

# Layer 2: Page Factory
class PageFactory:
    """Factory for managing page objects"""

    _instances = {}

    @classmethod
    def get_page(cls, driver: WebDriver, page_class):
        """Get or create page instance"""
        key = (page_class, id(driver))
        if key not in cls._instances:
            cls._instances[key] = page_class(driver)
        return cls._instances[key]

    @classmethod
    def clear_cache(cls):
        """Clear page cache"""
        cls._instances.clear()

