/**
 * Advanced Parallel Execution Framework
 * Supports multi-device, multi-platform parallel testing
 */
public class ParallelExecutionFramework {

    // Device pool manager
    static class DevicePoolManager {
        private static final int MAX_CONCURRENT_DEVICES = 10;
        private final Semaphore deviceSemaphore = new Semaphore(MAX_CONCURRENT_DEVICES, true);
        private final Map<String, DeviceInfo> availableDevices = new ConcurrentHashMap<>();
        private final Map<String, DeviceInfo> allocatedDevices = new ConcurrentHashMap<>();

        public DevicePoolManager() {
            initializeDevicePool();
        }

        private void initializeDevicePool() {
            // Add local devices
            availableDevices.put("android-emu-1", new DeviceInfo("Android", "emulator-5554", "Pixel_6_API_33", 4723));
            availableDevices.put("android-emu-2", new DeviceInfo("Android", "emulator-5556", "Pixel_7_API_34", 4724));
            availableDevices.put("ios-sim-1", new DeviceInfo("iOS", "iPhone 15", "iPhone_15_Simulator", 4725));

            // Add real devices via ADB detection
            detectConnectedDevices();
        }

        private void detectConnectedDevices() {
            try {
                Process process = Runtime.getRuntime().exec("adb devices");
                Scanner scanner = new Scanner(process.getInputStream());

                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    if (line.contains("\tdevice")) {
                        String deviceId = line.split("\t")[0];
                        if (!deviceId.startsWith("emulator")) {
                            String deviceName = getDeviceModel(deviceId);
                            int port = findAvailablePort();
                            availableDevices.put(deviceId, 
                                new DeviceInfo("Android", deviceId, deviceName, port));
                        }
                    }
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        public synchronized DeviceInfo allocateDevice(String platform, String testName) {
            try {
                deviceSemaphore.acquire();

                // Find suitable device
                DeviceInfo device = findSuitableDevice(platform);
                if (device != null) {
                    availableDevices.remove(device.getDeviceId());
                    allocatedDevices.put(device.getDeviceId(), device);
                    device.setAllocatedTest(testName);
                    System.out.println("Allocated device: " + device + " for test: " + testName);
                    return device;
                }

                deviceSemaphore.release();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
            return null;
        }

        public synchronized void releaseDevice(String deviceId) {
            DeviceInfo device = allocatedDevices.remove(deviceId);
            if (device != null) {
                availableDevices.put(deviceId, device);
                device.clearAllocation();
                deviceSemaphore.release();
                System.out.println("Released device: " + deviceId);
            }
        }

        private DeviceInfo findSuitableDevice(String platform) {
            return availableDevices.values().stream()
                .filter(d -> d.getPlatform().equalsIgnoreCase(platform))
                .findFirst()
                .orElse(null);
        }

        private int findAvailablePort() {
            // Simple port finder - in production use proper port management
            return 8200 + availableDevices.size();
        }

        private String getDeviceModel(String deviceId) {
            try {
                Process process = Runtime.getRuntime().exec("adb -s " + deviceId + " shell getprop ro.product.model");
                Scanner scanner = new Scanner(process.getInputStream());
                return scanner.hasNextLine() ? scanner.nextLine().trim() : "Unknown Device";
            } catch (Exception e) {
                return "Unknown Device";
            }
        }
    }

    // Device information class
    static class DeviceInfo {
        private final String platform;
        private final String deviceId;
        private final String deviceName;
        private final int appiumPort;
        private String allocatedTest;

        public DeviceInfo(String platform, String deviceId, String deviceName, int appiumPort) {
            this.platform = platform;
            this.deviceId = deviceId;
            this.deviceName = deviceName;
            this.appiumPort = appiumPort;
        }

        // Getters and setters
        public void setAllocatedTest(String testName) { this.allocatedTest = testName; }
        public void clearAllocation() { this.allocatedTest = null; }
        public String getPlatform() { return platform; }
        public String getDeviceId() { return deviceId; }
        public String getDeviceName() { return deviceName; }
        public int getAppiumPort() { return appiumPort; }

        @Override
        public String toString() {
            return String.format("%s (%s) on port %d", deviceName, platform, appiumPort);
        }
    }

    // Thread-local driver storage
    private static final ThreadLocal<AppiumDriver> threadLocalDriver = new ThreadLocal<>();
    private static final DevicePoolManager devicePool = new DevicePoolManager();
    private static final ExecutorService executorService = 
        Executors.newFixedThreadPool(5); // Configurable thread pool

    // Test factory for parallel execution
    public static class ParallelTestFactory {

        public static void executeTestsInParallel(List<Runnable> tests) {
            List<Future<?>> futures = new ArrayList<>();

            for (Runnable test : tests) {
                Future<?> future = executorService.submit(() -> {
                    try {
                        test.run();
                    } catch (Exception e) {
                        System.err.println("Test execution failed: " + e.getMessage());
                        e.printStackTrace();
                    }
                });
                futures.add(future);
            }

            // Wait for all tests to complete
            for (Future<?> future : futures) {
                try {
                    future.get();
                } catch (Exception e) {
                    System.err.println("Error waiting for test completion: " + e.getMessage());
                }
            }
        }
    }

    // TestNG parallel configuration
    @BeforeSuite
    public void beforeSuite() {
        System.out.println("Initializing parallel test suite...");
        System.out.println("Available devices: " + devicePool);
    }

    @BeforeMethod
    public void setupDriver(Method method) {
        // Get test configuration from method annotations or parameters
        String platform = getPlatformFromTest(method);
        String testName = method.getName();

        // Allocate device
        DeviceInfo device = devicePool.allocateDevice(platform, testName);
        if (device == null) {
            throw new RuntimeException("No available device for platform: " + platform);
        }

        try {
            // Start Appium server on device port (simplified - in production use proper server management)
            startAppiumServer(device.getAppiumPort());

            // Create driver with device-specific capabilities
            AppiumDriver driver = createDriver(device, method);
            threadLocalDriver.set(driver);

        } catch (Exception e) {
            devicePool.releaseDevice(device.getDeviceId());
            throw new RuntimeException("Failed to setup driver", e);
        }
    }

    @AfterMethod
    public void tearDownDriver(Method method) {
        AppiumDriver driver = threadLocalDriver.get();
        if (driver != null) {
            try {
                // Take screenshot on failure
                if (method.getAnnotation(Test.class).alwaysRun() || 
                    Thread.currentThread().getUncaughtExceptionHandler() != null) {
                    // Capture screenshot logic here
                }

                driver.quit();
            } finally {
                threadLocalDriver.remove();

                // Release device
                String deviceId = extractDeviceIdFromDriver(driver);
                if (deviceId != null) {
                    devicePool.releaseDevice(deviceId);
                }
            }
        }
    }

    @AfterSuite
    public void afterSuite() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
        System.out.println("Parallel test suite completed");
    }

    // Utility methods
    private String getPlatformFromTest(Method method) {
        // Extract platform from test annotation or configuration
        Test testAnnotation = method.getAnnotation(Test.class);
        if (testAnnotation != null && testAnnotation.groups().length > 0) {
            for (String group : testAnnotation.groups()) {
                if (group.equalsIgnoreCase("android") || group.equalsIgnoreCase("ios")) {
                    return group;
                }
            }
        }
        return "Android"; // Default
    }

    private void startAppiumServer(int port) {
        // In production, use AppiumServiceBuilder or manage server processes
        System.out.println("Starting Appium server on port: " + port);
        // Implementation depends on your Appium setup
    }

    private AppiumDriver createDriver(DeviceInfo device, Method method) throws Exception {
        DesiredCapabilities caps = new DesiredCapabilities();

        // Common capabilities
        caps.setCapability("platformName", device.getPlatform());
        caps.setCapability("deviceName", device.getDeviceName());
        caps.setCapability("automationName", 
            device.getPlatform().equalsIgnoreCase("Android") ? "UiAutomator2" : "XCUITest");

        // App-specific capabilities
        caps.setCapability("app", getAppPath(device.getPlatform()));

        // Test-specific capabilities
        caps.setCapability("testName", method.getName());
        caps.setCapability("build", "Parallel Execution Build");

        // Platform-specific capabilities
        if (device.getPlatform().equalsIgnoreCase("Android")) {
            caps.setCapability("udid", device.getDeviceId());
            caps.setCapability("systemPort", 8200 + new Random().nextInt(100)); // Unique system port
        } else {
            caps.setCapability("udid", device.getDeviceId());
            caps.setCapability("wdaLocalPort", 8100 + new Random().nextInt(100));
        }

        // Create driver
        URL appiumUrl = new URL("http://127.0.0.1:" + device.getAppiumPort() + "/wd/hub");

        if (device.getPlatform().equalsIgnoreCase("Android")) {
            return new AndroidDriver(appiumUrl, caps);
        } else {
            return new IOSDriver(appiumUrl, caps);
        }
    }

    private String extractDeviceIdFromDriver(AppiumDriver driver) {
        // Extract device ID from driver capabilities
        return (String) driver.getCapabilities().getCapability("udid");
    }

    private String getAppPath(String platform) {
        // Return appropriate app path based on platform
        return platform.equalsIgnoreCase("Android") 
            ? "/path/to/android/app.apk" 
            : "/path/to/ios/app.ipa";
    }
}

