            this.endpoint = getDefaultEndpoint(provider);
        }

        private String getDefaultEndpoint(CloudProvider provider) {
            switch (provider) {
                case BROWSERSTACK:
                    return "https://hub.browserstack.com/wd/hub";
                case SAUCE_LABS:
                    return "https://ondemand.us-west-1.saucelabs.com:443/wd/hub";
                case AWS_DEVICE_FARM:
                    return "https://devicefarm.amazonaws.com";
                case FIREBASE_TEST_LAB:
                    return "https://cloud.testlab.google.com";
                case LAMBDA_TEST:
                    return "https://hub.lambdatest.com/wd/hub";
                case PERFECTO:
                    return "https://perfectomobile.com/nexperience/wd/hub";
                default:
                    throw new IllegalArgumentException("Unknown provider: " + provider);
            }
        }

        public CloudConfig withOption(String key, Object value) {
            this.providerOptions.put(key, value);
            return this;
        }

        public CloudConfig withEndpoint(String endpoint) {
            return this;
        }

        // Getters
        public CloudProvider getProvider() { return provider; }
        public String getUsername() { return username; }
        public String getAccessKey() { return accessKey; }
        public String getEndpoint() { return endpoint; }
        public Map<String, Object> getProviderOptions() { return providerOptions; }
    }

    // Device request specification
    public static class DeviceRequest {
        private String platform; // "android" or "ios"
        private String osVersion;
        private String deviceName;
        private String deviceId;
        private boolean realDevice = true;
        private Map<String, Object> capabilities = new HashMap<>();

        public DeviceRequest(String platform) {
            this.platform = platform;
        }

        public DeviceRequest withOsVersion(String osVersion) {
            this.osVersion = osVersion;
            return this;
        }

        public DeviceRequest withDeviceName(String deviceName) {
            this.deviceName = deviceName;
            return this;
        }

        public DeviceRequest withRealDevice(boolean realDevice) {
            this.realDevice = realDevice;
            return this;
        }

        public DeviceRequest withCapability(String key, Object value) {
            this.capabilities.put(key, value);
            return this;
        }

        // Getters
        public String getPlatform() { return platform; }
        public String getOsVersion() { return osVersion; }
        public String getDeviceName() { return deviceName; }
        public boolean isRealDevice() { return realDevice; }
        public Map<String, Object> getCapabilities() { return capabilities; }
    }

    // Cloud provider adapter interface
    public interface CloudProviderAdapter {
        MutableCapabilities createCapabilities(CloudConfig config, DeviceRequest request);
        URL getEndpoint(CloudConfig config);
        void updateTestStatus(RemoteWebDriver driver, boolean passed, String reason);
        Map<String, Object> getTestInfo(RemoteWebDriver driver);
    }

    // BrowserStack adapter implementation
    public static class BrowserStackAdapter implements CloudProviderAdapter {
        @Override
        public MutableCapabilities createCapabilities(CloudConfig config, DeviceRequest request) {
            DesiredCapabilities caps = new DesiredCapabilities();

            // BrowserStack specific capabilities
            caps.setCapability("browserstack.user", config.getUsername());
            caps.setCapability("browserstack.key", config.getAccessKey());
            caps.setCapability("browserstack.debug", "true");
            caps.setCapability("browserstack.networkLogs", "true");
            caps.setCapability("browserstack.video", "true");
            caps.setCapability("browserstack.appium_version", "2.0.0");

            // Project metadata
            caps.setCapability("project", "Mobile Automation Project");
            caps.setCapability("build", System.getenv("BUILD_NUMBER") != null ? 
                System.getenv("BUILD_NUMBER") : "Local Build");
            caps.setCapability("name", Thread.currentThread().getName());

            // Device capabilities
            caps.setCapability("platformName", request.getPlatform());
            caps.setCapability("platformVersion", request.getOsVersion());
            caps.setCapability("deviceName", request.getDeviceName());
            caps.setCapability("realMobile", request.isRealDevice());

            // App capabilities
            if (config.getProviderOptions().containsKey("app")) {
                caps.setCapability("app", config.getProviderOptions().get("app"));
            }

            // Additional capabilities from request
            request.getCapabilities().forEach(caps::setCapability);

            return caps;
        }

        @Override
        public URL getEndpoint(CloudConfig config) {
            try {
                return new URL(config.getEndpoint());
            } catch (MalformedURLException e) {
                throw new RuntimeException("Invalid BrowserStack endpoint", e);
            }
        }

        @Override
        public void updateTestStatus(RemoteWebDriver driver, boolean passed, String reason) {
            try {
                driver.executeScript("browserstack_executor: {\"action\": \"setSessionStatus\", \"arguments\": {\"status\": \"" + 
                    (passed ? "passed" : "failed") + "\", \"reason\": \"" + reason + "\"}}");
            } catch (Exception e) {
                System.err.println("Failed to update BrowserStack test status: " + e.getMessage());
            }
        }

        @Override
        public Map<String, Object> getTestInfo(RemoteWebDriver driver) {
            Map<String, Object> info = new HashMap<>();
            try {
                String sessionId = driver.getSessionId().toString();
                info.put("sessionId", sessionId);
                info.put("dashboardUrl", "https://app-automate.browserstack.com/dashboard/v2/builds/" + sessionId);
                info.put("videoUrl", "https://app-automate.browserstack.com/sessions/" + sessionId + "/video");
            } catch (Exception e) {
                // Ignore errors
            }
            return info;
        }
    }

    // Sauce Labs adapter implementation
    public static class SauceLabsAdapter implements CloudProviderAdapter {
        @Override
        public MutableCapabilities createCapabilities(CloudConfig config, DeviceRequest request) {
            DesiredCapabilities caps = new DesiredCapabilities();

            // Sauce Labs specific capabilities
            MutableCapabilities sauceOptions = new MutableCapabilities();
            sauceOptions.setCapability("username", config.getUsername());
            sauceOptions.setCapability("accessKey", config.getAccessKey());
            sauceOptions.setCapability("build", System.getenv("BUILD_NUMBER") != null ? 
                System.getenv("BUILD_NUMBER") : "Local Build");
            sauceOptions.setCapability("name", Thread.currentThread().getName());
            sauceOptions.setCapability("appiumVersion", "2.0.0");

            // Device capabilities
            caps.setCapability("platformName", request.getPlatform());
            caps.setCapability("platformVersion", request.getOsVersion());
            caps.setCapability("deviceName", request.getDeviceName());
            caps.setCapability("appium:deviceName", request.getDeviceName());

            // App capabilities
            if (config.getProviderOptions().containsKey("app")) {
                caps.setCapability("appium:app", config.getProviderOptions().get("app"));
            }

            // Set sauce options
            caps.setCapability("sauce:options", sauceOptions);

            // Additional capabilities from request
            request.getCapabilities().forEach((key, value) -> {
                if (key.startsWith("appium:")) {
                    caps.setCapability(key, value);
                } else {
                    caps.setCapability("appium:" + key, value);
                }
            });

            return caps;
        }

        @Override
        public URL getEndpoint(CloudConfig config) {
            try {
                return new URL(config.getEndpoint());
            } catch (MalformedURLException e) {
                throw new RuntimeException("Invalid Sauce Labs endpoint", e);
            }
        }

        @Override
        public void updateTestStatus(RemoteWebDriver driver, boolean passed, String reason) {
            try {
                driver.executeScript("sauce:job-result=" + (passed ? "passed" : "failed"));
            } catch (Exception e) {
                System.err.println("Failed to update Sauce Labs test status: " + e.getMessage());
            }
        }

        @Override
        public Map<String, Object> getTestInfo(RemoteWebDriver driver) {
            Map<String, Object> info = new HashMap<>();
            try {
                String sessionId = driver.getSessionId().toString();
                info.put("sessionId", sessionId);
                info.put("dashboardUrl", "https://app.saucelabs.com/tests/" + sessionId);
            } catch (Exception e) {
                // Ignore errors
            }
            return info;
        }
    }

    // Adapter factory
    public static class CloudAdapterFactory {
        private static final Map<CloudProvider, Supplier<CloudProviderAdapter>> adapterRegistry = new HashMap<>();

        static {
            adapterRegistry.put(CloudProvider.BROWSERSTACK, BrowserStackAdapter::new);
            adapterRegistry.put(CloudProvider.SAUCE_LABS, SauceLabsAdapter::new);
            // Register other adapters here
        }

        public static CloudProviderAdapter getAdapter(CloudProvider provider) {
            Supplier<CloudProviderAdapter> supplier = adapterRegistry.get(provider);
            if (supplier == null) {
                throw new IllegalArgumentException("No adapter registered for provider: " + provider);
            }
            return supplier.get();
        }
    }

    // Main cloud test manager
    public static class CloudTestManager {
        private final CloudConfig cloudConfig;
        private final CloudProviderAdapter adapter;
        private final ThreadLocal<RemoteWebDriver> threadLocalDriver = new ThreadLocal<>();
        private final Map<String, DeviceRequest> activeDevices = new ConcurrentHashMap<>();

        public CloudTestManager(CloudConfig cloudConfig) {
            this.cloudConfig = cloudConfig;
            this.adapter = CloudAdapterFactory.getAdapter(cloudConfig.getProvider());
        }

        public RemoteWebDriver createDriver(DeviceRequest deviceRequest) {
            try {
                MutableCapabilities caps = adapter.createCapabilities(cloudConfig, deviceRequest);
                URL endpoint = adapter.getEndpoint(cloudConfig);

                RemoteWebDriver driver;
                if (deviceRequest.getPlatform().equalsIgnoreCase("android")) {
                    driver = new AndroidDriver(endpoint, caps);
                } else {
                    driver = new IOSDriver(endpoint, caps);
                }

                threadLocalDriver.set(driver);
                activeDevices.put(driver.getSessionId().toString(), deviceRequest);

                System.out.println("Created cloud driver for " + deviceRequest.getDeviceName() + 
                    " on " + cloudConfig.getProvider());

                return driver;

            } catch (Exception e) {
                throw new RuntimeException("Failed to create cloud driver", e);
            }
        }

        public void markTestPassed(String reason) {
            RemoteWebDriver driver = threadLocalDriver.get();
            if (driver != null) {
                adapter.updateTestStatus(driver, true, reason);
            }
        }

        public void markTestFailed(String reason) {
            RemoteWebDriver driver = threadLocalDriver.get();
            if (driver != null) {
                adapter.updateTestStatus(driver, false, reason);
            }
        }

        public void tearDown() {
            RemoteWebDriver driver = threadLocalDriver.get();
            if (driver != null) {
                try {
                    String sessionId = driver.getSessionId().toString();
                    Map<String, Object> testInfo = adapter.getTestInfo(driver);

                    System.out.println("Test completed. Session ID: " + sessionId);
                    System.out.println("Dashboard URL: " + testInfo.get("dashboardUrl"));

                    driver.quit();
                    activeDevices.remove(sessionId);

                } catch (Exception e) {
                    System.err.println("Error during teardown: " + e.getMessage());
                } finally {
                    threadLocalDriver.remove();
                }
            }
        }

        public Map<String, Object> getCurrentTestInfo() {
            RemoteWebDriver driver = threadLocalDriver.get();
            if (driver != null) {
                return adapter.getTestInfo(driver);
            }
            return Collections.emptyMap();
        }

        public List<DeviceRequest> getActiveDevices() {
            return new ArrayList<>(activeDevices.values());
        }
    }

