    // Utility class for cost estimation
    public static class CloudCostEstimator {

        public static double estimateCost(CloudProvider provider, int deviceMinutes, boolean realDevice) {
            // Simplified cost estimation
            // In reality, use provider-specific pricing APIs

            double costPerMinute;
            switch (provider) {
                case BROWSERSTACK:
                    costPerMinute = realDevice ? 0.08 : 0.02; // Example rates
                    break;
                case SAUCE_LABS:
                    costPerMinute = realDevice ? 0.07 : 0.015;
                    break;
                case AWS_DEVICE_FARM:
                    costPerMinute = 0.17; // Per device minute
                    break;
                case FIREBASE_TEST_LAB:
                    costPerMinute = realDevice ? 0.20 : 0.05;
                    break;
                default:
                    costPerMinute = 0.10;
            }

            return deviceMinutes * costPerMinute;
        }

        public static Map<String, Double> compareProviders(int androidTests, int iosTests, int minutesPerTest) {
            Map<String, Double> costs = new HashMap<>();

            int totalDeviceMinutes = (androidTests + iosTests) * minutesPerTest;

            for (CloudProvider provider : CloudProvider.values()) {
                double cost = estimateCost(provider, totalDeviceMinutes, true);
                costs.put(provider.name(), cost);
            }

            return costs;
        }
    }
