package com.example.app.test.architecture

import androidx.test.espresso.Espresso
import androidx.test.espresso.action.ViewActions
import androidx.test.espresso.assertion.ViewAssertions
import androidx.test.espresso.matcher.ViewMatchers
import org.hamcrest.Matchers

// Screenplay Pattern Implementation for Espresso

// 1. Actor - Represents a user with abilities
class Actor(private val name: String) {

    private val abilities = mutableListOf<Ability>()

    fun can(ability: Ability): Actor {
        abilities.add(ability)
        return this
    }

    fun attemptsTo(vararg tasks: Task): Actor {
        tasks.forEach { task ->
            task.performWith(this)
        }
        return this
    }

    fun shouldSeeThat(question: Question): Actor {
        question.answeredBy(this)
        return this
    }

    fun <T> using(abilityClass: Class<T>): T {
        return abilities.find { it.javaClass == abilityClass } as T
            ?: throw IllegalArgumentException("Actor doesn't have ability: $abilityClass")
    }
}

// 2. Task - Business task the actor wants to accomplish
interface Task {
    fun performWith(actor: Actor)
}

// 3. Interaction - Low-level UI interaction
interface Interaction {
    fun execute()
}

// 4. Ability - What the actor can do
interface Ability

// 5. Question - How the actor can verify outcomes
interface Question {
    fun answeredBy(actor: Actor)
}

// Concrete Implementations

// Abilities
class BrowseProductsAbility : Ability {
    fun searchFor(product: String) {
        Espresso.onView(ViewMatchers.withId(R.id.search_field))
            .perform(ViewActions.typeText(product))
    }

    fun selectProductAt(position: Int) {
        Espresso.onView(ViewMatchers.withId(R.id.products_recycler))
            .perform(RecyclerViewActions.actionOnItemAtPosition<RecyclerView.ViewHolder>(
                position, ViewActions.click()
            ))
    }
}

class PurchaseAbility : Ability {
    fun addToCart() {
        Espresso.onView(ViewMatchers.withId(R.id.add_to_cart_button))
            .perform(ViewActions.click())
    }

    fun proceedToCheckout() {
        Espresso.onView(ViewMatchers.withId(R.id.checkout_button))
            .perform(ViewActions.click())
    }
}

// Tasks
class LoginTask(private val email: String, private val password: String) : Task {
    override fun performWith(actor: Actor) {
        // Using direct Espresso interactions within task
        Espresso.onView(ViewMatchers.withId(R.id.email_field))
            .perform(ViewActions.typeText(email))

        Espresso.onView(ViewMatchers.withId(R.id.password_field))
            .perform(ViewActions.typeText(password))

        Espresso.onView(ViewMatchers.withId(R.id.login_button))
            .perform(ViewActions.click())
    }
}

class SearchForProductTask(private val productName: String) : Task {
    override fun performWith(actor: Actor) {
        val browseAbility = actor.using(BrowseProductsAbility::class.java)
        browseAbility.searchFor(productName)
    }
}

class AddToCartTask : Task {
    override fun performWith(actor: Actor) {
        val purchaseAbility = actor.using(PurchaseAbility::class.java)
        purchaseAbility.addToCart()
    }
}

// Questions
class IsLoggedInQuestion : Question {
    override fun answeredBy(actor: Actor) {
        Espresso.onView(ViewMatchers.withId(R.id.welcome_message))
            .check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
    }
}

class IsProductDisplayedQuestion(private val productName: String) : Question {
    override fun answeredBy(actor: Actor) {
        Espresso.onView(
            Matchers.allOf(
                ViewMatchers.withId(R.id.product_name),
                ViewMatchers.withText(Matchers.containsString(productName))
            )
        ).check(ViewAssertions.matches(ViewMatchers.isDisplayed()))
    }
}

// Usage in Tests
class ScreenplayPatternTests {

    @Test
    fun testCustomerPurchasesProduct() {
        // Create actor with abilities
        val customer = Actor("Regular Customer")
            .can(BrowseProductsAbility())
            .can(PurchaseAbility())

        // Perform business tasks
        customer.attemptsTo(
            LoginTask("customer@example.com", "password123"),
            SearchForProductTask("iPhone"),
            AddToCartTask()
        )

        // Verify outcomes
        customer.shouldSeeThat(IsLoggedInQuestion())
        customer.shouldSeeThat(IsProductDisplayedQuestion("iPhone"))
    }
}

// BDD Integration with Cucumber
class BDDStepDefinitions {

    private lateinit var actor: Actor

    @Given("I am a logged in user")
    fun iAmALoggedInUser() {
        actor = Actor("Test User")
            .can(BrowseProductsAbility())
            .can(PurchaseAbility())

        actor.attemptsTo(
            LoginTask("test@example.com", "password123")
        )
    }

    @When("I search for {string}")
    fun iSearchForProduct(productName: String) {
        actor.attemptsTo(
            SearchForProductTask(productName)
        )
    }

    @Then("I should see product {string} in results")
    fun iShouldSeeProductInResults(productName: String) {
        actor.shouldSeeThat(
            IsProductDisplayedQuestion(productName)
        )
    }
}

