import XCTest

// MARK: - MVVM Test Architecture for XCUITest

// Model: Test Data
struct TestUser {
    let email: String
    let password: String
    let name: String
    let isAdmin: Bool

    static var regularUser: TestUser {
        return TestUser(
            email: "user@example.com",
            password: "password123",
            name: "Regular User",
            isAdmin: false
        )
    }

    static var adminUser: TestUser {
        return TestUser(
            email: "admin@example.com",
            password: "admin123",
            name: "Admin User",
            isAdmin: true
        )
    }
}

struct Product {
    let id: String
    let name: String
    let price: Double
    let category: String
}

// View: Page Objects
protocol Page {
    var app: XCUIApplication { get }
    var isDisplayed: Bool { get }
}

class LoginPage: Page {
    let app: XCUIApplication

    init(app: XCUIApplication) {
        self.app = app
    }

    var isDisplayed: Bool {
        return app.otherElements["login_screen"].waitForExistence(timeout: 3)
    }

    func enterEmail(_ email: String) {
        let emailField = app.textFields["email_field"]
        emailField.tap()
        emailField.typeText(email)
    }

    func enterPassword(_ password: String) {
        let passwordField = app.secureTextFields["password_field"]
        passwordField.tap()
        passwordField.typeText(password)
    }

    func tapLogin() {
        app.buttons["login_button"].tap()
    }
}

class ProductListPage: Page {
    let app: XCUIApplication

    init(app: XCUIApplication) {
        self.app = app
    }

    var isDisplayed: Bool {
        return app.otherElements["product_list_screen"].waitForExistence(timeout: 3)
    }

    func searchForProduct(_ query: String) {
        let searchField = app.searchFields["product_search"]
        searchField.tap()
        searchField.typeText(query)
        app.buttons["Search"].tap()
    }

    func selectProduct(at index: Int) {
        let productTable = app.tables["products_table"]
        if productTable.cells.count > index {
            productTable.cells.element(boundBy: index).tap()
        }
    }
}

// ViewModel: Test Logic
class LoginViewModel {
    private let page: LoginPage
    private var user: TestUser?

    init(page: LoginPage) {
        self.page = page
    }

    func login(with user: TestUser) -> ProductListViewModel {
        self.user = user

        page.enterEmail(user.email)
        page.enterPassword(user.password)
        page.tapLogin()

        // Verify login success
        let productListPage = ProductListPage(app: page.app)
        XCTAssertTrue(
            productListPage.isDisplayed,
            "Should be redirected to product list after login"
        )

        return ProductListViewModel(page: productListPage, user: user)
    }
}

class ProductListViewModel {
    private let page: ProductListPage
    private let user: TestUser
    private var selectedProduct: Product?

    init(page: ProductListPage, user: TestUser) {
        self.page = page
        self.user = user
    }

    func searchForProduct(_ query: String) -> Self {
        page.searchForProduct(query)
        return self
    }

    func verifyResultsContain(_ productName: String) -> Self {
        let resultsTable = page.app.tables["search_results_table"]
        XCTAssertTrue(resultsTable.waitForExistence(timeout: 3))

        // Check if any result contains the product name
        let predicate = NSPredicate(format: "label CONTAINS[c] %@", productName)
        let matchingCells = resultsTable.cells.containing(predicate)
        XCTAssertGreaterThan(matchingCells.count, 0, "Should find at least one product matching '\(productName)'")

        return self
    }

    func selectFirstResult() -> ProductDetailViewModel {
        let resultsTable = page.app.tables["search_results_table"]
        resultsTable.cells.firstMatch.tap()

        let productDetailPage = ProductDetailPage(app: page.app)
        XCTAssertTrue(productDetailPage.isDisplayed)

        return ProductDetailViewModel(page: productDetailPage, user: user)
    }
}

class ProductDetailViewModel {
    private let page: ProductDetailPage
    private let user: TestUser

    init(page: ProductDetailPage, user: TestUser) {
        self.page = page
        self.user = user
    }

    func addToCart() -> CartViewModel {
        page.tapAddToCart()

        // Handle any alerts
        let alert = page.app.alerts.firstMatch
        if alert.waitForExistence(timeout: 2) {
            alert.buttons["OK"].tap()
        }

        let cartPage = CartPage(app: page.app)
        // Navigate to cart (implementation depends on app navigation)
        page.app.buttons["cart_button"].tap()

        XCTAssertTrue(cartPage.isDisplayed)
        return CartViewModel(page: cartPage, user: user)
    }
}

// Usage in Tests
class MVVMArchitectureTests: XCTestCase {

    var app: XCUIApplication!

    override func setUp() {
