// BDD with XCTest Gherkin
import XCTestGherkin

class BDDTests: XCTestCase, XCTestGherkin {

    var app: XCUIApplication!
    var currentUser: TestUser!

    override func setUp() {
        super.setUp()

        app = XCUIApplication()
        app.launchArguments = ["--uitesting"]
        app.launch()
    }

    func testFeatures() {
        given("I am on the login screen")
        when("I enter valid credentials")
        then("I should see the product list")
    }

    // Step Definitions
    func givenIAmOnTheLoginScreen() {
        let loginPage = LoginPage(app: app)
        XCTAssertTrue(loginPage.isDisplayed)
    }

    func whenIEnterValidCredentials() {
        let loginPage = LoginPage(app: app)
        currentUser = .regularUser

        loginPage.enterEmail(currentUser.email)
        loginPage.enterPassword(currentUser.password)
        loginPage.tapLogin()
    }

    func thenIShouldSeeTheProductList() {
        let productListPage = ProductListPage(app: app)
        XCTAssertTrue(
            productListPage.waitForExistence(timeout: 5),
            "Should be redirected to product list"
        )
    }
}

