// 1. Memory Optimization: Object Pooling
class ConnectionPool private constructor() {
    companion object {
        private val MAX_POOL_SIZE = 5
        private val pool = mutableListOf<DatabaseConnection>()
        private val lock = Any()

        fun acquire(): DatabaseConnection {
            synchronized(lock) {
                return if (pool.isNotEmpty()) {
                    pool.removeAt(pool.size - 1)
                } else {
                    DatabaseConnection()
                }
            }
        }

        fun release(connection: DatabaseConnection) {
            synchronized(lock) {
                if (pool.size < MAX_POOL_SIZE) {
                    pool.add(connection)
                } else {
                    connection.close()
                }
            }
        }
    }
}

class DatabaseConnection {
    fun close() { /* Close connection */ }
}

// 2. Memory Optimization: Weak References for Listeners
class DataManager {
    private val listeners = mutableListOf<WeakReference<DataListener>>()

    fun addListener(listener: DataListener) {
        listeners.add(WeakReference(listener))
    }

    private fun notifyListeners(data: Any) {
        val iterator = listeners.iterator()
        while (iterator.hasNext()) {
            val listenerRef = iterator.next()
            val listener = listenerRef.get()
            if (listener != null) {
                listener.onDataChanged(data)
            } else {
                iterator.remove() // Clean up garbage collected listeners
            }
        }
    }
}

interface DataListener {
    fun onDataChanged(data: Any)
}

// 3. Image Loading Optimization with Caching
object ImageCacheManager {
    private const val MAX_MEMORY = (Runtime.getRuntime().maxMemory() / 1024).toInt() / 8
    private val memoryCache: LruCache<String, Bitmap> = object : LruCache<String, Bitmap>(MAX_MEMORY) {
        override fun sizeOf(key: String, bitmap: Bitmap): Int {
            return bitmap.byteCount / 1024
        }
    }

    private val diskCacheDir: File by lazy {
        File(App.context.cacheDir, "images")
    }

    init {
        if (!diskCacheDir.exists()) {
            diskCacheDir.mkdirs()
        }
    }

    suspend fun loadBitmap(imageUrl: String, width: Int, height: Int): Bitmap? = withContext(IO) {
        // Check memory cache first
        memoryCache[imageUrl]?.let { return@withContext it }

        // Check disk cache
        val cacheFile = File(diskCacheDir, imageUrl.hashCode().toString())
        if (cacheFile.exists()) {
            val options = BitmapFactory.Options().apply {
                inJustDecodeBounds = true
                BitmapFactory.decodeFile(cacheFile.absolutePath, this)

                // Calculate sampling
                val imageHeight = outHeight
                val imageWidth = outWidth
                var scaleFactor = 1

                if (imageHeight > height || imageWidth > width) {
                    val halfHeight = imageHeight / 2
                    val halfWidth = imageWidth / 2

                    while ((halfHeight / scaleFactor) >= height && 
                           (halfWidth / scaleFactor) >= width) {
                        scaleFactor *= 2
                    }
                }

                inJustDecodeBounds = false
                inSampleSize = scaleFactor
                inPreferredConfig = Bitmap.Config.RGB_565
            }

            val bitmap = BitmapFactory.decodeFile(cacheFile.absolutePath, options)
            bitmap?.let { memoryCache.put(imageUrl, it) }
            return@withContext bitmap
        }

        // Download and cache
        val bitmap = downloadAndDecodeBitmap(imageUrl, width, height)
        bitmap?.let {
            memoryCache.put(imageUrl, it)
            // Cache to disk in background
            withContext(NonCancellable) {
                cacheBitmapToDisk(imageUrl, it)
            }
        }
        return@withContext bitmap
    }

