// 4. RecyclerView Optimization
class OptimizedAdapter(private val items: List<String>) : 
    RecyclerView.Adapter<OptimizedAdapter.ViewHolder>() {

    // View type constants
    private companion object {
        const val VIEW_TYPE_ITEM = 0
        const val VIEW_TYPE_LOADING = 1
    }

    // Efficient ViewHolder pattern
    class ViewHolder(view: View) : RecyclerView.ViewHolder(view) {
        // View references
        private val textView = view.findViewById<TextView>(R.id.text_view)

        // Bind data efficiently
        fun bind(item: String) {
            // Avoid unnecessary binding
            if (textView.text != item) {
                textView.text = item
            }

            // Optimize view state
            itemView.isClickable = true
            itemView.isFocusable = true
        }

        // Clear resources when view is recycled
        fun clear() {
            textView.text = ""
            itemView.isClickable = false
            itemView.isFocusable = false
        }
    }

    // Pre-calculate stable IDs for better animation performance
    private val stableIdMap = mutableMapOf<String, Long>()
    private var nextStableId: Long = 0

    init {
        setHasStableIds(true)
        items.forEach { item ->
            stableIdMap[item] = nextStableId++
        }
    }

    override fun getItemId(position: Int): Long {
        return stableIdMap[items[position]] ?: super.getItemId(position)
    }

    override fun getItemViewType(position: Int): Int {
        return VIEW_TYPE_ITEM
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ViewHolder {
        // Inflate only when necessary
        val view = LayoutInflater.from(parent.context)
            .inflate(R.layout.item_layout, parent, false)
        return ViewHolder(view)
    }

    override fun onBindViewHolder(holder: ViewHolder, position: Int) {
        holder.bind(items[position])
    }

    override fun getItemCount(): Int = items.size

    // Optimize for partial updates
    override fun onBindViewHolder(holder: ViewHolder, position: Int, payloads: List<Any>) {
        if (payloads.isEmpty()) {
            super.onBindViewHolder(holder, position, payloads)
        } else {
            // Handle partial updates
            payloads.forEach { payload ->
                when (payload) {
                    is String -> holder.bind(payload)
                }
            }
        }
    }

    // Pre-fetch optimization
    override fun onViewRecycled(holder: ViewHolder) {
        super.onViewRecycled(holder)
        holder.clear()
    }
}

// 5. Network Optimization: HTTP Client with Caching
object OptimizedHttpClient {
    private const val CACHE_SIZE = 10 * 1024 * 1024L // 10 MB

    val instance: OkHttpClient by lazy {
        val cache = Cache(File(App.context.cacheDir, "http"), CACHE_SIZE)

        OkHttpClient.Builder()
            .cache(cache)
            .addInterceptor { chain ->
                val request = chain.request()
                val response = chain.proceed(request)

                // Add cache control
                response.newBuilder()
                    .header("Cache-Control", "public, max-age=60")
                    .build()
            }
            .addNetworkInterceptor { chain ->
                val response = chain.proceed(chain.request())
                response.newBuilder()
                    .header("Cache-Control", "public, max-age=31536000") // 1 year for static assets
                    .build()
            }
            .build()
    }

    suspend fun makeRequest(url: String): String? = withContext(IO) {
        try {
            val request = Request.Builder()
                .url(url)
                .header("Accept-Encoding", "gzip")
                .build()

            instance.newCall(request).execute().use { response ->
                if (response.isSuccessful) {
                    response.body?.string()
                } else {
                    null
                }
            }
        } catch (e: Exception) {
            null
        }
    }
}

