// 10. Performance Monitoring
object PerformanceMonitor {

    private val frameTimes = ArrayDeque<Long>()
    private const val MAX_FRAME_SAMPLES = 120
    private val frameLock = Any()

    fun onFrame() {
        val currentTime = System.nanoTime()

        synchronized(frameLock) {
            frameTimes.addLast(currentTime)

            // Keep only recent samples
            while (frameTimes.size > MAX_FRAME_SAMPLES) {
                frameTimes.removeFirst()
            }

            // Calculate FPS if we have enough samples
            if (frameTimes.size >= 2) {
                val timeSpan = (frameTimes.last() - frameTimes.first()) / 1_000_000_000.0
                val fps = (frameTimes.size - 1) / timeSpan

                if (fps < 55) {
                    // Log or report low FPS
                    Log.w("Performance", "Low FPS detected: $fps")
                }
            }
        }
    }

    fun measureOperation(operationName: String, block: () -> Unit) {
        val startTime = System.nanoTime()
        block()
        val duration = (System.nanoTime() - startTime) / 1_000_000.0

        if (duration > 16.67) { // More than one frame at 60 FPS
            Log.w("Performance", "$operationName took ${duration}ms")
        }
    }
}

