@Retention(AnnotationRetention.RUNTIME)
@Target(AnnotationTarget.FUNCTION)
annotation class FlakyTest(
    val maxRetries: Int = 3,
    val minSuccess: Int = 1
)

class FlakyTestRule : TestRule {
    override fun apply(base: Statement, description: Description): Statement {
        return object : Statement() {
            override fun evaluate() {
                val annotation = description.getAnnotation(FlakyTest::class.java)
                if (annotation == null) {
                    base.evaluate()
                    return
                }

                var lastFailure: Throwable? = null
                var successes = 0

                for (i in 1..annotation.maxRetries) {
                    try {
                        base.evaluate()
                        successes++
                        if (successes >= annotation.minSuccess) {
                            return
                        }
                    } catch (e: Throwable) {
                        lastFailure = e
                        println("Flaky test attempt $i failed: ${e.message}")
                    }
                }

                throw AssertionError(
                    "Flaky test failed after ${annotation.maxRetries} attempts. " +
                    "Required ${annotation.minSuccess} successes, got $successes",
                    lastFailure
                )
            }
        }
    }
}

