// Test data cleanup strategy
class TestDataManager {
  constructor() {
    this.createdIds = {
      users: [],
      products: [],
      orders: []
    };
  }

  async createTestUser(userData) {
    const response = await request(app)
      .post('/api/users')
      .send(userData);

    const userId = response.body.id;
    this.createdIds.users.push(userId);

    return response.body;
  }

  async cleanup() {
    // Delete in reverse order to respect foreign keys
    for (const orderId of this.createdIds.orders.reverse()) {
      await request(app).delete(`/api/orders/${orderId}`);
    }

    for (const productId of this.createdIds.products.reverse()) {
      await request(app).delete(`/api/products/${productId}`);
    }

    for (const userId of this.createdIds.users.reverse()) {
      await request(app).delete(`/api/users/${userId}`);
    }

    this.createdIds = { users: [], products: [], orders: [] };
  }
}

