import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Trend, Rate, Counter } from 'k6/metrics';

// Custom metrics
const responseTimeTrend = new Trend('response_time');
const errorRate = new Rate('errors');
const requestCounter = new Counter('requests');

// Configuration
export const options = {
  // Smoke test (light load)
  // stages: [
  //   { duration: '30s', target: 10 },
  //   { duration: '1m', target: 10 },
  //   { duration: '30s', target: 0 },
  // ],

  // Load test (normal load)
  stages: [
    { duration: '2m', target: 100 },   // Ramp up to 100 users
    { duration: '5m', target: 100 },   // Stay at 100 users
    { duration: '2m', target: 0 },     // Ramp down to 0
  ],

  // Stress test (find limits)
  // stages: [
  //   { duration: '2m', target: 100 },
  //   { duration: '5m', target: 200 },
  //   { duration: '2m', target: 300 },
  //   { duration: '5m', target: 300 },
  //   { duration: '2m', target: 0 },
  // ],

  thresholds: {
    // 95% of requests must complete within 500ms
    http_req_duration: ['p(95)<500'],

    // Error rate must be below 1%
    errors: ['rate<0.01'],

    // Throughput requirements
    http_reqs: ['count>1000'],
  },

  // Enable HTTP/2
  http: {
    http2: true,
  },
};

// Test data (can be loaded from JSON file)
const testUsers = [
  { email: 'user1@test.com', password: 'password123' },
  { email: 'user2@test.com', password: 'password123' },
  // ... more test users
];

// Setup function (runs once)
export function setup() {
  console.log('Setup: Creating test data...');

  // Create test users if needed
  const adminToken = getAdminToken();

  testUsers.forEach(user => {
    const response = http.post(
      'https://api.example.com/users',
      JSON.stringify(user),
      {
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${adminToken}`,
        },
      }
    );

    check(response, {
      'user created': (r) => r.status === 201,
    });
  });

  return { testUsers };
}

// Main test function
export default function (data) {
  const user = data.testUsers[__VU % data.testUsers.length];

  // Group related requests for better reporting
  group('Authentication Flow', () => {
    // 1. Login
    const loginRes = http.post(
      'https://api.example.com/auth/login',
      JSON.stringify({
        email: user.email,
        password: user.password,
      }),
      {
        headers: { 'Content-Type': 'application/json' },
      }
    );

    // Track metrics
    responseTimeTrend.add(loginRes.timings.duration);
    requestCounter.add(1);

    // Check response
    const loginCheck = check(loginRes, {
      'login status is 200': (r) => r.status === 200,
      'login has token': (r) => r.json('token') !== undefined,
    });

    // Track errors
    if (!loginCheck) {
      errorRate.add(1);
    }

    const authToken = loginRes.json('token');

    // 2. Get user profile (authenticated)
    const profileRes = http.get(
      'https://api.example.com/users/me',
      {
        headers: {
          'Authorization': `Bearer ${authToken}`,
        },
      }
    );

    check(profileRes, {
      'profile status is 200': (r) => r.status === 200,
      'profile has email': (r) => r.json('email') === user.email,
    });

    // Small think time
    sleep(Math.random() * 2 + 1);
  });

  group('Product Browsing', () => {
    // 3. Browse products
    const productsRes = http.get('https://api.example.com/products');

    check(productsRes, {
      'products status is 200': (r) => r.status === 200,
      'products returned': (r) => r.json().length > 0,
    });

    // 4. Get specific product
    const productId = productsRes.json()[0].id;
    const productRes = http.get(`https://api.example.com/products/${productId}`);

    check(productRes, {
      'product status is 200': (r) => r.status === 200,
      'product has details': (r) => r.json('name') !== undefined,
    });

    sleep(Math.random() * 3 + 1);
  });
}

// Teardown function (runs once)
export function teardown(data) {
  console.log('Teardown: Cleaning up test data...');

  // Clean up test users
  const adminToken = getAdminToken();

  data.testUsers.forEach(user => {
    // In real scenario, you'd need to get user ID first
    // This is simplified
    const deleteRes = http.del(
      `https://api.example.com/users?email=${encodeURIComponent(user.email)}`,
      null,
      {
        headers: {
          'Authorization': `Bearer ${adminToken}`,
        },
      }
    );

    console.log(`Deleted user ${user.email}: ${deleteRes.status}`);
  });
}

import { rest } from 'msw';
import { setupServer } from 'msw/node';
import { faker } from '@faker-js/faker';

// Create mock server
const server = setupServer(
  // Mock GET /users
  rest.get('https://api.example.com/users', (req, res, ctx) => {
    const limit = parseInt(req.url.searchParams.get('limit') || '20');
    const offset = parseInt(req.url.searchParams.get('offset') || '0');

    // Generate mock users
    const users = Array.from({ length: limit }, (_, i) => ({
      id: offset + i + 1,
      name: faker.person.fullName(),
      email: faker.internet.email(),
      age: faker.number.int({ min: 18, max: 65 }),
      createdAt: faker.date.past().toISOString(),
    }));

    // Simulate pagination metadata
    const total = 1000;
    const hasMore = offset + limit < total;

    return res(
      ctx.status(200),
      ctx.json({
        data: users,
        pagination: {
          total,
          limit,
          offset,
          hasMore,
        },
      }),
      // Simulate network delay
      ctx.delay(faker.number.int({ min: 50, max: 500 }))
    );
  }),

  // Mock POST /users
  rest.post('https://api.example.com/users', async (req, res, ctx) => {
    const userData = await req.json();

    // Validation logic
    if (!userData.name || !userData.email) {
      return res(
        ctx.status(400),
        ctx.json({
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Name and email are required',
            fields: {
              name: !userData.name ? 'Required' : undefined,
              email: !userData.email ? 'Required' : undefined,
            },
          },
        })
      );
    }

    // Email format validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(userData.email)) {
      return res(
        ctx.status(400),
        ctx.json({
          error: {
            code: 'VALIDATION_ERROR',
            message: 'Invalid email format',
            fields: { email: 'Must be valid email' },
          },
        })
      );
    }

    // Simulate successful creation
    const newUser = {
      id: faker.number.int({ min: 1000, max: 9999 }),
      ...userData,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    return res(
      ctx.status(201),
      ctx.set('Location', `https://api.example.com/users/${newUser.id}`),
      ctx.json(newUser)
    );
  }),

  // Mock GET /users/:id
  rest.get('https://api.example.com/users/:id', (req, res, ctx) => {
    const { id } = req.params;

    // Check if ID is valid
    if (!id || isNaN(parseInt(id))) {
      return res(
        ctx.status(400),
        ctx.json({
          error: {
            code: 'INVALID_ID',
            message: 'Invalid user ID',
          },
        })
      );
    }

    const userId = parseInt(id);

    // Simulate user not found
    if (userId > 1000) {
      return res(
        ctx.status(404),
        ctx.json({
          error: {
            code: 'NOT_FOUND',
            message: `User with ID ${userId} not found`,
          },
        })
      );
    }

    // Return mock user
    return res(
      ctx.status(200),
      ctx.json({
        id: userId,
        name: faker.person.fullName(),
        email: faker.internet.email(),
        age: faker.number.int({ min: 18, max: 65 }),
        address: {
          street: faker.location.streetAddress(),
          city: faker.location.city(),
          country: faker.location.country(),
        },
        createdAt: faker.date.past().toISOString(),
        updatedAt: faker.date.recent().toISOString(),
      })
    );
  }),

  // Mock authentication endpoint
  rest.post('https://api.example.com/auth/login', async (req, res, ctx) => {
    const credentials = await req.json();

    // Check credentials
    if (credentials.email === 'test@example.com' && credentials.password === 'password123') {
      return res(
        ctx.status(200),
        ctx.json({
          token: 'mock_jwt_token_' + faker.string.alphanumeric(32),
          user: {
            id: 1,
            email: 'test@example.com',
            name: 'Test User',
          },
          expiresIn: 3600, // 1 hour
        })
      );
    }

    // Invalid credentials
    return res(
      ctx.status(401),
      ctx.json({
        error: {
          code: 'INVALID_CREDENTIALS',
          message: 'Invalid email or password',
        },
      })
    );
  }),

  // Mock error scenarios
  rest.get('https://api.example.com/error-test', (req, res, ctx) => {
    const errorType = req.url.searchParams.get('type');

    switch (errorType) {
      case '500':
        return res(
          ctx.status(500),
          ctx.json({
            error: {
              code: 'INTERNAL_SERVER_ERROR',
              message: 'Something went wrong on our end',
            },
          })
        );
      case 'timeout':
        return res(ctx.delay(10000)); // 10 second delay
      case 'network':
        return res.networkError('Failed to connect');
      default:
        return res(ctx.status(200), ctx.json({ status: 'ok' }));
    }
  })
);

// Test using the mock server
describe('API Tests with MSW', () => {
  beforeAll(() => server.listen());
  afterEach(() => server.resetHandlers());
  afterAll(() => server.close());

  test('GET /users returns paginated data', async () => {
    const response = await fetch('https://api.example.com/users?limit=10&offset=0');
    const data = await response.json();

    expect(response.status).toBe(200);
    expect(data).toHaveProperty('data');
    expect(data).toHaveProperty('pagination');
    expect(data.data).toHaveLength(10);
    expect(data.pagination).toMatchObject({
      total: 1000,
      limit: 10,
      offset: 0,
      hasMore: true,
    });
  });

  test('POST /users validates required fields', async () => {
    const response = await fetch('https://api.example.com/users', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: 'John' }), // Missing email
    });

    const data = await response.json();

    expect(response.status).toBe(400);
    expect(data.error.code).toBe('VALIDATION_ERROR');
    expect(data.error.fields.email).toBe('Required');
  });

  test('Error endpoint returns appropriate errors', async () => {
    const response = await fetch('https://api.example.com/error-test?type=500');
    const data = await response.json();

    expect(response.status).toBe(500);
    expect(data.error.code).toBe('INTERNAL_SERVER_ERROR');
  });
});

