// Example 1: Dynamic Authentication Header
const crypto = require('crypto-js');

// Generate API signature
const apiKey = pm.environment.get("api_key");
const apiSecret = pm.environment.get("api_secret");
const timestamp = Date.now();
const nonce = Math.random().toString(36).substring(2);

// Create signature string
const signatureString = `${apiKey}${timestamp}${nonce}${pm.request.body}`;
const signature = crypto.HmacSHA256(signatureString, apiSecret).toString(crypto.enc.Hex);

// Set headers
pm.request.headers.add({
  key: "X-API-Key",
  value: apiKey
});
pm.request.headers.add({
  key: "X-Timestamp",
  value: timestamp.toString()
});
pm.request.headers.add({
  key: "X-Nonce",
  value: nonce
});
pm.request.headers.add({
  key: "X-Signature",
  value: signature
});

console.log(`Generated signature for request: ${signature}`);

