// advanced-newman-runner.js
const newman = require('newman');
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);

class NewmanTestRunner {
  constructor(config) {
    this.config = {
      collectionsDir: './collections',
      environmentsDir: './environments',
      reportsDir: './reports',
      ...config
    };

    this.results = [];
    this.startTime = null;
    this.endTime = null;
  }

  async runAllCollections() {
    this.startTime = new Date();
    console.log(`Starting test run at ${this.startTime.toISOString()}`);

    // Get all collection files
    const collectionFiles = fs.readdirSync(this.config.collectionsDir)
      .filter(file => file.endsWith('.postman_collection.json'));

    console.log(`Found ${collectionFiles.length} collections to run`);

    // Run collections in sequence
    for (const collectionFile of collectionFiles) {
      await this.runCollection(collectionFile);
    }

    this.endTime = new Date();
    const duration = (this.endTime - this.startTime) / 1000;

    console.log(`\n=== Test Run Complete ===`);
    console.log(`Duration: ${duration.toFixed(2)} seconds`);
    console.log(`Collections run: ${this.results.length}`);

    // Generate combined report
    await this.generateCombinedReport();

    // Check overall status
    const overallStatus = this.results.every(r => r.summary.run.failures.length === 0)
      ? 'PASS' : 'FAIL';

    console.log(`Overall status: ${overallStatus}`);

    return {
      status: overallStatus,
      results: this.results,
      duration: duration
    };
  }

  async runCollection(collectionFile) {
    const collectionName = path.basename(collectionFile, '.postman_collection.json');
    const collectionPath = path.join(this.config.collectionsDir, collectionFile);

    console.log(`\n=== Running collection: ${collectionName} ===`);

    // Try to find matching environment file
    let environmentPath = null;
    const envFile = `${collectionName}.postman_environment.json`;
    const envPath = path.join(this.config.environmentsDir, envFile);

    if (fs.existsSync(envPath)) {
      environmentPath = envPath;
      console.log(`Using environment: ${envFile}`);
    } else {
      console.log(`No specific environment found, using default`);
    }

    // Prepare Newman options
    const options = {
      collection: require(collectionPath),
      reporters: ['cli'],
      insecure: true,
      timeout: 30000,
      timeoutRequest: 15000,
      timeoutScript: 15000
    };

    if (environmentPath) {
      options.environment = require(environmentPath);
    }

    // Run Newman
    return new Promise((resolve, reject) => {
      newman.run(options, (err, summary) => {
        if (err) {
          console.error(`Error running collection ${collectionName}:`, err);
          reject(err);
          return;
        }

        // Store result
        const result = {
          collection: collectionName,
          summary: summary,
          timestamp: new Date().toISOString(),
          stats: {
            total: summary.run.stats.requests.total,
            failed: summary.run.stats.requests.failed,
            testsTotal: summary.run.stats.tests.total,
            testsFailed: summary.run.stats.tests.failed
          }
        };

        this.results.push(result);

        // Generate individual report
        this.generateCollectionReport(collectionName, summary);

        console.log(`Collection ${collectionName} completed:`);
        console.log(`  Requests: ${result.stats.total} total, ${result.stats.failed} failed`);
        console.log(`  Tests: ${result.stats.testsTotal} total, ${result.stats.testsFailed} failed`);

        resolve(result);
      });
    });
  }

  async generateCollectionReport(collectionName, summary) {
    const reportDir = path.join(this.config.reportsDir, collectionName);

    // Create directory if it doesn't exist
    if (!fs.existsSync(reportDir)) {
      fs.mkdirSync(reportDir, { recursive: true });
    }

    // Save JSON report
    const jsonReport = {
      collection: collectionName,
      timestamp: new Date().toISOString(),
      summary: summary
    };

    await writeFile(
      path.join(reportDir, 'report.json'),
      JSON.stringify(jsonReport, null, 2)
    );

    // Generate HTML report
    const htmlReport = this.generateHTMLReport(collectionName, summary);
    await writeFile(
      path.join(reportDir, 'report.html'),
      htmlReport
    );

    console.log(`Reports saved to ${reportDir}`);
  }

  generateHTMLReport(collectionName, summary) {
    const stats = summary.run.stats;
    const failures = summary.run.failures;

    return `
    <!DOCTYPE html>
    <html>
    <head>
      <title>Test Report - ${collectionName}</title>
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .summary { background: #f5f5f5; padding: 20px; border-radius: 5px; }
        .stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
        .stat { background: white; padding: 15px; border-radius: 3px; text-align: center; }
        .stat .value { font-size: 24px; font-weight: bold; }
        .stat .label { color: #666; }
        .passed { color: green; }
        .failed { color: red; }
        .failures { margin-top: 30px; }
        .failure { background: #ffe6e6; padding: 10px; margin: 5px 0; border-left: 3px solid red; }
      </style>
    </head>
    <body>
      <h1>Test Report: ${collectionName}</h1>
      <p>Generated: ${new Date().toISOString()}</p>

      <div class="summary">
        <h2>Summary</h2>
        <div class="stats">
          <div class="stat">
            <div class="value">${stats.requests.total}</div>
            <div class="label">Total Requests</div>
          </div>
          <div class="stat">
            <div class="value ${stats.requests.failed > 0 ? 'failed' : 'passed'}">${stats.requests.failed}</div>
            <div class="label">Failed Requests</div>
          </div>
          <div class="stat">
            <div class="value">${stats.tests.total}</div>
            <div class="label">Total Tests</div>
          </div>
          <div class="stat">
            <div class="value ${stats.tests.failed > 0 ? 'failed' : 'passed'}">${stats.tests.failed}</div>
            <div class="label">Failed Tests</div>
          </div>
        </div>
      </div>

      ${failures.length > 0 ? `
      <div class="failures">
        <h2>Failures (${failures.length})</h2>
        ${failures.map(failure => `
          <div class="failure">
            <strong>${failure.source.name}</strong><br>
            ${failure.error.message}<br>
            <small>Test: ${failure.error.test}</small>
          </div>
        `).join('')}
      </div>
      ` : '<p>All tests passed! ✅</p>'}
    </body>
    </html>
    `;
  }

  async generateCombinedReport() {
    const combinedReport = {
      timestamp: new Date().toISOString(),
      duration: (this.endTime - this.startTime) / 1000,
      collections: this.results.map(r => ({
        name: r.collection,
        stats: r.stats,
        timestamp: r.timestamp,
        status: r.summary.run.failures.length === 0 ? 'PASS' : 'FAIL'
      })),
      summary: {
        totalCollections: this.results.length,
        passedCollections: this.results.filter(r => r.summary.run.failures.length === 0).length,
        failedCollections: this.results.filter(r => r.summary.run.failures.length > 0).length,
        totalRequests: this.results.reduce((sum, r) => sum + r.stats.total, 0),
        failedRequests: this.results.reduce((sum, r) => sum + r.stats.failed, 0),
        totalTests: this.results.reduce((sum, r) => sum + r.stats.testsTotal, 0),
        failedTests: this.results.reduce((sum, r) => sum + r.stats.testsFailed, 0)
      }
    };

    const reportPath = path.join(this.config.reportsDir, 'combined-report.json');
    await writeFile(reportPath, JSON.stringify(combinedReport, null, 2));

    console.log(`Combined report saved to ${reportPath}`);
  }
}

// Usage example
async function main() {
  const runner = new NewmanTestRunner({
    collectionsDir: './tests/collections',
    environmentsDir: './tests/environments',
    reportsDir: './test-reports'
  });

  try {
    const result = await runner.runAllCollections();

    // Exit with appropriate code
    process.exit(result.status === 'PASS' ? 0 : 1);
  } catch (error) {
    console.error('Test runner failed:', error);
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

