// ===== LOGGING FILTER FOR SENSITIVE DATA =====
public class SanitizedLogFilter implements Filter {
    @Override
    public Response filter(FilterableRequestSpecification requestSpec, 
                          FilterableResponseSpecification responseSpec, 
                          FilterContext ctx) {

        // Clone request to avoid modifying original
        FilterableRequestSpecification sanitizedRequest = cloneRequest(requestSpec);

        // Sanitize sensitive headers
        if (sanitizedRequest.getHeaders() != null) {
            Map<String, String> headers = new HashMap<>(sanitizedRequest.getHeaders().asMap());
            headers.replace("Authorization", "[REDACTED]");
            headers.replace("X-Api-Key", "[REDACTED]");
            sanitizedRequest.headers(headers);
        }

        // Sanitize body if it contains sensitive data
        if (sanitizedRequest.getBody() != null) {
            String body = sanitizedRequest.getBody();
            // Simple example: redact passwords
            body = body.replaceAll("(?i)(\"password\"\s*:\s*\")([^\"]*)(\")", 
                                  "$1[REDACTED]$3");
            sanitizedRequest.body(body);
        }

        // Continue with sanitized request
        Response response = ctx.next(sanitizedRequest, responseSpec);

        // Also sanitize response if needed
        return response;
    }

    private FilterableRequestSpecification cloneRequest(
            FilterableRequestSpecification original) {
        // Implementation depends on REST Assured version
        // This is a simplified example
        return original;
    }
}

