public class ApiSpecifications {

    // Singleton pattern for shared specs
    private static RequestSpecification defaultSpec;
    private static RequestSpecification adminSpec;
    private static RequestSpecification publicSpec;

    public static synchronized RequestSpecification getDefaultSpec() {
        if (defaultSpec == null) {
