// ===== CUSTOM AUTHENTICATION HEADERS =====
public class CustomAuth {

    public static String generateSignature(String method, String path, String body, String secret) {
        String data = method + path + body;
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(secret.getBytes(), "HmacSHA256");
            mac.init(keySpec);
            byte[] signature = mac.doFinal(data.getBytes());
            return Base64.getEncoder().encodeToString(signature);
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate signature", e);
        }
    }
}

@Test
public void testWithHmacSignature() {
    String method = "POST";
    String path = "/api/orders";
    String body = "{\"productId\":123,\"quantity\":2}";
    String secret = System.getenv("API_SECRET");

    String signature = CustomAuth.generateSignature(method, path, body, secret);

    given()
        .header("X-Signature", signature)
        .header("X-Timestamp", String.valueOf(System.currentTimeMillis()))
        .body(body)
    .when()
        .post(path)
    .then()
        .statusCode(201);
}

// ===== OAUTH2 AUTHORIZATION CODE FLOW (SIMULATED) =====
@Test
public void testOAuth2AuthorizationCodeFlow() {
    // This is a simplified simulation - real OAuth2 flows involve browser interaction

    // 1. Get authorization code (in real scenario, this involves user login)
    String authCode = given()
        .redirects().follow(false)  // Don't follow redirects
        .queryParam("response_type", "code")
        .queryParam("client_id", "test-client")
        .queryParam("redirect_uri", "https://callback.example.com")
        .queryParam("scope", "read write")
        .queryParam("state", "random-state")
    .when()
        .get("/oauth/authorize")
    .then()
        .statusCode(302)  // Redirect
        .extract()
        .header("Location")
        .split("code=")[1].split("&")[0];

    // 2. Exchange code for tokens
    Response tokenResponse = given()
        .auth().preemptive().basic("test-client", "client-secret")
        .formParam("grant_type", "authorization_code")
        .formParam("code", authCode)
        .formParam("redirect_uri", "https://callback.example.com")
    .when()
        .post("/oauth/token")
    .then()
        .statusCode(200)
        .extract()
        .response();

    String accessToken = tokenResponse.jsonPath().getString("access_token");
    String refreshToken = tokenResponse.jsonPath().getString("refresh_token");

    // 3. Use access token
    given()
        .auth().oauth2(accessToken)
    .when()
        .get("/api/user")
    .then()
        .statusCode(200);

    // 4. Test token refresh
    given()
        .auth().preemptive().basic("test-client", "client-secret")
        .formParam("grant_type", "refresh_token")
        .formParam("refresh_token", refreshToken)
    .when()
        .post("/oauth/token")
    .then()
        .statusCode(200);
}

// ===== MULTI-TENANT AUTHENTICATION =====
public class MultiTenantAuth {

    public static RequestSpecification getTenantSpec(String tenantId) {
        String tenantToken = getTenantToken(tenantId);

        return new RequestSpecBuilder()
            .addHeader("Authorization", "Bearer " + tenantToken)
            .addHeader("X-Tenant-ID", tenantId)
            .build();
    }

    private static String getTenantToken(String tenantId) {
        // Retrieve or generate token for tenant
        // Could be from cache, database, or external service
        return "tenant-token-" + tenantId;
    }
}

@TestFactory
public Stream<DynamicTest> testMultiTenantAccess() {
    List<String> tenantIds = Arrays.asList("tenant-a", "tenant-b", "tenant-c");

    return tenantIds.stream()
        .map(tenantId -> DynamicTest.dynamicTest(
            "Test access for tenant: " + tenantId,
            () -> {
                given()
                    .spec(MultiTenantAuth.getTenantSpec(tenantId))
                .when()
                    .get("/api/tenant-data")
                .then()
                    .statusCode(200)
                    .body("tenantId", equalTo(tenantId));
            }
        ));
}

// ===== AUTHENTICATION TEST MATRIX =====
@ParameterizedTest
@MethodSource("authCombinations")
public void testAuthenticationMatrix(
        String authMethod, 
        String credentials, 
        int expectedStatus,
        String expectedError) {

    RequestSpecification spec = given()
        .spec(ApiSpecifications.getDefaultSpec());

    switch (authMethod) {
        case "basic" -> spec.auth().basic(credentials.split(":")[0], 
                                         credentials.split(":")[1]);
        case "bearer" -> spec.auth().oauth2(credentials);
        case "apikey" -> spec.header("X-API-Key", credentials);
        case "none" -> { /* No authentication */ }
    }

    ValidatableResponse response = spec
    .when()
        .get("/api/protected")
    .then()
        .statusCode(expectedStatus);

    if (expectedStatus >= 400) {
        response.body("error", equalTo(expectedError));
    }
}

private static Stream<Arguments> authCombinations() {
    return Stream.of(
        // Valid scenarios
        Arguments.of("basic", "admin:admin123", 200, null),
        Arguments.of("bearer", "valid-jwt-token", 200, null),
        Arguments.of("apikey", "valid-api-key", 200, null),

        // Invalid scenarios
        Arguments.of("basic", "wrong:wrong", 401, "Unauthorized"),
        Arguments.of("bearer", "expired-token", 401, "Invalid token"),
        Arguments.of("apikey", "invalid-key", 403, "Forbidden"),
        Arguments.of("none", "", 401, "Missing authentication")
    );
}

