import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

public class GraphQLTests {

    private static final String GRAPHQL_ENDPOINT = "/graphql";

    // Utility method to build GraphQL request
    private Map<String, Object> buildGraphQLRequest(String query, Map<String, Object> variables) {
        Map<String, Object> request = new HashMap<>();
        request.put("query", query);
        if (variables != null && !variables.isEmpty()) {
            request.put("variables", variables);
        }
        return request;
    }

    @Test
    public void testBasicGraphQLQuery() {
        String graphqlQuery = """
            query GetUser($userId: ID!) {
              user(id: $userId) {
                id
                name
                email
                posts {
                  id
                  title
                }
              }
            }
            """;

        Map<String, Object> variables = Map.of("userId", 123);
        Map<String, Object> requestBody = buildGraphQLRequest(graphqlQuery, variables);

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user.id", equalTo(123))
            .body("data.user.name", notNullValue())
            .body("data.user.email", matchesPattern(".+@.+\\..+"))
            .body("data.user.posts", hasSize(greaterThan(0)));
    }

    @Test
    public void testGraphQLErrorHandling() {
        String invalidQuery = """
            query {
              user(id: "invalid") {
                id
                name
                invalidField
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(invalidQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200) // GraphQL typically returns 200 even for errors
            .body("errors", notNullValue())
            .body("errors[0].message", containsString("invalidField"))
            .body("errors[0].locations", not(empty()))
            .body("errors[0].path", not(empty()));
    }

    @Test
    public void testGraphQLMutation() {
        String mutation = """
            mutation CreatePost($input: CreatePostInput!) {
              createPost(input: $input) {
                id
                title
                content
                author {
                  id
                  name
                }
              }
            }
            """;

        Map<String, Object> input = Map.of(
            "title", "Test Post",
            "content", "This is a test post",
            "authorId", 123
        );

        Map<String, Object> variables = Map.of("input", input);

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(mutation, variables))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.createPost.id", notNullValue())
            .body("data.createPost.title", equalTo("Test Post"))
            .body("data.createPost.author.id", equalTo(123));
    }

    @Test
    public void testQueryComplexityLimiting() {
        // Try to query deeply nested data
        String complexQuery = """
            query {
              users(first: 10) {
                edges {
                  node {
                    id
                    posts(first: 10) {
                      edges {
                        node {
                          id
                          comments(first: 10) {
                            edges {
                              node {
                                id
                                author {
                                  id
                                  posts(first: 10) {
                                    edges {
                                      node {
                                        id
                                        # Deep nesting continues...
                                      }
                                    }
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(complexQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("complexity"));
    }

    @Test
    public void testAuthenticationAndAuthorization() {
        String adminQuery = """
            query {
              adminStats {
                totalUsers
                activeUsers
                revenue
              }
            }
            """;

        // Test without authentication
        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("authenticate"));

        // Test with regular user token
        given()
            .contentType(ContentType.JSON)
            .header("Authorization", "Bearer user-token")
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", not(empty()))
            .body("errors[0].message", containsStringIgnoringCase("permission"));

        // Test with admin token
        given()
            .contentType(ContentType.JSON)
            .header("Authorization", "Bearer admin-token")
            .body(buildGraphQLRequest(adminQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("errors", nullValue())
            .body("data.adminStats", notNullValue());
    }

    @Test
    public void testIntrospectionQuery() {
        String introspectionQuery = """
            query IntrospectionQuery {
              __schema {
                queryType { name }
                mutationType { name }
                subscriptionType { name }
                types {
                  name
                  kind
                  description
                  fields {
                    name
                    type { name kind }
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(introspectionQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.__schema.queryType.name", equalTo("Query"))
            .body("data.__schema.types", hasSize(greaterThan(0)));
    }

    @Test
    public void testBatchQueries() {
        String batchQuery = """
            query BatchQuery($userId1: ID!, $userId2: ID!) {
              user1: user(id: $userId1) {
                id
                name
              }
              user2: user(id: $userId2) {
                id
                name
                email
              }
            }
            """;

        Map<String, Object> variables = Map.of(
            "userId1", 123,
            "userId2", 456
        );

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(batchQuery, variables))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user1.id", equalTo(123))
            .body("data.user2.id", equalTo(456))
            .body("data.user1.name", notNullValue())
            .body("data.user2.name", notNullValue());
    }

    @Test
    public void testNullHandlingAndOptionalFields() {
        String queryWithOptionalFields = """
            query {
              user(id: 999) {  # Non-existent user
                id
                name
                optionalField
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(queryWithOptionalFields, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .body("data.user", nullValue())  // User might be null
            .body("errors", nullValue());     // No errors for null data
    }

    @Test
    public void testPerformanceWithResponseTime() {
        String simpleQuery = """
            query {
              users(first: 5) {
                edges {
                  node {
                    id
                    name
                  }
                }
              }
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(buildGraphQLRequest(simpleQuery, null))
        .when()
            .post(GRAPHQL_ENDPOINT)
        .then()
            .statusCode(200)
            .time(lessThan(1000L))  // Response time should be < 1 second
            .body("data.users.edges", hasSize(lessThanOrEqualTo(5)));
    }
}

import com.fasterxml.jackson.databind.ObjectMapper;
import io.restassured.response.Response;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;

import static io.restassured.RestAssured.given;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.*;

public class AdvancedGraphQLTestingFramework {

    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final String TEST_DATA_DIR = "src/test/resources/graphql/";

    // GraphQL Client Utility
    public static class GraphQLClient {

        public static Response executeQuery(String query, Map<String, Object> variables) {
            return execute(query, variables, null);
        }

        public static Response executeMutation(String mutation, Map<String, Object> variables) {
            return execute(mutation, variables, null);
        }

        public static Response execute(String operation, 
                                      Map<String, Object> variables,
                                      Map<String, String> headers) {

            Map<String, Object> requestBody = Map.of(
                "query", operation,
                "variables", variables != null ? variables : Map.of()
            );

            var request = given()
                .contentType(ContentType.JSON)
                .body(requestBody);

            if (headers != null) {
                headers.forEach(request::header);
            }

            return request.post("/graphql");
        }

        public static Map<String, Object> extractData(Response response) {
            return response.jsonPath().getMap("data");
        }

        public static List<Map<String, Object>> extractErrors(Response response) {
            return response.jsonPath().getList("errors");
        }
    }

    // Schema Validator
    public static class SchemaValidator {

        public static void validateFieldExists(String typeName, String fieldName) {
            String introspectionQuery = String.format("""
                {
                  __type(name: \"%s\") {
                    fields {
                      name
                    }
                  }
                }
                """, typeName);

            Response response = GraphQLClient.executeQuery(introspectionQuery, null);
            List<String> fieldNames = response.jsonPath()
                .getList("data.__type.fields.name");

            assertThat("Field " + fieldName + " should exist in type " + typeName,
                fieldNames, hasItem(fieldName));
        }

        public static void validateTypeKind(String typeName, String expectedKind) {
            String query = String.format("""
                {
                  __type(name: \"%s\") {
                    kind
                  }
                }
                """, typeName);

            Response response = GraphQLClient.executeQuery(query, null);
            String actualKind = response.jsonPath().getString("data.__type.kind");

            assertThat(actualKind, equalTo(expectedKind));
        }
    }

    // Query Loader from Files
    public static class QueryLoader {

        public static String loadQuery(String fileName) throws IOException {
            return Files.readString(Paths.get(TEST_DATA_DIR + fileName + ".graphql"));
        }

        public static Map<String, Object> loadVariables(String fileName) throws IOException {
            return objectMapper.readValue(
                new File(TEST_DATA_DIR + fileName + ".json"),
                Map.class
            );
        }
    }

    // Test Examples
    @Test
    public void testSchemaConsistency() {
        SchemaValidator.validateFieldExists("User", "email");
        SchemaValidator.validateFieldExists("User", "posts");
        SchemaValidator.validateTypeKind("User", "OBJECT");
        SchemaValidator.validateTypeKind("UserRole", "ENUM");
    }

    @Test
    public void testFromFile() throws IOException {
        String query = QueryLoader.loadQuery("get-user-with-posts");
        Map<String, Object> variables = QueryLoader.loadVariables("user-variables");

        Response response = GraphQLClient.executeQuery(query, variables);

        assertThat(response.statusCode(), is(200));
        assertThat(GraphQLClient.extractErrors(response), empty());

        Map<String, Object> data = GraphQLClient.extractData(response);
        assertThat(data, hasKey("user"));
    }

    @ParameterizedTest
    @MethodSource("provideInvalidQueries")
    public void testInvalidQueries(String invalidQuery) {
        Response response = GraphQLClient.executeQuery(invalidQuery, null);

        assertThat(response.statusCode(), is(200));
        List<Map<String, Object>> errors = GraphQLClient.extractErrors(response);
        assertThat(errors, not(empty()));

        // All errors should have a message
        errors.forEach(error -> {
            assertThat(error, hasKey("message"));
            assertThat(error.get("message"), not(emptyOrNullString()));
        });
    }

    private static Stream<String> provideInvalidQueries() {
        return Stream.of(
            "query { invalidField }",
            "query { user(id: \"invalid\") { invalidField } }",
            "",  // Empty query
            "not a valid graphql query",
            "query { user(id: 123) { id name } user(id: 456) { id name } }"  // Duplicate field
        );
    }

    @Test
    public void testPerformanceBenchmark() {
        String query = """
            query {
              users(first: 100) {
                edges {
                  node {
                    id
                    name
                    email
                    posts(first: 10) {
                      edges {
                        node {
                          id
                          title
                        }
                      }
                    }
                  }
                }
              }
            }
            """;

        long startTime = System.currentTimeMillis();

        Response response = GraphQLClient.executeQuery(query, null);

        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;

        assertThat(response.statusCode(), is(200));

        // Performance assertions
        assertThat("Query should complete within 5 seconds", duration, lessThan(5000L));

        // Also check response size isn't too large
        String responseBody = response.getBody().asString();
        assertThat("Response size should be reasonable", 
            responseBody.length(), lessThan(100000));  // Less than 100KB
    }

    @Test
    public void testDataConsistency() {
        // Test that same query returns consistent results
        String query = """
            query {
              user(id: 1) {
                id
                name
                email
              }
            }
            """;

        Response response1 = GraphQLClient.executeQuery(query, null);
        Response response2 = GraphQLClient.executeQuery(query, null);

        Map<String, Object> data1 = GraphQLClient.extractData(response1);
        Map<String, Object> data2 = GraphQLClient.extractData(response2);

        // Data should be the same (assuming no updates between requests)
        assertThat(data1, equalTo(data2));
    }
}

