import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

// Custom metric for error rate
const errorRate = new Rate('errors');

// Test configuration
export let options = {
  stages: [
    { duration: '30s', target: 10 },  // Ramp up
    { duration: '1m', target: 50 },   // Stay at load
    { duration: '30s', target: 0 },   // Ramp down
  ],
  thresholds: {
    'http_req_duration': ['p(95)<500'],  // 95% under 500ms
    'errors': ['rate<0.01'],             // Error rate < 1%
  },
};

// GraphQL query
export default function() {
  const query = `
    query GetProducts($category: String!) {
      products(category: $category, first: 10) {
        edges {
          node {
            id
            name
            price
            category
          }
        }
      }
    }
  `;

  const variables = {
    category: 'electronics'
  };

  const payload = JSON.stringify({
    query: query,
    variables: variables
  });

  const headers = {
    'Content-Type': 'application/json',
    'Authorization': 'Bearer test-token'
  };

  const response = http.post('http://localhost:8080/graphql', payload, { headers: headers });

  // Validate response
  const success = check(response, {
    'status is 200': (r) => r.status === 200,
    'response has data': (r) => r.json('data') !== null,
    'no errors in response': (r) => r.json('errors') === null,
    'has products': (r) => r.json('data.products.edges.length') > 0
  });

  // Record error if any check failed
  errorRate.add(!success);

  sleep(1);
}

