                .headers(headers)
            .willRespondWith()
                .status(200)
                .headers(headers)
                .body(
                    new PactDslJsonBody()
                        .uuid("id", "123e4567-e89b-12d3-a456-426614174000")
                        .stringType("name", "Wireless Headphones")
                        .stringType("description", "Noise-cancelling wireless headphones")
                        .decimalType("price", 129.99)  // Type matching, not exact value
                        .stringType("category", "electronics")
