        headers.put("Content-Type", "application/json");

        return builder
            .given("products exist in electronics category")
            .uponReceiving("a request for electronics products with pagination")
                .path("/products")
                .method("GET")
                .query("category=electronics&page=1&size=10")
                .headers(headers)
            .willRespondWith()
                .status(200)
                .headers(headers)
                .body(
                    new PactDslJsonBody()
                        .minArrayLike("products", 1, 
                            new PactDslJsonBody()
                                .uuid("id")
                                .stringType("name")
                                .decimalType("price")
                                .stringType("category", "electronics")
                                .booleanType("inStock")
                        )
                        .integerType("total", 50)
                        .integerType("page", 1)
                        .integerType("size", 10)
                )
            .toPact();
    }

    @Pact(provider = PROVIDER_NAME, consumer = CONSUMER_NAME)
    public RequestResponsePact createPactForProductNotFound(PactDslWithProvider builder) {
        Map<String, String> headers = new HashMap<>();
        headers.put("Content-Type", "application/json");

        return builder
            .given("product with ID 999 does not exist")
            .uponReceiving("a request for non-existent product")
                .path("/products/999")
                .method("GET")
                .headers(headers)
            .willRespondWith()
                .status(404)
                .headers(headers)
                .body(
                    new PactDslJsonBody()
                        .stringType("code", "PRODUCT_NOT_FOUND")
                        .stringType("message", "Product not found")
                        .datetime("timestamp", "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'")
                )
            .toPact();
    }

    @Test
    @PactTestFor(pactMethod = "createPactForGetProduct")
    public void testGetProductById(MockServer mockServer) throws Exception {
        // Set up request
        String url = mockServer.getUrl() + "/products/123e4567-e89b-12d3-a456-426614174000";
        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer valid-token");
        HttpEntity<String> entity = new HttpEntity<>(headers);

        // Make request to mock server
        ResponseEntity<String> response = restTemplate.exchange(
            url, HttpMethod.GET, entity, String.class
        );

        // Verify response
        assertEquals(200, response.getStatusCodeValue());
        assertNotNull(response.getBody());

        // Parse and validate response
        Map<String, Object> product = objectMapper.readValue(response.getBody(), Map.class);

        assertNotNull(product.get("id"));
        assertNotNull(product.get("name"));
        assertNotNull(product.get("price"));
        assertEquals("electronics", product.get("category"));
        assertNotNull(product.get("inStock"));
        assertNotNull(product.get("tags"));
        assertTrue(((List<?>) product.get("tags")).size() >= 1);

        // Type validations
        assertTrue(product.get("price") instanceof Number);
        assertTrue(product.get("inStock") instanceof Boolean);
    }

    @Test
    @PactTestFor(pactMethod = "createPactForGetProducts")
    public void testGetProductsWithPagination(MockServer mockServer) throws Exception {
        String url = mockServer.getUrl() + "/products?category=electronics&page=1&size=10";

        ResponseEntity<String> response = restTemplate.getForEntity(url, String.class);

        assertEquals(200, response.getStatusCodeValue());

        Map<String, Object> result = objectMapper.readValue(response.getBody(), Map.class);

        assertNotNull(result.get("products"));
