import javax.xml.ws.Service;
import javax.xml.namespace.QName;
import java.net.URL;
import javax.xml.ws.BindingProvider;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;

public class ProductServiceSOAPTest {

    // Test with JAX-WS generated client
    public void testGetProduct() throws Exception {
        // URL to WSDL
        URL wsdlUrl = new URL("http://localhost:8080/ProductService?wsdl");

        // QName for service
        QName serviceName = new QName(
            "http://www.example.com/products", 
            "ProductService"
        );

        // Create service
        Service service = Service.create(wsdlUrl, serviceName);

        // Get port (proxy)
        ProductService port = service.getPort(ProductService.class);

        // Set endpoint address (if different from WSDL)
        BindingProvider bp = (BindingProvider) port;
        Map<String, Object> context = bp.getRequestContext();
        context.put(BindingProvider.ENDPOINT_ADDRESS_PROPERTY, 
                   "http://localhost:8080/ProductService");

        // Set timeout
        context.put("com.sun.xml.internal.ws.request.timeout", 5000); // 5 seconds
        context.put("com.sun.xml.internal.ws.connect.timeout", 5000);

        // Prepare request
        GetProductRequest request = new GetProductRequest();
        request.setProductId("PROD-12345");
        request.setIncludeDetails(true);

        // Execute SOAP call
        long startTime = System.currentTimeMillis();
        GetProductResponse response = port.getProduct(request);
        long duration = System.currentTimeMillis() - startTime;

        // Validate response
        assert response != null : "Response should not be null";
        assert response.getProduct() != null : "Product should not be null";

        Product product = response.getProduct();

        // Assertions
        assert "PROD-12345".equals(product.getProductId()) : 
               "Product ID should match";
        assert product.getPrice() > 0 : "Price should be positive";
        assert product.getName() != null && !product.getName().isEmpty() : 
               "Product name should not be empty";

        // Performance assertion
        assert duration < 1000 : "Response time should be under 1 second: " + duration + "ms";

        System.out.println("Test passed in " + duration + "ms");
        System.out.println("Product: " + product.getName() + ", Price: $" + product.getPrice());
    }

    // Data-driven test example
    public void testMultipleProducts() {
        List<String> productIds = List.of("PROD-12345", "PROD-67890", "PROD-11111");
        List<TestResult> results = new ArrayList<>();

        for (String productId : productIds) {
            try {
                GetProductRequest request = new GetProductRequest();
                request.setProductId(productId);

                GetProductResponse response = port.getProduct(request);

                results.add(new TestResult(productId, true, "Success"));
            } catch (Exception e) {
                results.add(new TestResult(productId, false, e.getMessage()));
            }
        }

        // Generate report
        long passed = results.stream().filter(TestResult::isSuccess).count();
        System.out.println("Passed: " + passed + "/" + results.size());
    }

    // Test error scenarios
    public void testInvalidProduct() {
        try {
            GetProductRequest request = new GetProductRequest();
            request.setProductId("INVALID-ID");

            GetProductResponse response = port.getProduct(request);

            // Should not reach here - expecting exception
            assert false : "Should have thrown exception for invalid product ID";
        } catch (ProductNotFoundException e) {
            // Expected exception
            assert e.getFaultCode().equals("PRODUCT_NOT_FOUND") : 
                   "Should have PRODUCT_NOT_FOUND fault code";
            System.out.println("Correctly handled invalid product: " + e.getMessage());
        }
    }
}

// Helper classes
class TestResult {
    private String testId;
    private boolean success;
    private String message;

    public TestResult(String testId, boolean success, String message) {
        this.testId = testId;
        this.success = success;
        this.message = message;
    }

    public boolean isSuccess() { return success; }
    public String getMessage() { return message; }
}

