        String password = "Password123!";

        ValidationResult result = validator.validateUserRegistration(email, password);

        assertTrue(result.isSuccess(), "User registration should succeed");
        assertNotNull(result.getUserId(), "User ID should be generated");

        // Cleanup
        if (result.getUserId() != null) {
            userService.deleteUserIfExists(result.getUserId());
        }
    }

    @Test
    public void testRegisterDuplicateUser() {
        String email = "duplicate@example.com";
        String password = "Password123!";

        // First registration should succeed
        ValidationResult firstResult = validator.validateUserRegistration(email, password);
        assertTrue(firstResult.isSuccess(), "First registration should succeed");

        // Second registration should fail
        ValidationResult secondResult = validator.validateUserRegistration(email, password);
        assertFalse(secondResult.isSuccess(), "Duplicate registration should fail");
        assertTrue(secondResult.getErrorMessage().contains("duplicate") || 
                   secondResult.getErrorMessage().contains("409"),
