package com.company.api.tests;

import com.company.api.factories.TestDataFactory;
import com.company.api.models.User;
import com.company.api.models.Order;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class FactoryPatternTests {

    @Test
    public void testUserCreationWithFactory() {
        // Using factory methods
        User basicUser = TestDataFactory.createBasicUser();
        User adminUser = TestDataFactory.createAdminUser();
        User inactiveUser = TestDataFactory.createInactiveUser();

        // Assertions
        assertTrue(basicUser.isActive());
        assertTrue(adminUser.getRoles().contains("ADMIN"));
        assertFalse(inactiveUser.isActive());
    }

    @Test
    public void testOrderCreationWithFactory() {
        // Different order types
        Order simpleOrder = TestDataFactory.createSimpleOrder();
        Order largeOrder = TestDataFactory.createLargeOrder();
        Order discountedOrder = TestDataFactory.createOrderWithDiscount("SAVE10", 10.0);

        assertEquals(1, simpleOrder.getItems().size());
        assertEquals(2, largeOrder.getItems().size());
        assertEquals(89.99, discountedOrder.getTotalAmount()); // 99.99 - 10.0
    }

    @Test
    public void testUserRequestWithBuilder() {
        // Using builder for complex object creation
        UserRequest request = new TestDataFactory.UserRequestBuilder()
            .withEmail("builder.user@example.com")
            .withPassword("SecurePass123!")
            .withName("Builder", "User")
            .withContactInfo("+1234567890", "123 Test St, Test City")
            .withWelcomeEmail(false)
            .withRole("USER")
            .withRole("PREMIUM")
            .build();

        // Assertions
        assertEquals("builder.user@example.com", request.getEmail());
        assertEquals(2, request.getRoles().size());
        assertFalse(request.isSendWelcomeEmail());
    }

    @Test
    public void testAbstractFactoryPattern() {
        // Environment-specific factories
        TestDataFactoryAbstract prodFactory = new TestDataFactory.ProductionDataFactory();
        TestDataFactoryAbstract testFactory = new TestDataFactory.TestDataFactoryImpl();

        // Production data
        User prodUser = prodFactory.createUser();
        Order prodOrder = prodFactory.createOrder();

        // Test data
        User testUser = testFactory.createUser();
        Order testOrder = testFactory.createOrder();

        // Verify different characteristics
        assertTrue(prodUser.getEmail().endsWith("@company.com"));
        assertTrue(testUser.getEmail().contains("@example.com"));

        assertEquals("USD", prodOrder.getCurrency());
        assertNull(testOrder.getCurrency()); // Test orders might not have currency
    }
}

// TEST DATA MANAGER
package com.company.api.testdata;

import com.company.api.models.*;
import com.github.javafaker.Faker;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class TestDataManager {

    private static TestDataManager instance;
    private final Faker faker;
    private final Map<String, Object> dataRegistry;
    private final TestDataCache cache;

    private TestDataManager() {
        this.faker = new Faker();
        this.dataRegistry = new ConcurrentHashMap<>();
        this.cache = new TestDataCache();
    }

    public static synchronized TestDataManager getInstance() {
        if (instance == null) {
            instance = new TestDataManager();
        }
        return instance;
    }

    // User Data Management
    public User createUser() {
        User user = User.builder()
            .id(generateId())
            .email(faker.internet().emailAddress())
            .firstName(faker.name().firstName())
            .lastName(faker.name().lastName())
            .phone(faker.phoneNumber().phoneNumber())
            .active(true)
            .createdAt(new Date())
            .build();

        registerData("user_" + user.getId(), user);
        return user;
    }

    public User createUserWithProfile(UserProfile profile) {
        User user = createUser();
        user.setProfile(profile);
        return user;
    }

    public List<User> createUsers(int count) {
        List<User> users = new ArrayList<>();
        for (int i = 0; i < count; i++) {
            users.add(createUser());
        }
        return users;
    }

    // Order Data Management
    public Order createOrder(String userId) {
        Order order = Order.builder()
            .id(generateId())
            .userId(userId)
            .status("PENDING")
            .totalAmount(faker.number().randomDouble(2, 10, 1000))
            .createdAt(new Date())
            .items(createOrderItems(1, 5))
            .build();

        registerData("order_" + order.getId(), order);
        return order;
    }

    public Order createOrderWithUser() {
        User user = createUser();
        return createOrder(user.getId());
    }

    // Product Data Management
    public Product createProduct() {
        Product product = Product.builder()
            .id(generateId())
            .sku("SKU-" + faker.regexify("[A-Z0-9]{8}"))
            .name(faker.commerce().productName())
            .description(faker.lorem().paragraph())
            .price(faker.number().randomDouble(2, 1, 1000))
            .category(faker.commerce().department())
            .inStock(faker.bool().bool())
            .build();

        registerData("product_" + product.getId(), product);
        return product;
    }

    // Test Data Cleanup
    public void cleanupAllData() {
        dataRegistry.clear();
        cache.clear();
    }

    public void cleanupUserData(String userId) {
        dataRegistry.entrySet().removeIf(entry -> 
            entry.getKey().startsWith("user_") && 
            entry.getValue() instanceof User && 
            ((User) entry.getValue()).getId().equals(userId)
        );
    }

    // Data Retrieval
    public <T> T getData(String key, Class<T> type) {
        Object data = dataRegistry.get(key);
        if (data != null && type.isInstance(data)) {
            return type.cast(data);
        }
        return null;
    }

    public List<User> getAllUsers() {
        return dataRegistry.entrySet().stream()
            .filter(entry -> entry.getKey().startsWith("user_"))
            .map(entry -> (User) entry.getValue())
            .collect(Collectors.toList());
    }

    // Data Validation
    public boolean validateUser(User user) {
        if (user == null) return false;
        if (user.getEmail() == null || !user.getEmail().contains("@")) return false;
        if (user.getFirstName() == null || user.getFirstName().trim().isEmpty()) return false;
        if (user.getLastName() == null || user.getLastName().trim().isEmpty()) return false;
        return true;
    }

    // Helper Methods
    private String generateId() {
        return UUID.randomUUID().toString();
    }

    private void registerData(String key, Object data) {
        dataRegistry.put(key, data);
    }

    private List<OrderItem> createOrderItems(int min, int max) {
        int count = faker.number().numberBetween(min, max);
        List<OrderItem> items = new ArrayList<>();

        for (int i = 0; i < count; i++) {
            Product product = createProduct();
            OrderItem item = OrderItem.builder()
                .productId(product.getId())
                .productName(product.getName())
                .quantity(faker.number().numberBetween(1, 10))
                .unitPrice(product.getPrice())
                .build();
            items.add(item);
        }

        return items;
    }
}

// TEST DATA CACHE FOR PERFORMANCE
class TestDataCache {
    private final Map<String, Object> cache;
    private final long defaultTtl = 300000; // 5 minutes

    public TestDataCache() {
        this.cache = new ConcurrentHashMap<>();
    }

    public void put(String key, Object value) {
        put(key, value, defaultTtl);
    }

    public void put(String key, Object value, long ttlMillis) {
        CacheEntry entry = new CacheEntry(value, System.currentTimeMillis() + ttlMillis);
        cache.put(key, entry);
    }

    public Object get(String key) {
        CacheEntry entry = (CacheEntry) cache.get(key);
        if (entry == null) return null;

        if (entry.isExpired()) {
            cache.remove(key);
            return null;
        }

        return entry.getValue();
    }

    public void clear() {
        cache.clear();
    }

    public void cleanupExpired() {
        cache.entrySet().removeIf(entry -> 
            ((CacheEntry) entry.getValue()).isExpired()
        );
    }

    private static class CacheEntry {
        private final Object value;
        private final long expiryTime;

        public CacheEntry(Object value, long expiryTime) {
            this.value = value;
            this.expiryTime = expiryTime;
        }

        public Object getValue() {
            return value;
        }

        public boolean isExpired() {
            return System.currentTimeMillis() > expiryTime;
        }
    }
}

