@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public class TestDataManagementTests {

    private TestDataManager dataManager;
    private List<String> createdUserIds;

    @BeforeAll
    public void setup() {
        dataManager = TestDataManager.getInstance();
        createdUserIds = new ArrayList<>();
    }

    @AfterAll
    public void cleanup() {
        // Cleanup all test data
        for (String userId : createdUserIds) {
            dataManager.cleanupUserData(userId);
        }
    }

    @Test
    public void testCreateUserWithTestDataManager() {
        // Create user using data manager
        User user = dataManager.createUser();
        createdUserIds.add(user.getId());

        // Validate user
        assertTrue(dataManager.validateUser(user));
        assertNotNull(user.getEmail());
        assertNotNull(user.getFirstName());
        assertNotNull(user.getLastName());
    }

    @Test
    public void testCreateMultipleUsers() {
        // Create multiple users
        List<User> users = dataManager.createUsers(5);
        users.forEach(user -> createdUserIds.add(user.getId()));

        assertEquals(5, users.size());

        // Verify all users are unique
        Set<String> emails = users.stream()
            .map(User::getEmail)
            .collect(Collectors.toSet());
        assertEquals(5, emails.size());
    }

    @Test
    public void testCreateOrderWithUser() {
        // Create order with associated user
        Order order = dataManager.createOrderWithUser();
        User user = dataManager.getData("user_" + order.getUserId(), User.class);

        createdUserIds.add(order.getUserId());

        assertNotNull(order);
        assertNotNull(user);
        assertEquals(order.getUserId(), user.getId());
        assertTrue(order.getTotalAmount() > 0);
        assertFalse(order.getItems().isEmpty());
    }

    @Test
    public void testDataCleanup() {
        // Create test data
        User user1 = dataManager.createUser();
        User user2 = dataManager.createUser();

        // Verify data exists
        assertNotNull(dataManager.getData("user_" + user1.getId(), User.class));
        assertNotNull(dataManager.getData("user_" + user2.getId(), User.class));

        // Cleanup specific user
        dataManager.cleanupUserData(user1.getId());

        // Verify cleanup
        assertNull(dataManager.getData("user_" + user1.getId(), User.class));
        assertNotNull(dataManager.getData("user_" + user2.getId(), User.class));

        // Cleanup remaining
        dataManager.cleanupUserData(user2.getId());
    }
