// k6 performance test script for e-commerce platform
import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Rate, Trend } from 'k6/metrics';
import { htmlReport } from 'https://raw.githubusercontent.com/benc-uk/k6-reporter/main/dist/bundle.js';

// Custom metrics
export let errorRate = new Rate('errors');
export let searchResponseTime = new Trend('search_response_time');
export let cartResponseTime = new Trend('cart_response_time');
export let checkoutResponseTime = new Trend('checkout_response_time');

// Test configuration
export let options = {
  stages: [
    // Ramp-up to normal load
    { duration: '5m', target: 1000 }, // 0 to 1000 users over 5 minutes
    { duration: '30m', target: 1000 }, // Stay at 1000 users for 30 minutes

    // Spike testing phase
    { duration: '2m', target: 5000 }, // Spike to 5000 users in 2 minutes
    { duration: '10m', target: 5000 }, // Stay at spike level for 10 minutes

    // Ramp-down
    { duration: '5m', target: 0 }, // Ramp down to 0
  ],

  // Thresholds (SLA requirements)
  thresholds: {
    'http_req_duration': ['p(95)<2000'], // 95% of requests under 2 seconds
    'http_req_failed': ['rate<0.01'], // Error rate less than 1%
    'errors': ['rate<0.1'], // Custom error rate threshold
  },

  // Discard response bodies to save memory
  discardResponseBodies: true,
};

// Test data (in production, use external files or APIs)
const products = [
  { id: 'PROD-001', name: 'Wireless Headphones', category: 'electronics' },
  { id: 'PROD-002', name: 'Running Shoes', category: 'sports' },
  { id: 'PROD-003', name: 'Coffee Maker', category: 'home' },
  // Add more products as needed
];

const users = [
  { email: 'user1@test.com', password: 'password123' },
  { email: 'user2@test.com', password: 'password123' },
  // Add more users as needed
];

// Setup function (runs once at beginning)
export function setup() {
  console.log('Setting up test data...');

  // In a real scenario, you might:
  // 1. Create test users via API
  // 2. Generate test products
  // 3. Set up test database

  return {
    baseUrl: __ENV.BASE_URL || 'https://api.ecommerce.example.com',
    authToken: null,
    testStartTime: new Date().toISOString(),
  };
}

// Main test function
export default function (data) {
  const { baseUrl } = data;

  // Simulate different user behaviors based on virtual user ID
  const userId = __VU % 4;

  switch (userId) {
    case 0:
      simulateBrowsingUser(baseUrl);
      break;
    case 1:
      simulateSearchingUser(baseUrl);
      break;
    case 2:
      simulateShoppingUser(baseUrl);
      break;
    case 3:
      simulateCheckoutUser(baseUrl);
      break;
  }

  // Think time between actions
  sleep(Math.random() * 3 + 1); // 1-4 seconds
}

// User behavior simulations
function simulateBrowsingUser(baseUrl) {
  group('Browsing User', function () {
    // Browse homepage
    let res = http.get(`${baseUrl}/api/home`);
    check(res, { 'homepage status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    // Browse categories
    const categories = ['electronics', 'clothing', 'home', 'sports'];
    const category = categories[Math.floor(Math.random() * categories.length)];

    res = http.get(`${baseUrl}/api/categories/${category}/products`);
    check(res, { 'category page status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    // View random product
    const product = products[Math.floor(Math.random() * products.length)];
    res = http.get(`${baseUrl}/api/products/${product.id}`);
    check(res, { 'product page status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);
  });
}

function simulateSearchingUser(baseUrl) {
  group('Searching User', function () {
    // Perform search
    const searchTerms = ['wireless', 'shoes', 'coffee', 'gaming', 'fitness'];
    const term = searchTerms[Math.floor(Math.random() * searchTerms.length)];

    const startTime = new Date().getTime();
    let res = http.get(`${baseUrl}/api/search?q=${term}`);
    const endTime = new Date().getTime();

    searchResponseTime.add(endTime - startTime);
    check(res, { 'search status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    // Filter search results
    if (res.status === 200 && res.json().products.length > 0) {
      const product = res.json().products[0];
      res = http.get(`${baseUrl}/api/products/${product.id}`);
      check(res, { 'searched product status 200': (r) => r.status === 200 });
      errorRate.add(res.status !== 200);
    }
  });
}

function simulateShoppingUser(baseUrl) {
  group('Shopping User', function () {
    // Add item to cart
    const product = products[Math.floor(Math.random() * products.length)];

    const cartStartTime = new Date().getTime();
    let res = http.post(
      `${baseUrl}/api/cart/items`,
      JSON.stringify({
        productId: product.id,
        quantity: Math.floor(Math.random() * 3) + 1,
      }),
      { headers: { 'Content-Type': 'application/json' } }
    );
    const cartEndTime = new Date().getTime();

    cartResponseTime.add(cartEndTime - cartStartTime);
    check(res, { 'add to cart status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    // View cart
    res = http.get(`${baseUrl}/api/cart`);
    check(res, { 'view cart status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    // Remove item from cart (25% chance)
    if (Math.random() < 0.25 && res.status === 200 && res.json().items.length > 0) {
      const itemId = res.json().items[0].id;
      res = http.del(`${baseUrl}/api/cart/items/${itemId}`);
      check(res, { 'remove from cart status 200': (r) => r.status === 200 });
      errorRate.add(res.status !== 200);
    }
  });
}

function simulateCheckoutUser(baseUrl) {
  group('Checkout User', function () {
    // Start checkout
    const checkoutStartTime = new Date().getTime();
    let res = http.post(
      `${baseUrl}/api/checkout/start`,
      JSON.stringify({
        cartId: `cart-${__VU}-${__ITER}`,
        shippingMethod: 'standard',
      }),
      { headers: { 'Content-Type': 'application/json' } }
    );
    const checkoutEndTime = new Date().getTime();

    checkoutResponseTime.add(checkoutEndTime - checkoutStartTime);
    check(res, { 'checkout start status 200': (r) => r.status === 200 });
    errorRate.add(res.status !== 200);

    if (res.status === 200) {
      const checkoutId = res.json().checkoutId;

      // Add shipping address
      res = http.post(
        `${baseUrl}/api/checkout/${checkoutId}/shipping`,
        JSON.stringify({
          address: '123 Test St',
          city: 'Test City',
          zipCode: '12345',
          country: 'US',
        }),
        { headers: { 'Content-Type': 'application/json' } }
      );
      check(res, { 'shipping address status 200': (r) => r.status === 200 });
      errorRate.add(res.status !== 200);

      // Complete checkout (50% chance)
      if (Math.random() < 0.5) {
        res = http.post(
          `${baseUrl}/api/checkout/${checkoutId}/complete`,
          JSON.stringify({
            paymentMethod: 'credit_card',
            paymentToken: 'test_token_123',
          }),
          { headers: { 'Content-Type': 'application/json' } }
        );
        check(res, { 'checkout complete status 200': (r) => r.status === 200 });
        errorRate.add(res.status !== 200);
      }
    }
  });
}

// Teardown function (runs once at end)
export function teardown(data) {
  console.log('Test completed at:', new Date().toISOString());
  console.log('Test started at:', data.testStartTime);

  // In a real scenario, you might:
  // 1. Clean up test data
  // 2. Generate reports
  // 3. Send notifications
}

// Generate HTML report
export function handleSummary(data) {
  return {
    'summary.html': htmlReport(data),
    'stdout': textSummary(data, { indent: ' ', enableColors: true }),
  };
}

