    // 3. Constant rate
    constantUsersPerSec(10).during(2.minutes),  // 10 users/sec for 2 min

    // 4. Ramp rate (increase rate)
    rampUsersPerSec(5).to(20).during(3.minutes), // 5→20 users/sec over 3 min

