import { browser } from 'k6/browser';
import { trend } from 'k6/metrics';

// Custom metrics for web vitals
const largestContentfulPaint = trend('web_vitals_lcp');
const firstInputDelay = trend('web_vitals_fid');
const cumulativeLayoutShift = trend('web_vitals_cls');

export const options = {
  scenarios: {
    browser: {
      executor: 'shared-iterations',
      vus: 5,
      iterations: 10,
      options: {
        browser: {
          type: 'chromium',
          launchOptions: {
            headless: true,
            args: ['--no-sandbox'],
          },
        },
      },
    },
  },
  thresholds: {
    'web_vitals_lcp': ['p(95)<2500'],
    'web_vitals_fid': ['p(95)<100'],
    'web_vitals_cls': ['p(95)<0.1'],
  },
};

export default async function () {
  const page = await browser.newPage();

  try {
    // Navigate and measure performance
    await page.goto('https://example.com', { waitUntil: 'networkidle' });

    // Capture Web Vitals
    const metrics = await page.evaluate(() => {
      return new Promise((resolve) => {
        const observer = new PerformanceObserver((list) => {
          const entries = list.getEntries();
          const metrics = {};

          entries.forEach((entry) => {
            switch (entry.entryType) {
              case 'largest-contentful-paint':
                metrics.lcp = entry.startTime;
                break;
              case 'first-input':
                metrics.fid = entry.processingStart - entry.startTime;
                break;
              case 'layout-shift':
                if (!metrics.cls) metrics.cls = 0;
                if (!entry.hadRecentInput) {
                  metrics.cls += entry.value;
                }
                break;
            }
          });

          resolve(metrics);
        });

        observer.observe({ entryTypes: ['largest-contentful-paint', 'first-input', 'layout-shift'] });

        // Stop observing after 5 seconds
        setTimeout(() => observer.disconnect(), 5000);
      });
    });

    // Record metrics
    if (metrics.lcp) largestContentfulPaint.add(metrics.lcp);
    if (metrics.fid) firstInputDelay.add(metrics.fid);
    if (metrics.cls) cumulativeLayoutShift.add(metrics.cls);

    // Interact with the page
    await page.locator('input[name="search"]').type('performance testing');
    await page.locator('button[type="submit"]').click();

    // Wait for results
    await page.waitForSelector('.search-results');

  } finally {
    await page.close();
  }
}

