// Maintenance Tracking and Management System
public class FrameworkMaintenanceManager {

    private final MaintenanceMetrics metrics;
    private final MaintenanceBacklog backlog;
    private final RefactoringPlanner refactoringPlanner;
    private final DependencyManager dependencyManager;

    public FrameworkMaintenanceManager(String projectPath) {
        this.metrics = new MaintenanceMetrics(projectPath);
        this.backlog = new MaintenanceBacklog();
        this.refactoringPlanner = new RefactoringPlanner(metrics);
        this.dependencyManager = new DependencyManager(projectPath);
    }

    public void analyzeMaintenanceNeeds() {
        // Collect metrics
        metrics.collectAllMetrics();

        // Analyze technical debt
        TechnicalDebtAnalysis debtAnalysis = metrics.analyzeTechnicalDebt();

        // Identify refactoring opportunities
        List<RefactoringOpportunity> opportunities = 
            refactoringPlanner.identifyOpportunities(debtAnalysis);

        // Check dependency health
        DependencyHealthReport dependencyReport = 
            dependencyManager.analyzeDependencies();

        // Update backlog
        updateBacklog(opportunities, dependencyReport, debtAnalysis);
    }

    public MaintenancePlan createMaintenancePlan(int sprintCapacity) {
        MaintenancePlan plan = new MaintenancePlan();

        // Allocate capacity
        int preventiveCapacity = (int) (sprintCapacity * 0.4);
        int adaptiveCapacity = (int) (sprintCapacity * 0.3);
        int perfectiveCapacity = (int) (sprintCapacity * 0.2);
        int correctiveCapacity = sprintCapacity - preventiveCapacity 
            - adaptiveCapacity - perfectiveCapacity;

        // Select items from backlog
        plan.addItems(backlog.selectItems("preventive", preventiveCapacity));
        plan.addItems(backlog.selectItems("adaptive", adaptiveCapacity));
        plan.addItems(backlog.selectItems("perfective", perfectiveCapacity));
        plan.addItems(backlog.selectItems("corrective", correctiveCapacity));

        return plan;
    }

    public void executeMaintenancePlan(MaintenancePlan plan) {
        for (MaintenanceItem item : plan.getItems()) {
            try {
                item.execute();
                backlog.markCompleted(item);
                metrics.recordMaintenanceActivity(item);
            } catch (Exception e) {
                backlog.markFailed(item, e.getMessage());
                System.err.println("Failed maintenance item: " + item + ", error: " + e.getMessage());
            }
        }

        // Update metrics after maintenance
        metrics.collectAllMetrics();
    }

    private void updateBacklog(List<RefactoringOpportunity> opportunities,
                              DependencyHealthReport dependencyReport,
                              TechnicalDebtAnalysis debtAnalysis) {
        // Add refactoring opportunities
        for (RefactoringOpportunity opportunity : opportunities) {
            MaintenanceItem item = createMaintenanceItem(opportunity);
            backlog.addItem(item);
        }

        // Add dependency updates
        for (DependencyIssue issue : dependencyReport.getCriticalIssues()) {
            MaintenanceItem item = createDependencyUpdateItem(issue);
            backlog.addItem(item, Priority.HIGH);
        }

        // Add high-debt items
        for (CodeSmell smell : debtAnalysis.getCriticalSmells()) {
            MaintenanceItem item = createDebtReductionItem(smell);
            backlog.addItem(item, Priority.MEDIUM);
        }
    }
}

// Maintenance Metrics Collector
public class MaintenanceMetrics {
    private final String projectPath;
    private final Map<String, Object> collectedMetrics;
    private final CodeAnalyzer codeAnalyzer;
    private final TestAnalyzer testAnalyzer;

    public MaintenanceMetrics(String projectPath) {
        this.projectPath = projectPath;
        this.collectedMetrics = new HashMap<>();
        this.codeAnalyzer = new CodeAnalyzer(projectPath);
        this.testAnalyzer = new TestAnalyzer(projectPath);
    }

    public void collectAllMetrics() {
        collectedMetrics.clear();

        // Code quality metrics
        collectedMetrics.put("complexity", codeAnalyzer.calculateComplexity());
        collectedMetrics.put("duplication", codeAnalyzer.calculateDuplication());
        collectedMetrics.put("smells", codeAnalyzer.detectCodeSmells());

        // Test quality metrics
        collectedMetrics.put("stability", testAnalyzer.calculateStability());
        collectedMetrics.put("flakiness", testAnalyzer.calculateFlakiness());
        collectedMetrics.put("coverage", testAnalyzer.calculateCoverage());

        // Maintenance metrics
        collectedMetrics.put("churn", calculateCodeChurn());
        collectedMetrics.put("debt", calculateTechnicalDebt());
        collectedMetrics.put("maintainability", calculateMaintainabilityIndex());
    }

    public TechnicalDebtAnalysis analyzeTechnicalDebt() {
        TechnicalDebtAnalysis analysis = new TechnicalDebtAnalysis();

        // Analyze code smells for debt
        List<CodeSmell> smells = (List<CodeSmell>) collectedMetrics.get("smells");
        double debtHours = 0;

        for (CodeSmell smell : smells) {
            double smellDebt = estimateDebtHours(smell);
            debtHours += smellDebt;
            analysis.addSmell(smell, smellDebt);
        }

        analysis.setTotalDebtHours(debtHours);
        analysis.setDebtRatio(debtHours / estimateTotalDevelopmentHours());

        return analysis;
    }

    private double calculateTechnicalDebt() {
        TechnicalDebtAnalysis analysis = analyzeTechnicalDebt();
        return analysis.getDebtRatio();
    }

    private double calculateMaintainabilityIndex() {
        // Calculate maintainability index (0-100)
        double complexity = (double) collectedMetrics.get("complexity");
        double duplication = (double) collectedMetrics.get("duplication");
        int smellCount = ((List<?>) collectedMetrics.get("smells")).size();

        // Simplified maintainability calculation
        double maintainability = 100.0;
        maintainability -= complexity * 0.5;
        maintainability -= duplication * 2.0;
        maintainability -= smellCount * 1.0;

        return Math.max(0, Math.min(100, maintainability));
    }

    private double calculateCodeChurn() {
        // Calculate percentage of code changed recently
        try {
            Process process = Runtime.getRuntime().exec(
                "git log --since=\"30 days ago\" --name-only --oneline | ".
                "sort | uniq | wc -l", 
                null, new File(projectPath));

            BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream()));
            String changedFiles = reader.readLine();

            // Get total files
            Process totalProcess = Runtime.getRuntime().exec(
                "find . -name \"*.java\" | wc -l", 
                null, new File(projectPath));

            BufferedReader totalReader = new BufferedReader(
                new InputStreamReader(totalProcess.getInputStream()));
            String totalFiles = totalReader.readLine();

            if (changedFiles != null && totalFiles != null) {
                double changed = Double.parseDouble(changedFiles.trim());
                double total = Double.parseDouble(totalFiles.trim());
                return total > 0 ? (changed / total) * 100 : 0;
            }
        } catch (Exception e) {
            System.err.println("Failed to calculate code churn: " + e.getMessage());
        }

        return 0.0;
    }

    private double estimateDebtHours(CodeSmell smell) {
        // Estimate hours to fix based on smell type and severity
        switch (smell.getType()) {
            case "LONG_METHOD": return 2.0;
            case "DUPLICATED_CODE": return 4.0;
            case "COMPLEX_CONDITIONAL": return 1.0;
            case "GOD_CLASS": return 8.0;
            case "LAZY_CLASS": return 0.5;
            default: return 1.0;
        }
    }

    private double estimateTotalDevelopmentHours() {
        // Estimate based on lines of code
        try {
            Process process = Runtime.getRuntime().exec(
                "find . -name \"*.java\" -exec wc -l {} + | tail -1 | awk '{print $1}'", 
                null, new File(projectPath));

            BufferedReader reader = new BufferedReader(
                new InputStreamReader(process.getInputStream()));
            String lines = reader.readLine();

            if (lines != null) {
                double loc = Double.parseDouble(lines.trim());
                // Assume 10 lines per hour (conservative estimate)
                return loc / 10.0;
            }
        } catch (Exception e) {
            System.err.println("Failed to estimate development hours: " + e.getMessage());
        }

        return 1000.0; // Default estimate
    }

    public void recordMaintenanceActivity(MaintenanceItem item) {
        // Record maintenance activity for metrics tracking
        // Implementation depends on tracking system
    }
}

// Technical Debt Analysis
public class TechnicalDebtAnalysis {
    private final Map<CodeSmell, Double> smellDebtMap;
    private double totalDebtHours;
    private double debtRatio;

    public TechnicalDebtAnalysis() {
        this.smellDebtMap = new HashMap<>();
    }

    public void addSmell(CodeSmell smell, double debtHours) {
        smellDebtMap.put(smell, debtHours);
    }

    public List<CodeSmell> getCriticalSmells() {
        return smellDebtMap.entrySet().stream()
            .filter(entry -> entry.getValue() >= 4.0) // 4+ hours is critical
            .map(Map.Entry::getKey)
            .collect(Collectors.toList());
    }

    public List<CodeSmell> getHighPrioritySmells() {
        return smellDebtMap.entrySet().stream()
            .filter(entry -> entry.getValue() >= 2.0 && entry.getValue() < 4.0)
            .map(Map.Entry::getKey)
            .collect(Collectors.toList());
    }

    // Getters and setters
    public double getTotalDebtHours() { return totalDebtHours; }
    public void setTotalDebtHours(double totalDebtHours) { this.totalDebtHours = totalDebtHours; }

    public double getDebtRatio() { return debtRatio; }
    public void setDebtRatio(double debtRatio) { this.debtRatio = debtRatio; }
}

// Automated Code Quality Checker
public class CodeQualityChecker {

    private final List<QualityRule> rules;
    private final List<QualityMetric> metrics;
    private final QualityReportGenerator reportGenerator;

    public CodeQualityChecker() {
        this.rules = loadQualityRules();
        this.metrics = loadQualityMetrics();
        this.reportGenerator = new QualityReportGenerator();
    }

    public QualityReport checkCodeQuality(String sourcePath) {
        QualityReport report = new QualityReport(sourcePath);

        // Parse source code
        List<SourceFile> sourceFiles = parseSourceFiles(sourcePath);

        // Apply rules
        for (SourceFile file : sourceFiles) {
            for (QualityRule rule : rules) {
                List<QualityViolation> violations = rule.check(file);
                if (!violations.isEmpty()) {
                    report.addViolations(file.getPath(), violations);
                }
            }
        }

        // Calculate metrics
        for (QualityMetric metric : metrics) {
            MetricResult result = metric.calculate(sourceFiles);
            report.addMetric(result);
        }

        // Generate overall score
        report.calculateOverallScore();

        return report;
    }

    public RefactoringSuggestions suggestRefactorings(QualityReport report) {
        RefactoringSuggestions suggestions = new RefactoringSuggestions();

        // Analyze violations for refactoring opportunities
        for (Map.Entry<String, List<QualityViolation>> entry : 
             report.getViolationsByFile().entrySet()) {

            String filePath = entry.getKey();
            List<QualityViolation> violations = entry.getValue();

            // Group violations by type and location
            Map<String, List<QualityViolation>> groupedViolations = 
                violations.stream().collect(Collectors.groupingBy(
                    v -> v.getType() + "_" + v.getLineNumber()));

            for (List<QualityViolation> group : groupedViolations.values()) {
                RefactoringSuggestion suggestion = 
                    analyzeViolationGroup(group, filePath);
                if (suggestion != null) {
                    suggestions.addSuggestion(suggestion);
                }
            }
        }

        // Prioritize suggestions
        suggestions.prioritize();

        return suggestions;
    }

    private RefactoringSuggestion analyzeViolationGroup(
            List<QualityViolation> violations, String filePath) {

        if (violations.isEmpty()) {
            return null;
        }

        QualityViolation firstViolation = violations.get(0);

        // Determine refactoring based on violation type
        switch (firstViolation.getType()) {
            case "DUPLICATED_CODE":
                return createExtractMethodSuggestion(violations, filePath);
            case "LONG_METHOD":
                return createExtractMethodSuggestion(violations, filePath);
            case "COMPLEX_CONDITIONAL":
                return createSimplifyConditionalSuggestion(violations, filePath);
            case "MAGIC_NUMBER":
                return createExtractConstantSuggestion(violations, filePath);
            case "GOD_CLASS":
                return createExtractClassSuggestion(violations, filePath);
            case "LAZY_CLASS":
                return createInlineClassSuggestion(violations, filePath);
            default:
                return null;
        }
    }

    private RefactoringSuggestion createExtractMethodSuggestion(
            List<QualityViolation> violations, String filePath) {

        RefactoringSuggestion suggestion = new RefactoringSuggestion(
            "Extract Method",
            filePath,
            violations.get(0).getLineNumber(),
            "High"
        );

        suggestion.setDescription("Extract duplicated/long method code into separate method");
        suggestion.setEffortEstimate(2); // hours
        suggestion.setBenefitEstimate(5); // maintenance hours saved

        // Add example code
        suggestion.setExampleBefore(
            "public void testLogin() {\n" +
            "    // 20 lines of login logic\n" +
            "    // Duplicated in other tests\n" +
            "}");

        suggestion.setExampleAfter(
            "public void testLogin() {\n" +
            "    loginUser("testuser", "password");\n" +
            "}\n\n" +
            "private void loginUser(String username, String password) {\n" +
            "    // Extracted login logic\n" +
            "}");

        return suggestion;
    }
}

// Quality Rule Implementation
public class DuplicateCodeRule implements QualityRule {

    private final int minDuplicateLines;

    public DuplicateCodeRule(int minDuplicateLines) {
        this.minDuplicateLines = minDuplicateLines;
    }

    @Override
    public List<QualityViolation> check(SourceFile file) {
        List<QualityViolation> violations = new ArrayList<>();

        // Find duplicate code blocks
        List<CodeBlock> blocks = extractCodeBlocks(file);

        for (int i = 0; i < blocks.size(); i++) {
            for (int j = i + 1; j < blocks.size(); j++) {
                CodeBlock block1 = blocks.get(i);
                CodeBlock block2 = blocks.get(j);

                if (isDuplicate(block1, block2)) {
                    violations.add(new QualityViolation(
                        "DUPLICATED_CODE",
                        file.getPath(),
                        block1.getStartLine(),
                        "Duplicate code detected: " + block1.getLines().size() + " lines",
                        "Consider extracting to common method"
                    ));
                }
            }
        }

        return violations;
    }

    private boolean isDuplicate(CodeBlock block1, CodeBlock block2) {
        if (block1.getLines().size() < minDuplicateLines ||
            block2.getLines().size() < minDuplicateLines) {
            return false;
        }

        // Simple duplicate detection (in real implementation, use more sophisticated algorithm)
        String normalized1 = normalizeCode(block1.getContent());
        String normalized2 = normalizeCode(block2.getContent());

        return normalized1.equals(normalized2);
    }

    private String normalizeCode(String code) {
        // Remove whitespace and comments for comparison
        return code.replaceAll("\\s+", " ")
                   .replaceAll("//.*", "")
                   .replaceAll("/\\*.*?\\*/", "")
                   .trim();
    }
}

// Test-Specific Quality Rules
public class TestQualityRule implements QualityRule {

    @Override
    public List<QualityViolation> check(SourceFile file) {
        List<QualityViolation> violations = new ArrayList<>();

        if (!file.isTestFile()) {
            return violations;
        }

        // Check for test-specific smells
        violations.addAll(checkForSleepStatements(file));
        violations.addAll(checkForHardcodedValues(file));
        violations.addAll(checkForTestInterdependence(file));
        violations.addAll(checkForMissingAssertions(file));
        violations.addAll(checkForTooManyAssertions(file));

        return violations;
    }

    private List<QualityViolation> checkForSleepStatements(SourceFile file) {
        List<QualityViolation> violations = new ArrayList<>();

        Pattern sleepPattern = Pattern.compile("Thread\.sleep|sleep\(|wait\(");
        for (int i = 0; i < file.getLines().size(); i++) {
            String line = file.getLines().get(i);
            if (sleepPattern.matcher(line).find()) {
                violations.add(new QualityViolation(
                    "SLEEP_STATEMENT",
                    file.getPath(),
                    i + 1,
                    "Sleep/wait statement found in test",
                    "Use explicit waits instead of Thread.sleep()"
                ));
            }
        }

        return violations;
    }

    private List<QualityViolation> checkForHardcodedValues(SourceFile file) {
        List<QualityViolation> violations = new ArrayList<>();

        // Look for magic numbers and strings in assertions
        Pattern assertionPattern = Pattern.compile(
            "assert.*\(.*\"([^\"]+)\".*\).*|assertEquals.*\(.*\"([^\"]+)\".*\)");

        for (int i = 0; i < file.getLines().size(); i++) {
            String line = file.getLines().get(i);
            if (assertionPattern.matcher(line).find()) {
                // Check if it's a URL, email, or other test data that should be externalized
                if (line.contains("http://") || line.contains("https://") || 
                    line.contains("@") || line.matches(".*[0-9]{10,}.*")) {

                    violations.add(new QualityViolation(
                        "HARDCODED_TEST_DATA",
                        file.getPath(),
                        i + 1,
                        "Hardcoded test data found",
                        "Externalize test data to configuration or data files"
                    ));
                }
            }
        }

        return violations;
    }

    private List<QualityViolation> checkForTestInterdependence(SourceFile file) {
        List<QualityViolation> violations = new ArrayList<>();

        // Check for @DependsOn or similar annotations
        Pattern dependsPattern = Pattern.compile("@DependsOn|dependsOnMethod");
        for (int i = 0; i < file.getLines().size(); i++) {
            String line = file.getLines().get(i);
            if (dependsPattern.matcher(line).find()) {
                violations.add(new QualityViolation(
                    "TEST_INTERDEPENDENCE",
                    file.getPath(),
                    i + 1,
                    "Test interdependence detected",
                    "Tests should be independent and runnable in any order"
                ));
            }
        }

        return violations;
    }
}

// Refactoring Automation
public class AutomatedRefactoringTool {

    private final RefactoringEngine refactoringEngine;
    private final CodeFormatter codeFormatter;
    private final TestRunner testRunner;

    public AutomatedRefactoringTool() {
        this.refactoringEngine = new RefactoringEngine();
        this.codeFormatter = new CodeFormatter();
        this.testRunner = new TestRunner();
    }

    public RefactoringResult applyRefactoring(
            String filePath, 
            RefactoringSuggestion suggestion) {

        RefactoringResult result = new RefactoringResult(suggestion);

        try {
            // Backup original file
            String backup = FileUtils.readFileToString(new File(filePath), "UTF-8");

            // Apply refactoring
            String refactoredCode = applyRefactoringToFile(filePath, suggestion);

            // Format code
            String formattedCode = codeFormatter.format(refactoredCode);

            // Write back
            FileUtils.writeStringToFile(new File(filePath), formattedCode, "UTF-8");

            // Run affected tests
            TestRunResult testResult = testRunner.runTestsForFile(filePath);

            if (testResult.allPassed()) {
                result.setSuccess(true);
                result.setMessage("Refactoring applied successfully");
            } else {
                // Rollback on test failure
                FileUtils.writeStringToFile(new File(filePath), backup, "UTF-8");
                result.setSuccess(false);
                result.setMessage("Refactoring failed: tests broke. Rolled back changes.");
                result.setTestFailures(testResult.getFailures());
            }

        } catch (Exception e) {
            result.setSuccess(false);
            result.setMessage("Refactoring failed: " + e.getMessage());
        }

        return result;
    }

    private String applyRefactoringToFile(
            String filePath, 
            RefactoringSuggestion suggestion) throws Exception {

        String content = FileUtils.readFileToString(new File(filePath), "UTF-8");

        switch (suggestion.getType()) {
            case "Extract Method":
                return refactoringEngine.extractMethod(content, suggestion);
            case "Extract Constant":
                return refactoringEngine.extractConstant(content, suggestion);
            case "Rename Variable":
                return refactoringEngine.renameVariable(content, suggestion);
            case "Inline Method":
                return refactoringEngine.inlineMethod(content, suggestion);
            default:
                throw new IllegalArgumentException("Unsupported refactoring type: " + 
                    suggestion.getType());
        }
    }
}

// Quality Gate for Pull Requests
public class PullRequestQualityGate {

    private final CodeQualityChecker qualityChecker;
    private final TestQualityAnalyzer testAnalyzer;
    private final Map<String, Double> qualityThresholds;

    public PullRequestQualityGate() {
        this.qualityChecker = new CodeQualityChecker();
        this.testAnalyzer = new TestQualityAnalyzer();
        this.qualityThresholds = loadQualityThresholds();
    }

    public QualityGateResult evaluatePullRequest(
            String sourceBranch, 
            String targetBranch) {

        QualityGateResult result = new QualityGateResult();

        // Get changed files
        List<String> changedFiles = getChangedFiles(sourceBranch, targetBranch);

        // Check each changed file
        for (String filePath : changedFiles) {
            if (filePath.endsWith(".java")) {
                QualityReport report = qualityChecker.checkCodeQuality(filePath);

                // Check against thresholds
                if (!meetsQualityThresholds(report)) {
                    result.addFailure(filePath, 
                        "Code quality below threshold: " + report.getOverallScore());
                }

                // Check test-specific quality for test files
                if (filePath.contains("Test") || filePath.contains("test")) {
                    TestQualityReport testReport = testAnalyzer.analyzeTestFile(filePath);
                    if (!testReport.isAcceptable()) {
                        result.addFailure(filePath, 
                            "Test quality issues: " + testReport.getIssues());
                    }
                }
            }
        }

        // Overall evaluation
        if (result.hasFailures()) {
            result.setPassed(false);
            result.setMessage("Quality gate failed: " + result.getFailureCount() + " issues");
        } else {
            result.setPassed(true);
            result.setMessage("Quality gate passed");
        }

        return result;
    }

    private boolean meetsQualityThresholds(QualityReport report) {
        return report.getOverallScore() >= qualityThresholds.get("overall_score") &&
               report.getMetricValue("complexity") <= qualityThresholds.get("max_complexity") &&
               report.getMetricValue("duplication") <= qualityThresholds.get("max_duplication") &&
               report.getViolationCount() <= qualityThresholds.get("max_violations");
    }
}

// Technical Debt Tracking System
public class TechnicalDebtManager {

    private final DebtInventory inventory;
    private final DebtAnalyzer analyzer;
    private final DebtPrioritizer prioritizer;
    private final PaymentPlanner paymentPlanner;

    public TechnicalDebtManager(String projectPath) {
        this.inventory = new DebtInventory(projectPath);
        this.analyzer = new DebtAnalyzer();
        this.prioritizer = new DebtPrioritizer();
        this.paymentPlanner = new PaymentPlanner();
    }

    public DebtReport analyzeTechnicalDebt() {
        // Discover debt items
        List<DebtItem> debtItems = inventory.discoverDebt();

        // Analyze each item
        for (DebtItem item : debtItems) {
            analyzer.analyzeDebtItem(item);
        }

        // Create report
        DebtReport report = new DebtReport();
        report.setDebtItems(debtItems);
        report.setTotalDebt(calculateTotalDebt(debtItems));
        report.setTotalInterest(calculateTotalInterest(debtItems));
        report.setDebtRatio(calculateDebtRatio(debtItems));

        return report;
    }

    public PaymentPlan createPaymentPlan(DebtReport report, int availableCapacity) {
        // Prioritize debt items
        List<DebtItem> prioritized = prioritizer.prioritize(report.getDebtItems());

        // Create payment plan
        PaymentPlan plan = paymentPlanner.createPlan(prioritized, availableCapacity);

        return plan;
    }

    public void trackPaymentProgress(PaymentPlan plan) {
        PaymentTracker tracker = new PaymentTracker(plan);
        tracker.trackProgress();

        // Generate progress report
        ProgressReport progressReport = tracker.generateProgressReport();

        // Update stakeholders
        notifyStakeholders(progressReport);
    }

    private double calculateTotalDebt(List<DebtItem> debtItems) {
        return debtItems.stream()
            .mapToDouble(DebtItem::getPrincipal)
            .sum();
    }

    private double calculateTotalInterest(List<DebtItem> debtItems) {
        return debtItems.stream()
            .mapToDouble(DebtItem::getAnnualInterest)
            .sum();
    }

    private double calculateDebtRatio(List<DebtItem> debtItems) {
        double totalDebt = calculateTotalDebt(debtItems);
        double codeValue = estimateCodeValue();

        return codeValue > 0 ? (totalDebt / codeValue) * 100 : 0;
    }

    private double estimateCodeValue() {
        // Estimate based on development cost
        // In reality, this would be more sophisticated
        return 100000; // $100k estimated value
    }
}

// Debt Item Representation
public class DebtItem {
    private final String id;
    private final DebtType type;
    private final String description;
    private final String location;
    private final DebtSeverity severity;
    private final double principal; // cost to fix
    private final double annualInterest; // annual cost of not fixing
    private final LocalDate createdDate;
    private LocalDate dueDate;
    private DebtStatus status;
    private String assignedTo;

    public DebtItem(String id, DebtType type, String description, 
                   String location, DebtSeverity severity) {
        this.id = id;
        this.type = type;
        this.description = description;
        this.location = location;
        this.severity = severity;
        this.createdDate = LocalDate.now();
        this.status = DebtStatus.OPEN;

        // Estimate principal and interest based on type and severity
        this.principal = estimatePrincipal(type, severity);
        this.annualInterest = estimateAnnualInterest(type, severity);
    }

    private double estimatePrincipal(DebtType type, DebtSeverity severity) {
        double basePrincipal = 0;

        switch (type) {
            case FLAKY_TEST:
                basePrincipal = 8.0; // hours
                break;
            case DUPLICATED_CODE:
                basePrincipal = 4.0;
                break;
            case BRITTLE_TEST:
                basePrincipal = 6.0;
                break;
            case OUTDATED_DEPENDENCY:
                basePrincipal = 2.0;
                break;
            case POOR_PERFORMANCE:
                basePrincipal = 12.0;
                break;
            default:
                basePrincipal = 4.0;
        }

        // Adjust for severity
        switch (severity) {
            case CRITICAL: return basePrincipal * 2.0;
            case HIGH: return basePrincipal * 1.5;
            case MEDIUM: return basePrincipal;
            case LOW: return basePrincipal * 0.5;
            default: return basePrincipal;
        }
    }

    private double estimateAnnualInterest(DebtType type, DebtSeverity severity) {
        double baseInterest = 0;

        switch (type) {
            case FLAKY_TEST:
                baseInterest = 40.0; // hours per year
                break;
            case DUPLICATED_CODE:
                baseInterest = 20.0;
                break;
            case BRITTLE_TEST:
                baseInterest = 60.0;
                break;
            case OUTDATED_DEPENDENCY:
                baseInterest = 10.0;
                break;
            case POOR_PERFORMANCE:
                baseInterest = 30.0;
                break;
            default:
                baseInterest = 20.0;
        }

        // Adjust for severity
        switch (severity) {
            case CRITICAL: return baseInterest * 3.0;
            case HIGH: return baseInterest * 2.0;
            case MEDIUM: return baseInterest;
            case LOW: return baseInterest * 0.5;
            default: return baseInterest;
        }
    }

    public double getTotalCost(int years) {
        // Total cost = principal + (interest * years)
        return principal + (annualInterest * years);
    }

    public double getRoi(int years) {
        // ROI = (interest saved - principal) / principal
        double interestSaved = annualInterest * years;
        return (interestSaved - principal) / principal;
    }

    // Getters and setters
    public String getId() { return id; }
    public DebtType getType() { return type; }
    public String getDescription() { return description; }
    public double getPrincipal() { return principal; }
    public double getAnnualInterest() { return annualInterest; }
}

// Debt Inventory
public class DebtInventory {
    private final String projectPath;
    private final CodeAnalyzer codeAnalyzer;
    private final TestAnalyzer testAnalyzer;
    private final DependencyAnalyzer dependencyAnalyzer;

    public DebtInventory(String projectPath) {
        this.projectPath = projectPath;
        this.codeAnalyzer = new CodeAnalyzer(projectPath);
        this.testAnalyzer = new TestAnalyzer(projectPath);
        this.dependencyAnalyzer = new DependencyAnalyzer(projectPath);
    }

    public List<DebtItem> discoverDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Discover code quality debt
        debtItems.addAll(discoverCodeQualityDebt());

        // Discover test quality debt
        debtItems.addAll(discoverTestQualityDebt());

        // Discover dependency debt
        debtItems.addAll(discoverDependencyDebt());

        // Discover performance debt
        debtItems.addAll(discoverPerformanceDebt());

        return debtItems;
    }

    private List<DebtItem> discoverCodeQualityDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze code smells
        List<CodeSmell> smells = codeAnalyzer.detectCodeSmells();

        for (CodeSmell smell : smells) {
            if (smell.getSeverity() >= CodeSmell.Severity.MAJOR) {
                DebtItem item = new DebtItem(
                    "CODE-" + UUID.randomUUID().toString().substring(0, 8),
                    DebtType.CODE_SMELL,
                    "Code smell: " + smell.getType(),
                    smell.getLocation(),
                    convertSeverity(smell.getSeverty())
                );
                debtItems.add(item);
            }
        }

        // Analyze duplication
        double duplicationRate = codeAnalyzer.calculateDuplication();
        if (duplicationRate > 5.0) { // More than 5% duplication
            DebtItem item = new DebtItem(
                "DUP-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.DUPLICATED_CODE,
                "High code duplication: " + String.format("%.1f", duplicationRate) + "%",
                projectPath,
                duplicationRate > 10.0 ? DebtSeverity.HIGH : DebtSeverity.MEDIUM
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private List<DebtItem> discoverTestQualityDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze flaky tests
        List<FlakyTest> flakyTests = testAnalyzer.identifyFlakyTests();
        for (FlakyTest flakyTest : flakyTests) {
            DebtItem item = new DebtItem(
                "FLAKY-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.FLAKY_TEST,
                "Flaky test: " + flakyTest.getTestName(),
                flakyTest.getLocation(),
                flakyTest.getFlakinessRate() > 0.3 ? DebtSeverity.CRITICAL : DebtSeverity.HIGH
            );
            debtItems.add(item);
        }

        // Analyze brittle tests
        List<BrittleTest> brittleTests = testAnalyzer.identifyBrittleTests();
        for (BrittleTest brittleTest : brittleTests) {
            DebtItem item = new DebtItem(
                "BRITTLE-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.BRITTLE_TEST,
                "Brittle test: " + brittleTest.getTestName(),
                brittleTest.getLocation(),
                DebtSeverity.HIGH
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private List<DebtItem> discoverDependencyDebt() {
        List<DebtItem> debtItems = new ArrayList<>();

        // Analyze outdated dependencies
        List<OutdatedDependency> outdatedDeps = dependencyAnalyzer.findOutdatedDependencies();

        for (OutdatedDependency dep : outdatedDeps) {
            DebtSeverity severity;
            if (dep.isSecurityVulnerability()) {
                severity = DebtSeverity.CRITICAL;
            } else if (dep.getVersionsBehind() > 5) {
                severity = DebtSeverity.HIGH;
            } else if (dep.getVersionsBehind() > 2) {
                severity = DebtSeverity.MEDIUM;
            } else {
                severity = DebtSeverity.LOW;
            }

            DebtItem item = new DebtItem(
                "DEP-" + UUID.randomUUID().toString().substring(0, 8),
                DebtType.OUTDATED_DEPENDENCY,
                "Outdated dependency: " + dep.getName() + " (" + 
                dep.getCurrentVersion() + " -> " + dep.getLatestVersion() + ")",
                dep.getLocation(),
                severity
            );
            debtItems.add(item);
        }

        return debtItems;
    }

    private DebtSeverity convertSeverity(CodeSmell.Severity smellSeverity) {
        switch (smellSeverity) {
            case BLOCKER: return DebtSeverity.CRITICAL;
            case CRITICAL: return DebtSeverity.HIGH;
            case MAJOR: return DebtSeverity.MEDIUM;
            case MINOR: return DebtSeverity.LOW;
            default: return DebtSeverity.LOW;
        }
    }
}

// Debt Prioritizer
public class DebtPrioritizer {

    public List<DebtItem> prioritize(List<DebtItem> debtItems) {
        return debtItems.stream()
            .sorted((item1, item2) -> {
                // Priority = f(severity, interest, age, roi)
                double priority1 = calculatePriority(item1);
                double priority2 = calculatePriority(item2);

                return Double.compare(priority2, priority1); // Higher priority first
            })
            .collect(Collectors.toList());
    }

    private double calculatePriority(DebtItem item) {
        double priority = 0;

        // Severity weight (40%)
        priority += getSeverityWeight(item.getSeverity()) * 0.4;

        // Interest weight (30%)
        priority += normalizeInterest(item.getAnnualInterest()) * 0.3;

        // Age weight (20%)
        priority += calculateAgeWeight(item.getCreatedDate()) * 0.2;

        // ROI weight (10%)
        priority += calculateRoiWeight(item) * 0.1;

        return priority;
    }

    private double getSeverityWeight(DebtSeverity severity) {
        switch (severity) {
            case CRITICAL: return 1.0;
            case HIGH: return 0.75;
            case MEDIUM: return 0.5;
            case LOW: return 0.25;
            default: return 0.5;
        }
    }

    private double normalizeInterest(double interest) {
        // Normalize to 0-1 range
        // Assume max interest is 100 hours/year
        return Math.min(interest / 100.0, 1.0);
    }

    private double calculateAgeWeight(LocalDate createdDate) {
        long daysOld = ChronoUnit.DAYS.between(createdDate, LocalDate.now());

        // Older debt gets higher weight, up to 180 days
        return Math.min(daysOld / 180.0, 1.0);
    }

    private double calculateRoiWeight(DebtItem item) {
        double roi = item.getRoi(1); // 1-year ROI

        // Higher ROI gets higher weight
        return Math.min(roi / 5.0, 1.0); // Cap at 500% ROI
    }
}

// Debt Dashboard
