@Component
@Scope("cucumber-glue")
public class TestContext {

    private final Map<String, Object> contextData = new ConcurrentHashMap<>();
    private final ThreadLocal<WebDriver> driver = new ThreadLocal<>();
    private final ThreadLocal<Scenario> currentScenario = new ThreadLocal<>();
    private final List<TestAttachment> attachments = new ArrayList<>();

    public enum ContextKey {
        CURRENT_USER,
        CURRENT_ORDER,
        TEST_DATA,
        API_RESPONSE,
        SCREENSHOT_PATH
    }

    public void setDriver(WebDriver driver) {
        this.driver.set(driver);
    }

    public WebDriver getDriver() {
        return driver.get();
    }

    public void setScenario(Scenario scenario) {
        currentScenario.set(scenario);
    }

    public Scenario getScenario() {
        return currentScenario.get();
    }

    public void put(ContextKey key, Object value) {
        contextData.put(key.name(), value);
    }

    @SuppressWarnings("unchecked")
    public <T> T get(ContextKey key) {
        return (T) contextData.get(key.name());
    }

    public void attachScreenshot(String name) {
        if (getDriver() instanceof TakesScreenshot) {
            File screenshot = ((TakesScreenshot) getDriver()).getScreenshotAs(OutputType.FILE);
            getScenario().attach(FileUtils.readFileToByteArray(screenshot), "image/png", name);
        }
    }

    public void attachJson(String name, Object data) throws JsonProcessingException {
        ObjectMapper mapper = new ObjectMapper();
        String json = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(data);
        getScenario().attach(json, "application/json", name);
    }

    public void clear() {
        contextData.clear();
        if (driver.get() != null) {
            driver.get().quit();
            driver.remove();
        }
        currentScenario.remove();
        attachments.clear();
    }
}

