      accessibilityRegions: [
        {
          selector: '.checkout-form label',
          type: 'RegularText'
        },
        {
          selector: '.error-message',
          type: 'BoldText'
        }
      ],
      waitForSelectors: [
        '.checkout-form',
        '.order-summary',
        '.payment-options'
      ],
