import boto3
from botocore.config import Config
from datetime import datetime, timedelta
import json
from typing import Dict, List, Any, Optional

class AWSFaultInjector:
    """
    AWS Fault Injection Simulator (FIS) integration for chaos engineering.
    """

    def __init__(self, region: str = "us-west-2", profile: str = None):
        """Initialize FIS client."""
        session = boto3.Session(profile_name=profile) if profile else boto3.Session()
        config = Config(
            retries={
                'max_attempts': 10,
                'mode': 'standard'
            }
        )

        self.fis = session.client('fis', region_name=region, config=config)
        self.ec2 = session.client('ec2', region_name=region)
        self.rds = session.client('rds', region_name=region)
        self.ssm = session.client('ssm', region_name=region)

        self.region = region

    def create_ec2_stop_experiment(self, 
                                 instance_ids: List[str],
                                 experiment_name: str,
                                 duration: int = 300) -> Dict[str, Any]:
        """
        Create experiment to stop EC2 instances.
        """
        # Create experiment template
        template = {
            "description": f"Stop EC2 instances {instance_ids}",
            "stopConditions": [
                {
                    "source": "aws:cloudwatch:alarm",
                    "value": "arn:aws:cloudwatch:us-west-2:123456789012:alarm:High-CPU-Utilization"
                }
            ],
            "targets": {
                "Instances": {
                    "resourceType": "aws:ec2:instance",
                    "resourceArns": [
                        f"arn:aws:ec2:{self.region}:123456789012:instance/{instance_id}"
                        for instance_id in instance_ids
                    ],
                    "selectionMode": "ALL"
                }
            },
            "actions": {
                "stop-instances": {
                    "actionId": "aws:ec2:stop-instances",
                    "parameters": {
                        "startInstancesAfterDuration": f"PT{duration}S"
                    },
                    "targets": {
                        "Instances": "Instances"
                    }
                }
            },
            "roleArn": "arn:aws:iam::123456789012:role/awsfis-service-role",
            "tags": {
                "Name": experiment_name,
                "Environment": "staging",
                "ChaosExperiment": "true"
            }
        }

        response = self.fis.create_experiment_template(**template)
        template_id = response["experimentTemplate"]["id"]

        logger.info(f"Created experiment template: {template_id}")
        return {"template_id": template_id, "template": template}

    def create_network_latency_experiment(self,
                                        vpc_id: str,
                                        subnet_ids: List[str],
                                        latency_ms: int = 100,
                                        jitter_ms: int = 20) -> Dict[str, Any]:
        """
        Create experiment to inject network latency.
        """
        # Get network ACL for the subnet
        nacl_response = self.ec2.describe_network_acls(
            Filters=[
                {
                    'Name': 'vpc-id',
                    'Values': [vpc_id]
                },
                {
                    'Name': 'association.subnet-id',
                    'Values': subnet_ids
                }
            ]
        )

        if not nacl_response["NetworkAcls"]:
            raise ValueError(f"No NACL found for subnets: {subnet_ids}")

        nacl_id = nacl_response["NetworkAcls"][0]["NetworkAclId"]

        # Create SSM document for network latency
        ssm_document = {
            "schemaVersion": "2.2",
            "description": "Inject network latency using tc",
            "parameters": {
                "Latency": {
                    "type": "String",
                    "default": str(latency_ms),
                    "description": "Latency in milliseconds"
                },
                "Jitter": {
                    "type": "String",
                    "default": str(jitter_ms),
                    "description": "Jitter in milliseconds"
                },
                "Duration": {
                    "type": "String",
                    "default": "300",
                    "description": "Duration in seconds"
                }
            },
            "mainSteps": [
                {
                    "name": "InjectLatency",
                    "action": "aws:runShellScript",
                    "inputs": {
                        "runCommand": [
                            "#!/bin/bash",
                            "# Install tc if not present",
                            "command -v tc >/dev/null 2>&1 || { \\",
                            "  if [ -f /etc/redhat-release ]; then",
                            "    yum install -y iproute",
                            "  elif [ -f /etc/debian_version ]; then",
                            "    apt-get update && apt-get install -y iproute2",
                            "  fi",
                            "}",
                            "",
                            "# Get primary network interface",
                            "INTERFACE=$(ip route | grep default | awk '{print $5}')",
                            "",
                            "# Inject latency",
                            "tc qdisc add dev $INTERFACE root netem delay ${Latency}ms ${Jitter}ms",
                            "",
                            "# Wait for duration",
                            "sleep ${Duration}",
                            "",
                            "# Remove latency",
                            "tc qdisc del dev $INTERFACE root"
                        ]
                    }
                }
            ]
        }

        # Create or update SSM document
        document_name = f"InjectNetworkLatency-{int(datetime.now().timestamp())}"
        try:
            self.ssm.create_document(
                Content=json.dumps(ssm_document),
                Name=document_name,
                DocumentType="Command",
                DocumentFormat="JSON"
            )
        except self.ssm.exceptions.DocumentAlreadyExists:
            self.ssm.update_document(
                Content=json.dumps(ssm_document),
                Name=document_name,
                DocumentVersion="$LATEST"
            )

        # Create FIS experiment
        experiment_template = {
            "description": f"Inject {latency_ms}ms network latency with {jitter_ms}ms jitter",
            "stopConditions": [
                {
                    "source": "none"
                }
            ],
            "targets": {
                "InstancesInSubnet": {
                    "resourceType": "aws:ec2:instance",
                    "resourceTags": {
                        "Subnet": "true"
                    },
                    "filters": [
                        {
                            "path": "State.Name",
                            "values": ["running"]
                        }
                    ],
                    "selectionMode": "COUNT(1)"
                }
            },
            "actions": {
                "ssm-latency": {
                    "actionId": "aws:ssm:send-command",
                    "parameters": {
                        "documentArn": f"arn:aws:ssm:{self.region}::document/{document_name}",
                        "documentParameters": json.dumps({
                            "Latency": str(latency_ms),
                            "Jitter": str(jitter_ms),
                            "Duration": "300"
                        }),
                        "duration": "PT5M"
                    },
                    "targets": {
                        "Instances": "InstancesInSubnet"
                    }
                }
            },
            "roleArn": "arn:aws:iam::123456789012:role/awsfis-service-role",
            "tags": {
                "Name": "network-latency-experiment",
                "ChaosType": "network"
            }
        }

        response = self.fis.create_experiment_template(**experiment_template)
        return {
            "template_id": response["experimentTemplate"]["id"],
            "ssm_document": document_name
        }

    def start_experiment(self, template_id: str,
                        client_token: str = None) -> Dict[str, Any]:
        """
        Start a chaos experiment.
        """
        params = {
            "experimentTemplateId": template_id
        }

        if client_token:
            params["clientToken"] = client_token

        response = self.fis.start_experiment(**params)
        experiment_id = response["experiment"]["id"]

        logger.info(f"Started experiment: {experiment_id}")
        return {
            "experiment_id": experiment_id,
            "status": response["experiment"]["state"]["status"],
            "start_time": response["experiment"]["creationTime"]
        }

    def monitor_experiment(self, experiment_id: str) -> Dict[str, Any]:
        """
        Monitor experiment status and results.
        """
        response = self.fis.get_experiment(id=experiment_id)
        experiment = response["experiment"]

        status = experiment["state"]["status"]
        actions = experiment.get("actions", {})

        # Get CloudWatch metrics for impact analysis
        metrics = self._get_experiment_metrics(experiment_id)

        return {
            "experiment_id": experiment_id,
            "status": status,
            "start_time": experiment["creationTime"],
            "end_time": experiment.get("endTime"),
            "actions": actions,
            "metrics": metrics,
            "log": self._get_experiment_logs(experiment_id)
        }

    def stop_experiment(self, experiment_id: str) -> Dict[str, Any]:
        """
        Stop a running experiment.
        """
        response = self.fis.stop_experiment(id=experiment_id)

        logger.info(f"Stopped experiment: {experiment_id}")
        return {
            "experiment_id": experiment_id,
            "status": response["experiment"]["state"]["status"]
        }

    def create_rds_failover_experiment(self,
                                     db_instance_identifier: str,
                                     force_failover: bool = False) -> Dict[str, Any]:
        """
        Create experiment to test RDS failover.
        """
        # Check if instance exists and is Multi-AZ
        response = self.rds.describe_db_instances(
            DBInstanceIdentifier=db_instance_identifier
        )

        instance = response["DBInstances"][0]
        if not instance["MultiAZ"]:
            raise ValueError(f"Instance {db_instance_identifier} is not Multi-AZ")

        # Create SSM document for monitoring
        ssm_document = {
            "schemaVersion": "2.2",
            "description": "Monitor RDS failover",
            "parameters": {
                "DBInstanceIdentifier": {
                    "type": "String",
                    "default": db_instance_identifier
                }
            },
            "mainSteps": [
                {
                    "name": "MonitorBeforeFailover",
                    "action": "aws:runShellScript",
                    "inputs": {
                        "runCommand": [
                            "#!/bin/bash",
                            f"aws rds describe-db-instances \",
                            f"  --db-instance-identifier {db_instance_identifier} \",
                            f"  --query 'DBInstances[0].{{DBInstanceStatus:DBInstanceStatus, AvailabilityZone:AvailabilityZone}}' \",
                            f"  --output json"
                        ]
                    },
                    "precondition": {
                        "StringEquals": ["platformType", "Linux"]
                    }
                },
                {
                    "name": "TriggerFailover",
                    "action": "aws:runShellScript",
                    "inputs": {
