                            "#!/bin/bash",
                            f"aws rds reboot-db-instance \",
                            f"  --db-instance-identifier {db_instance_identifier} \",
                            f"  --force-failover {str(force_failover).lower()}"
                        ]
                    },
                    "precondition": {
                        "StringEquals": ["platformType", "Linux"]
                    }
                },
                {
                    "name": "MonitorAfterFailover",
                    "action": "aws:runShellScript",
                    "timeoutSeconds": 600,
                    "inputs": {
                        "runCommand": [
                            "#!/bin/bash",
                            "# Wait for failover to complete",
                            "for i in {1..30}; do",
                            f"  STATUS=$(aws rds describe-db-instances \",
                            f"    --db-instance-identifier {db_instance_identifier} \",
                            f"    --query 'DBInstances[0].DBInstanceStatus' \",
                            f"    --output text)",
                            "  if [ \"$STATUS\" == \"available\" ]; then",
                            "    echo \"Failover completed\"",
                            "    break",
                            "  fi",
                            "  sleep 10",
                            "done"
                        ]
                    }
                }
            ]
        }

        # Create FIS experiment
        experiment_template = {
            "description": f"Test RDS failover for {db_instance_identifier}",
            "stopConditions": [
                {
                    "source": "aws:cloudwatch:alarm",
                    "value": f"arn:aws:cloudwatch:{self.region}:123456789012:alarm:RDS-High-CPU"
                }
            ],
            "targets": {
                "RDSInstance": {
                    "resourceType": "aws:rds:db",
                    "resourceArns": [
                        f"arn:aws:rds:{self.region}:123456789012:db:{db_instance_identifier}"
                    ],
                    "selectionMode": "ALL"
                }
            },
            "actions": {
                "rds-failover": {
                    "actionId": "aws:ssm:send-command",
                    "parameters": {
                        "documentArn": f"arn:aws:ssm:{self.region}::document/Custom-RDS-Failover",
                        "documentParameters": json.dumps({
                            "DBInstanceIdentifier": db_instance_identifier,
                            "ForceFailover": str(force_failover).lower()
                        }),
                        "duration": "PT10M"
                    },
                    "targets": {
                        "Instances": "RDSInstance"
                    }
                }
            },
            "roleArn": "arn:aws:iam::123456789012:role/awsfis-service-role",
            "tags": {
                "Name": "rds-failover-test",
                "Database": db_instance_identifier,
                "ChaosType": "database"
