from typing import Callable, Optional, Any, List
from playwright.sync_api import Page, Locator, expect
import allure
import time
from src.core.logger import get_logger

logger = get_logger(__name__)

class CustomAssertions:
    """Custom assertion methods for robust testing"""

    @staticmethod
    def assert_with_retry(
        assertion_func: Callable,
        timeout: int = 30,
        interval: float = 0.5,
        message: Optional[str] = None
    ) -> bool:
        """
        Retry assertion until it passes or timeout

        Args:
            assertion_func: Function that raises AssertionError on failure
            timeout: Maximum time to wait in seconds
            interval: Time between retries in seconds
            message: Custom error message

        Returns:
            bool: True if assertion passed
        """
        end_time = time.time() + timeout
        last_error = None

        while time.time() < end_time:
            try:
                assertion_func()
                return True
            except AssertionError as e:
                last_error = e
                time.sleep(interval)
            except Exception as e:
                last_error = AssertionError(f"Unexpected error: {e}")
                time.sleep(interval)

        if message:
            raise AssertionError(f"{message}\nLast error: {last_error}")
        else:
            raise last_error if last_error else AssertionError("Assertion failed")

    @staticmethod
    def assert_element_has_class(
        page: Page,
        selector: str,
        expected_class: str,
        timeout: int = 10
    ):
        """Assert element has specific CSS class"""
        with allure.step(f"Verify element {selector} has class '{expected_class}'"):
            element = page.locator(selector).first
            expect(element).to_have_class(f".*{expected_class}.*", timeout=timeout * 1000)

    @staticmethod
    def assert_element_count(
        page: Page,
        selector: str,
        expected_count: int,
        timeout: int = 10
    ):
        """Assert exact count of elements"""
        with allure.step(f"Verify {expected_count} elements found for {selector}"):

            def check_count():
                actual_count = page.locator(selector).count()
                assert actual_count == expected_count, \
                    f"Expected {expected_count} elements, found {actual_count}"

            CustomAssertions.assert_with_retry(check_count, timeout=timeout)

    @staticmethod
    def assert_url_matches_pattern(
        page: Page,
        pattern: str,
        timeout: int = 10
    ):
        """Assert URL matches regex pattern"""
        with allure.step(f"Verify URL matches pattern: {pattern}"):
            expect(page).to_have_url(f".*{pattern}.*", timeout=timeout * 1000)

    @staticmethod
    def assert_page_title(
        page: Page,
        expected_title: str,
        timeout: int = 10
    ):
        """Assert page title"""
        with allure.step(f"Verify page title is '{expected_title}'"):
            expect(page).to_have_title(expected_title, timeout=timeout * 1000)

    @staticmethod
    def assert_element_attribute(
        element: Locator,
        attribute: str,
        expected_value: str,
        timeout: int = 10
    ):
        """Assert element attribute value"""
        with allure.step(f"Verify element attribute {attribute} = '{expected_value}'"):
            expect(element).to_have_attribute(attribute, expected_value, timeout=timeout * 1000)

    @staticmethod
    def assert_soft(assertions: List[Callable], fail_fast: bool = False):
        """
        Perform multiple assertions with soft failure option

        Args:
            assertions: List of assertion functions
            fail_fast: If True, stop on first failure
        """
        errors = []

        for i, assertion_func in enumerate(assertions):
            try:
                assertion_func()
            except AssertionError as e:
                errors.append(f"Assertion {i + 1} failed: {e}")
                if fail_fast:
                    break

        if errors:
            error_message = "\n".join(errors)
            allure.attach(error_message, name="Soft Assertion Errors")
            raise AssertionError(f"Soft assertions failed:\n{error_message}")

    @staticmethod
    def assert_performance_metric(
        page: Page,
        metric_name: str,
        max_value: float,
        description: Optional[str] = None
    ):
        """Assert performance metric is within acceptable range"""
        with allure.step(f"Verify {metric_name} <= {max_value}ms"):
            metrics = page.evaluate("""
                () => {
                    const [timing] = performance.getEntriesByType('navigation');
                    return {
                        'dns_lookup': timing.domainLookupEnd - timing.domainLookupStart,
                        'tcp_connection': timing.connectEnd - timing.connectStart,
                        'request_response': timing.responseEnd - timing.requestStart,
                        'dom_loading': timing.domContentLoadedEventEnd - timing.domContentLoadedEventStart,
                        'page_load': timing.loadEventEnd - timing.loadEventStart,
                        'total_time': timing.loadEventEnd - timing.navigationStart
                    };
                }
            """)

            actual_value = metrics.get(metric_name, 0)
            assert actual_value <= max_value, \
                f"{metric_name} exceeded limit: {actual_value}ms > {max_value}ms"

            if description:
                allure.attach(f"{metric_name}: {actual_value}ms", name=description)

class WaitHandlers:
    """Custom wait handlers for dynamic content"""

    @staticmethod
    def wait_for_ajax_complete(page: Page, timeout: int = 30):
        """Wait for all AJAX requests to complete"""
        def is_ajax_complete():
            return page.evaluate("""() => {
                return window.jQuery ? jQuery.active === 0 : true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_ajax_complete():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"AJAX requests did not complete within {timeout} seconds")

    @staticmethod
    def wait_for_angular_ready(page: Page, timeout: int = 30):
        """Wait for Angular applications to be ready"""
        def is_angular_ready():
            return page.evaluate("""() => {
                if (window.angular) {
                    const injector = window.angular.element(document).injector();
                    return injector.get('$http').pendingRequests.length === 0;
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_angular_ready():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"Angular did not become ready within {timeout} seconds")

    @staticmethod
    def wait_for_react_ready(page: Page, timeout: int = 30):
        """Wait for React applications to be ready"""
        def is_react_ready():
            return page.evaluate("""() => {
                // Check for React loading state
                const reactRoot = document.querySelector('[data-reactroot], [data-reactid]');
                if (reactRoot) {
                    // Check if React has finished rendering
                    return !reactRoot.hasAttribute('data-react-loading');
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_react_ready():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"React did not become ready within {timeout} seconds")

    @staticmethod
    def wait_for_element_stable(
        page: Page,
        selector: str,
        stability_time: float = 1.0,
        timeout: int = 30
    ):
        """
        Wait for element to be stable (not moving/changing)

        Args:
            page: Playwright page object
            selector: Element selector
            stability_time: Time element must be stable (seconds)
            timeout: Maximum wait time (seconds)
        """
        element = page.locator(selector).first
        start_time = time.time()
        stable_start = None

        while time.time() - start_time < timeout:
            try:
                # Get current bounding box
                current_box = element.bounding_box()

                if current_box:
                    if stable_start is None:
                        stable_start = time.time()
                    elif time.time() - stable_start >= stability_time:
                        return True
                else:
                    stable_start = None

                time.sleep(0.1)

            except Exception:
                stable_start = None
                time.sleep(0.1)

        raise TimeoutError(f"Element {selector} did not stabilize within {timeout} seconds")

    @staticmethod
    def wait_for_animation_complete(page: Page, selector: str, timeout: int = 10):
        """Wait for CSS animations to complete"""
        def is_animation_complete():
            return page.evaluate(f"""(selector) => {
                const element = document.querySelector(selector);
                if (!element) return true;

                const style = window.getComputedStyle(element);
                const animation = style.animationName || style.webkitAnimationName;
                const transition = style.transitionProperty || style.webkitTransitionProperty;

                return animation === 'none' && transition === 'none';
            }""", selector)

        end_time = time.time() + timeout
        while time.time() < end_time:
            if is_animation_complete():
                return True
            time.sleep(0.1)

        raise TimeoutError(f"Animations for {selector} did not complete within {timeout} seconds")

    @staticmethod
    def wait_for_images_to_load(page: Page, timeout: int = 30):
        """Wait for all images to load"""
        def all_images_loaded():
            return page.evaluate("""() => {
                const images = document.getElementsByTagName('img');
                for (let img of images) {
                    if (!img.complete) return false;
                    if (img.naturalWidth === 0) return false;
                }
                return true;
            }""")

        end_time = time.time() + timeout
        while time.time() < end_time:
            if all_images_loaded():
                return True
            time.sleep(0.5)

        raise TimeoutError(f"Images did not load within {timeout} seconds")

# src/api/client.py
import requests
from typing import Dict, Optional, Any, Union, List, Tuple
from dataclasses import dataclass
from pydantic import BaseModel, ValidationError
import jsonschema
import json
import time
from datetime import datetime
from src.core.logger import get_logger
from src.config.base_config import get_config

logger = get_logger(__name__)

@dataclass
class APIResponse:
    """Standard API response container with enhanced metadata"""
    status_code: int
    headers: Dict[str, str]
    body: Any
    elapsed_time: float
    request: Optional[Dict] = None
    cookies: Optional[Dict] = None
    encoding: Optional[str] = None
    content_type: Optional[str] = None

    def __post_init__(self):
        # Parse JSON body if content type indicates JSON
        if isinstance(self.body, (str, bytes)) and \
           self.content_type and 'application/json' in self.content_type:
            try:
                self.body = json.loads(self.body)
            except json.JSONDecodeError:
                pass  # Keep as string if not valid JSON

class APIClient:
    """REST API client with built-in validation, retry logic, and performance tracking"""

    def __init__(self, base_url: Optional[str] = None):
        self.config = get_config()
        self.base_url = base_url or self.config.api_base_url
        self.session = requests.Session()
        self._setup_session()
        self.request_history: List[Dict] = []
        self.max_history_size = 100

    def _setup_session(self):
        """Setup session with default headers, auth, and retry strategy"""
        # Default headers
        self.session.headers.update({
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "ShopSmart-APITest/1.0",
            "X-Request-ID": f"test-{datetime.now().strftime('%Y%m%d%H%M%S')}"
        })

        # Add authentication if configured
        if hasattr(self.config, 'api_token') and self.config.api_token:
            self.session.headers["Authorization"] = f"Bearer {self.config.api_token}"

        # Setup retry adapter with exponential backoff
        from requests.adapters import HTTPAdapter
        from urllib3.util.retry import Retry

        retry_strategy = Retry(
            total=self.config.api_retry_attempts,
            backoff_factor=self.config.api_retry_delay,
            status_forcelist=[429, 500, 502, 503, 504],
            allowed_methods=["GET", "POST", "PUT", "DELETE", "PATCH"],
            raise_on_status=False
        )

        adapter = HTTPAdapter(
            max_retries=retry_strategy,
            pool_connections=10,
            pool_maxsize=10,
            pool_block=True
        )

        self.session.mount("http://", adapter)
        self.session.mount("https://", adapter)

        logger.info("API client session configured")

    def _make_request(
        self,
        method: str,
        endpoint: str,
        **kwargs
    ) -> APIResponse:
        """Make HTTP request with comprehensive logging and error handling"""
        url = f"{self.base_url}{endpoint}"

        # Prepare request data for logging
        request_data = {
            "method": method,
            "url": url,
            "headers": dict(self.session.headers),
            "timestamp": datetime.now().isoformat(),
            **kwargs
        }

        if "json" in kwargs:
            request_data["json"] = kwargs["json"]
        if "data" in kwargs:
            request_data["data"] = kwargs["data"]
        if "params" in kwargs:
            request_data["params"] = kwargs["params"]
        if "files" in kwargs:
            request_data["files"] = "[FILE_DATA]"  # Don't log actual file data

        logger.info(f"Making {method} request to {url}")

        try:
            start_time = time.time()
            response = self.session.request(method, url, **kwargs)
            elapsed_time = time.time() - start_time

            # Log response details
            logger.debug(f"Response status: {response.status_code}")
            logger.debug(f"Response time: {elapsed_time:.2f}s")

            # Parse response body
            content_type = response.headers.get('Content-Type', '')

            try:
                if 'application/json' in content_type:
                    body = response.json()
                else:
                    body = response.text
            except ValueError:
                body = response.content

            # Create API response object
            api_response = APIResponse(
                status_code=response.status_code,
                headers=dict(response.headers),
                body=body,
                elapsed_time=elapsed_time,
                request=request_data,
                cookies=dict(response.cookies),
                encoding=response.encoding,
                content_type=content_type
            )

            # Add to history
            self.request_history.append({
                "request": request_data,
                "response": {
                    "status_code": response.status_code,
                    "elapsed_time": elapsed_time,
                    "headers": dict(response.headers)
                }
            })

            # Keep history size manageable
            if len(self.request_history) > self.max_history_size:
                self.request_history = self.request_history[-self.max_history_size:]

            # Log error responses
            if response.status_code >= 400:
                logger.warning(
                    f"API error {response.status_code} for {method} {url}: {body}"
                )

            return api_response

        except requests.exceptions.RequestException as e:
            logger.error(f"Request failed: {e}")
            raise APIError(f"Request failed: {str(e)}")
        except Exception as e:
            logger.error(f"Unexpected error during request: {e}")
            raise

    # CRUD operations
    def get(self, endpoint: str, **kwargs) -> APIResponse:
        """GET request"""
        return self._make_request("GET", endpoint, **kwargs)

    def post(self, endpoint: str, **kwargs) -> APIResponse:
        """POST request"""
        return self._make_request("POST", endpoint, **kwargs)

    def put(self, endpoint: str, **kwargs) -> APIResponse:
        """PUT request"""
        return self._make_request("PUT", endpoint, **kwargs)

    def patch(self, endpoint: str, **kwargs) -> APIResponse:
        """PATCH request"""
        return self._make_request("PATCH", endpoint, **kwargs)

    def delete(self, endpoint: str, **kwargs) -> APIResponse:
        """DELETE request"""
        return self._make_request("DELETE", endpoint, **kwargs)

    def head(self, endpoint: str, **kwargs) -> APIResponse:
        """HEAD request"""
        return self._make_request("HEAD", endpoint, **kwargs)

    def options(self, endpoint: str, **kwargs) -> APIResponse:
        """OPTIONS request"""
        return self._make_request("OPTIONS", endpoint, **kwargs)

    # Authentication methods
    def login(self, username: str, password: str) -> str:
        """Authenticate and get token"""
        endpoint = "/auth/login"
        payload = {
            "username": username,
            "password": password
        }

        response = self.post(endpoint, json=payload)

        if response.status_code == 200:
            token = response.body.get("token")
            if token:
                self.session.headers["Authorization"] = f"Bearer {token}"
                logger.info("Authentication successful")
                return token

        raise AuthenticationError(f"Login failed: {response.body}")

    def logout(self):
        """Clear authentication"""
        if "Authorization" in self.session.headers:
            response = self.post("/auth/logout")
            if response.status_code == 200:
                del self.session.headers["Authorization"]
                logger.info("Logged out successfully")

    def refresh_token(self, refresh_token: str) -> Dict[str, str]:
        """Refresh access token"""
        payload = {"refresh_token": refresh_token}
        response = self.post("/auth/refresh", json=payload)

        if response.status_code == 200:
            return response.body

        raise AuthenticationError(f"Token refresh failed: {response.body}")

    # Validation methods
    def validate_response_schema(self, response: APIResponse, schema: Dict) -> bool:
        """Validate response against JSON schema"""
        try:
            jsonschema.validate(instance=response.body, schema=schema)
            logger.debug("Schema validation passed")
            return True
        except jsonschema.ValidationError as e:
            logger.error(f"Schema validation failed: {e}")
            raise ValidationError(f"Schema validation failed: {e}")

    def validate_response_model(self, response: APIResponse, model: BaseModel) -> BaseModel:
        """Validate response against Pydantic model"""
        try:
            validated_model = model(**response.body)
            logger.debug(f"Model validation passed for {model.__name__}")
            return validated_model
        except ValidationError as e:
            logger.error(f"Model validation failed: {e}")
            raise ValidationError(f"Model validation failed: {e}")

    def validate_status_code(self, response: APIResponse, expected_code: int) -> bool:
        """Validate response status code"""
        if response.status_code != expected_code:
            raise AssertionError(
                f"Expected status code {expected_code}, got {response.status_code}"
            )
        return True

    # Performance monitoring
    def assert_response_time(self, response: APIResponse, max_time: float) -> bool:
        """Assert response time is within limit"""
        assert response.elapsed_time <= max_time, \
            f"Response time {response.elapsed_time:.2f}s exceeds limit {max_time}s"
        return True

    def get_performance_metrics(self) -> Dict[str, Any]:
        """Get performance metrics from request history"""
        if not self.request_history:
            return {}

        response_times = [r["response"]["elapsed_time"] for r in self.request_history]
        status_codes = [r["response"]["status_code"] for r in self.request_history]

        return {
            "total_requests": len(self.request_history),
            "avg_response_time": sum(response_times) / len(response_times),
            "min_response_time": min(response_times),
            "max_response_time": max(response_times),
            "success_rate": sum(1 for code in status_codes if code < 400) / len(status_codes) * 100,
            "status_code_distribution": {
                code: status_codes.count(code) for code in set(status_codes)
            }
        }

    # File operations
    def upload_file(self, endpoint: str, file_path: str, 
                   field_name: str = "file", extra_data: Optional[Dict] = None) -> APIResponse:
        """Upload a file with multipart form data"""
        with open(file_path, 'rb') as file:
            files = {field_name: file}
            data = extra_data or {}
            return self.post(endpoint, files=files, data=data)

    def download_file(self, endpoint: str, save_path: str) -> bool:
        """Download a file"""
        response = self.get(endpoint, stream=True)

        if response.status_code == 200:
            with open(save_path, 'wb') as file:
                for chunk in response.iter_content(chunk_size=8192):
                    if chunk:
                        file.write(chunk)
            logger.info(f"File downloaded to {save_path}")
            return True

        logger.error(f"File download failed with status {response.status_code}")
        return False

    # Rate limiting and retry handling
    def handle_rate_limit(self, response: APIResponse) -> bool:
        """Handle rate limiting with exponential backoff"""
        if response.status_code == 429:
            retry_after = response.headers.get('Retry-After')
            wait_time = int(retry_after) if retry_after else 5

            logger.warning(f"Rate limited. Waiting {wait_time} seconds...")
            time.sleep(wait_time)
            return True

        return False

    def wait_for_condition(self, condition_func: Callable[[], bool], 
                          timeout: int = 30, interval: float = 1) -> bool:
        """Wait for condition to be true (useful for async operations)"""
        end_time = time.time() + timeout

        while time.time() < end_time:
            if condition_func():
                return True
            time.sleep(interval)

        raise TimeoutError(f"Condition not met within {timeout} seconds")

    # Batch operations
    def batch_requests(self, requests: List[Tuple[str, str, Dict]]) -> List[APIResponse]:
        """Execute multiple requests in sequence"""
        responses = []

        for method, endpoint, kwargs in requests:
            response = self._make_request(method, endpoint, **kwargs)
            responses.append(response)

            # Handle rate limiting
            if self.handle_rate_limit(response):
                # Retry the same request after rate limit wait
                response = self._make_request(method, endpoint, **kwargs)
                responses[-1] = response

        return responses

# Custom exceptions
class APIError(Exception):
    """Base API exception"""
    pass

class AuthenticationError(APIError):
    """Authentication failed"""
    pass

class ValidationError(APIError):
    """Response validation failed"""
    pass

class RateLimitError(APIError):
    """Rate limit exceeded"""
    pass

class TimeoutError(APIError):
    """Operation timeout"""
    pass

