                <p><span class="medium">Medium: {{ report.scan_results.summary.medium }}</span></p>
                <p><span class="low">Low: {{ report.scan_results.summary.low }}</span></p>
                <p><span class="info">Info: {{ report.scan_results.summary.info }}</span></p>

                <h3>Risk Assessment</h3>
                <p><strong>Risk Score:</strong> {{ report.risk_assessment.risk_score|round(2) }}</p>
                <p><strong>Risk Level:</strong> <span class="{{ report.risk_assessment.risk_level|lower }}">{{ report.risk_assessment.risk_level }}</span></p>
                <p>{{ report.risk_assessment.assessment }}</p>
            </div>

            <h2>Compliance Status</h2>
            <table>
                <tr>
                    <th>Standard</th>
                    <th>Status</th>
                </tr>
                {% for standard, passed in report.compliance.items() %}
                <tr>
                    <td>{{ standard|upper }}</td>
                    <td class="{{ 'compliance-pass' if passed else 'compliance-fail' }}">
                        {{ 'PASS' if passed else 'FAIL' }}
                    </td>
                </tr>
                {% endfor %}
            </table>

            <h2>Vulnerabilities Found</h2>
            {% if report.scan_results.vulnerabilities %}
                {% for vuln in report.scan_results.vulnerabilities %}
                <div class="vulnerability {{ vuln.severity }}-bg">
                    <span class="severity-badge {{ vuln.severity }}-badge">{{ vuln.severity|upper }}</span>
                    <h3>{{ vuln.type|replace('_', ' ')|title }}: {{ vuln.description }}</h3>
                    <p><strong>Endpoint:</strong> {{ vuln.endpoint }}</p>
                    {% if vuln.payload %}<p><strong>Payload:</strong> <code>{{ vuln.payload }}</code></p>{% endif %}
                    {% if vuln.evidence %}<p><strong>Evidence:</strong> {{ vuln.evidence }}</p>{% endif %}
                </div>
                {% endfor %}
            {% else %}
                <p>No vulnerabilities found! 🎉</p>
            {% endif %}

            <h2>Recommendations</h2>
            <ul>
                {% for recommendation in report.recommendations %}
                <li>{{ recommendation }}</li>
                {% endfor %}
            </ul>
        </body>
        </html>
        """

        import jinja2
        from datetime import datetime

        template = jinja2.Template(html_template)
        return template.render(report=report, datetime=datetime)

public WebElement waitForElementWithText(WebDriver driver, By locator, String expectedText, int timeout) {
